window.__D("text/torat-chaim/c015",{"p":[[2300540489,"ניכרים במציאות כלל, והב' בחי' התפשטות דבחי' כתר של כל ספי' שהוא בבחי' ההתחלקות דוקא כנ\"ל, ושרש נשמת משה הי' מבחי' ההתכללות דע\"ס בעצמות שע\"כ א' ונחנו מ\"ה ממש בעצם שאינו במציאות כלל וכלל היפך ההתחלקות דע\"ס דעיגולים זה תחת זה כו', וזהו פי' [משה] מה שמו<sup data-n=\"2055\">148</sup> כו', וגם הרי נמשך משם לבחי' עולם התיקון דאדם כמ\"ש העם אשר אנכי בקרבו כמ\"ש מן המים<sup data-n=\"2056\">149</sup> <span data-k=\"pg\">סה</span> ּ משיתיהו בע\"כ, דמצד בחי' הכלים דתיקון יש בהם בחי' התכללות דתחב\"ס וסוב\"ת כנ\"ל שלמעלה מהתכללות דע\"ס דעצמות ג\"כ כנ\"ל בפי' אדם אדמה לעליון ממש שהוא בעצמות א\"ס ב\"ה ממש דלאו מאינון מדות כלל שנק' יחיד ממש שהוא עצם אור פשוט בתכלית הפשיטות כו' שלמעלה מאחד<sup data-n=\"2057\">150</sup> שאינו רק יחוד והתכללות דע\"ס בעצמות וד\"ל.\n<b>ובזה</b> יובן מ\"ש והאיש משה עניו מאד מכל האדם כו' דקדק לומר מכל האדם אשר ע\"פ האדמה דוקא ולא מן המלאכים<sup data-n=\"2058\">151</sup> כו', לפי שהי' עניו מב' סיבות אחד מצד שורש מקורו העצמי בבחי' מ\"ע דהיינו בחי' התכללות דע\"ס בעצמות כנ\"ל (וזהו והמים אשר מעל השמים<sup data-n=\"2059\">152</sup> ונק' ים הקדמוני כו' שלמעלה מעיגולים דתהו כנ\"ל) שהוא בחי' מ\"ה בעצם כנ\"ל, והב' הי' עניו מכל האדם דוקא שהוא כאשר ירד ונמשך לבחי' עולם התיקון דאדם ששם מצד בחי' ההתכללות דכלים דאדם דומה לעליון ממש מלמעלה גם משרש ההתכללו'<sup data-n=\"2060\">153</sup> דע\"ס בעצמות כנ\"ל, ע\"כ הי' שם עניו ושפל בעצמו יותר. וזהו מכל האדם אשר ע\"פ האדמה דוקא, כשראה בסוף מה שאין בראש עד מבלי ימצא ראש וסוף רק ע\"י אמצעות כולם כשמקבלים זה מזה הרי הוא עצם אור יחיד פשוט שבזה דומה לעליון ממש ה\"ז למעלה גם מבחי' מה שלו שהי' קודם שלא הי' רק כאלו אינו במציאות, אבל לא בבחי' אין האמיתי דעצמות ממש, וע\"כ הי' עניו מכל האדם דבחי' התיקון דוקא מצד בחי' הכלים שבהם שהוא באמת שפל הרבה במדרגה מהם מטעם זה (אבל לא ממלאכים שהן בבחי' עיגולים דתהו כאופנים וחיות הקדש כידוע, שהוא נעלה מהם להיותו בבחי' מ\"ה דבחי' התכללות",[["2055","148","<b>[משה] מה שמו</b>: נסמן לעיל מג, ג."],["2056","149","<b>המים</b>: זט: המ\"ע."],["2057","150","<b>יחיד. . שלמעלה מאחד</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קלה וע' רמט. לקמן פ' בשלח רג, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">ש\"א נה, ב</a>. מאמרי אדה\"א בראשית ע' תק. וש\"נ. הנחות תקע\"ז ע' רי. סה\"מ מלוקט ח\"ד ע' סט. וש\"נ."],["2058","151","<b>ולא מן המלאכים</b>: ראה ספרי בהעלותך יב, ג."],["2059","152","<b>והמים אשר מעל השמים</b>: תהלים קמח, ד."],["2060","153","<b>מלמעלה גם משרש ההתכללו'</b>: אב: שלמעלה גם משרש משה בהתכללו'."]]],[2300540507,"דע\"ס בעצמות כנ\"ל וד\"ל). וזהו שא' ורוח אלקים מרחפת ע\"פ המים בחי' מ\"ע כו' זהו רוחו של משה ומשיח<sup data-n=\"2061\">154</sup>, פי' רוחו של משה<sup data-n=\"2062\">155</sup> הוא בחי' מ\"ע הנ\"ל, ורוח אלקים מרחפת ע\"פ המים עליונים זהו רוחו של משיח שלמעלה ממשה להיותו בא אחר תשלום בחי' התיקון דאדם כמ\"ש ישכיל עבדי כו' וגבה מאד למעלה מאדם<sup data-n=\"2063\">156</sup> והוא מ\"ה שאדם אדמה לעליון ממש כנ\"ל וכידוע בפי' אד\"ם אדם דוד משיח<sup data-n=\"2064\">157</sup> כו', וזהו שא' שלח נא ביד תשלח, שכוונתו הי' על משיח<sup data-n=\"2065\">158</sup> כידוע מטעם הנ\"ל וד\"ל.\n[ז] <b>ובכ\"ז</b> יובן מ\"ש משה אל ה' לא איש דברים אנכי כו', כי כבד פה וכבד לשון אנכי, דהנה ידוע בשורש ענין פה ולשון שזהו עיקר בחי' מדבר דאדם דבחי' התיקון<sup data-n=\"2066\">159</sup> דוקא כידוע דנפש השכלית דוקא הוא הנק' נפש המדברת<sup data-n=\"2067\">160</sup>, להיותו ששרש כח החכמה דאדם שם מ\"ה הוא בבחי' הפה ולשון שהוא המביא אור החכמה לגילוי דוקא וכמו פיה פתחה בחכמה<sup data-n=\"2068\">161</sup> כו' וכמ\"ש ויהי האדם לנפש חי' ות\"א לרוח ממללא<sup data-n=\"2069\">162</sup> כו'. וענין הדבור ידוע שהוא רק הצירופי' של האותיות יחד באופנים שונים שהוא ע\"י חכ' כמ\"ש מצרף לחכ'<sup data-n=\"2070\">163</sup>, דאבא יסד ברתא<sup data-n=\"2071\">164</sup> כידוע, והרי יש בדבור בה' מוצאות הפה דבר והיפוכו ממש שהוא ההתחלקות וההתכללות, שהרי עיקר האותיות באים בבחי' ההתחלקות דוקא כל אות בפ\"ע מכל מוצא כמו אחה\"ע מהגרון גיכ\"ק מהחיך כו' והן ה\"ג המחלקים<sup data-n=\"2072\">165</sup> כידוע, והיפוכו הוא ענין הצירוף של האותיות מכל מוצא יחד בתיבה א' כמו תיבת ברוך הב' מבומ\"ף משפתים והרי\"ש מן זסשר\"ץ<sup data-n=\"2073\">166</sup> משינים נקבצים יחד וכה\"ג, והיינו התכללות מה' מוצאות הפה ע\"פ בחי' חכ' <span data-k=\"pg\">132</span> ּ המצרף ממילא כו' והן בחי' ה\"ח שבדבור כלול מחו\"ג<sup data-n=\"2074\">167</sup> כידוע וממוצ[ע] הוא בחי' רוח ממללא כו' וזהו כדמיון התכללות כחות האברים אשר יצאו<sup data-n=\"2075\">168</sup> מפורדים זת\"ז דוקא כנ\"ל, וע\"כ זהו עיקר בחי' אדם דתיקון בפנימיות הנפש כמו שהוא בחיצוני' ברמ\"ח אברים מצד הכלים דוקא כנ\"ל, כך הוא מצד כלי הפה בדבור בה' מוצאות הפה המתחלק ומתכלל דוקא שהוא עיקר בחי' מדבר כנ\"ל, וע\"כ<sup data-n=\"2076\">169</sup> יש בזה שלימות יותר מעצם האורות דנפש אחר שבפה הכל מתכללים (כמו רצון ושכל ומדות",[["2061","154","<b>ורוח אלקים מרחפת. . ומשיח</b>: בראשית א, ב. ראה ב\"ר פ\"ב, ד. פ\"ח, א. ויק\"ר פי\"ד, א. מאמרי אדה\"א ויקרא ח\"א ע' קצה. לקמן פ' בשלח קנד, א."],["2062","155","<b>מרחפת ע\"פ המים. . רוחו של משה</b>: ראה גם הנחת כ\"ק אדה\"א כאן (שנסמן בריש המאמר). מאמרי אדה\"א שמות ח\"ב ע' שצה. ויקרא שם."],["2063","156","<b>ישכיל עבדי. . מאד למעלה מאדם</b>: ישעי' נב, יג. ראה לקו\"ת להאריז\"ל פ' תשא עה\"פ (לג, ה) ועתה הורד עדיך. מאמרי אדה\"א קונטרסים ע' דש. וש\"נ. ש\"א מ, א. נא, ב. סה\"מ תרל\"ה ח\"א ע' רסו. לקמן פ' תצוה שלב, א."],["2064","157","<b>אד\"ם אדם דוד משיח</b>: רקאנטי בראשית א, כו. ספר הגלגולים פס\"ב בשם ספר הקנה. לקמן פ' בשלח קס, ד. תצוה שלב, א. ויקהל תכב, ג. מאמרי אדה\"א דברים ח\"א ע' לד. וש\"נ. הנחות תקע\"ז ע' ו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670201\" data-slug=\"torat-chaim\" data-id=\"2300670201\">תו\"ח בראשית לב, ד</a> ובהנסמן לשם בהערה 51."],["2065","158","<b>שלח נא. . על משיח</b>: נסמן לעיל מד, ב."],["2066","159","<b>פה. . דבחי' התיקון</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680079\" data-slug=\"torat-chaim\" data-id=\"2300680079\">תו\"ח וישלח קפח, ד</a> שמציין ”בענין מי שם פה לאדם\" (מאמרים שנסמנו בריש המאמר כאן)."],["2067","160","<b>דנפש השכלית. . הנק' נפש המדברת</b>: ראה גם לקמן פ' בשלח רב, א. תצוה שכז, סע\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670601\" data-slug=\"torat-chaim\" data-id=\"2300670601\">תו\"ח נח עט, ג</a>."],["2068","161","<b>פיה פתחה בחכמה</b>: משלי לא, כו."],["2069","162","<b>ויהי האדם. . לרוח ממללא</b>: בראשית ב, ז. ראה תו\"ח נח שם ובהנסמן לשם."],["2070","163","<b>כמ\"ש מצרף לחכ'</b>: כ\"ה בכ\"מ — ראה הנסמן במאמרי אדה\"א נ\"ך ע' קכ. קונטרסים ע' תקמז. לעיל יב, א."],["2071","164","<b>דאבא יסד ברתא</b>: ראה זהר (רעיא מהימנא) פינחס רנו, ב. רמח, א. רנח, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670260\" data-slug=\"torat-chaim\" data-id=\"2300670260\">תו\"ח בראשית כב, ג</a> ובהנסמן לשם. לעיל יב, א."],["2072","165","<b>בה' מוצאות. . ה\"ג המחלקים</b>: ראה ס\"י פ\"ב, מ\"ג. ע\"ח (שער דרושי הצלם) שכ\"ה, דרוש ב. שער מאמרי רשב\"י לאד\"ז רצה, א (רצז, א). שעהיוה\"א ספ\"ד."],["2073","166","<b>אחה\"ע. . זסשר\"ץ</b>: ראה ס\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' קה."],["2074","167","<b>שבדבור </b>[אב: שהדיבור]<b> כלול מחו\"ג</b>: נסמן לקמן פ' בא קו, ד הערה 435."],["2075","168","<b>אשר יצאו</b>: זט: אחר שיצאו."],["2076","169","<b>וע\"כ</b>: זט: וא\"כ."]]],[2300540525,"ומחשבה שהכל מתגלה בדבור שנק' פתח כמו פיה פתחה בחכמה כו') מבלי שימצא ראש וסוף עד שהראש דחכ' ורצון ותענוג מקבל מדיבור, כמו שאנו רואים שבדיבור ניתוסף עצם כח השכל והרצון ותענוג מה שלא הי' בתחלה כלל (כמ\"ש במ\"א בענין בינה יתירה ניתנה באשה<sup data-n=\"2077\">170</sup> כו'), וזהו עיקר אדם אדמה לעליון שהוא למעלה בבחי' עצמות המאציל ממש כו' שבפה העליון בדבור שם נעוץ תחלת הכל כו' וכנ\"ל ברגל<sup data-n=\"2078\">171</sup> שאין בראש כו' וד\"ל.\n<b>ואמנם</b> הנה הדיבור מצד עצמו הרי הוא בבחי' יש ודבר במציאות מורגש במבטא שהוא גילוי השכל ומדות הכל במורגש ונק' סוף הכל כידוע, וראי' לזה שאם השכל עמוק מן ההשגה כמו שהוא בבחי' אין שהוא משכיל כו' א\"א לבוא בגילוי הדבור כלל וכלל והוא בחי' פנימיות כח מ\"ה דחכ' שנק' פלא כו'. וכן גם הרצון ומדות כמו שהן כלולים בעצמות הנפש ממש א\"א שיבואו בגילוי בדבור כלל, כמו אין מלה בלשוני כו' בש\"ע<sup data-n=\"2079\">172</sup> כאשר מתבטל ממציאותו לגמרי שנכללו כחות הנפש בעצמו ונשאר בבחי' דומם עד שאינו יכול לדבר כלל כו' (וכידוע במעשה דבעש\"ט<sup data-n=\"2080\">173</sup> ז\"ל שהתפלל כמה תפלות בע\"ש שיוכל לענות לשואלו<sup data-n=\"2081\">174</sup> דבר מעוצם ביטולו והתכללותו למעלה מעלה). וכמו העומד לפני המלך ממש שלא יכול לדבר דבר כו', וכתלמיד לפני רבו דאיידי דטריד למיבלע<sup data-n=\"2082\">175</sup> לא פליט כו', וכידוע שבחי' הדבור הוא כאשר יצא מהיכל המלך שיספר כל מה שראה בהיכל המלך, וזהו ענין שירות ותשבחות דדוד המלך שהוא בבחי' דיבור כו'. וכך הוא למעלה ביו\"ד מא' כמ\"ש בס\"י וקבען בפה<sup data-n=\"2083\">176</sup> שהוא ח\"ת שבדבור שמחי' את הכל מאין ליש להיותו בחי' היש דחכ' שבראש (וכן טעם<sup data-n=\"2084\">177</sup> הדיבור בד\"ת כמו פיה פתחה בחכ' פתח בחכ' כמו פתח ר\"פ<sup data-n=\"2085\">178</sup> כו' דכל פתח בחכ' שיוכל לבוא לגילוי אבל לא רזא דרזין<sup data-n=\"2086\">179</sup> סוד סתום השכל הנעלם מכל רעיון<sup data-n=\"2087\">180</sup> שא\"א לבא בדבור כלל (והוא ענין סייג לחכ' שתיקה<sup data-n=\"2088\">181</sup> דמלה בסלע ומשתוקא בתרין<sup data-n=\"2089\">182</sup> כידוע שזהו בחי' כתר שבכתר למעלה גם מח\"ס שבא לגילוי מן ההעלם כו'). ולמעלה הוא בחי' סדכ\"ס דלית מח' תפיסא בי'<sup data-n=\"2090\">183</sup> שא\"א לבא בפה העליון כו' וד\"ל.",[["2077","170","<b>בינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. מאמרי אדה\"ז תקס\"ד ע' נ. פרשיות התורה ח\"א ע' נה. דרך חיים שער התפלה ע' 120."],["2078","171","<b>וכנ\"ל ברגל</b>: אב: ויש ברגל מה."],["2079","172","<b>אין מלה בלשוני כו' בש\"ע</b>: תהלים קלט, ד. ראה מאמרי אדה\"א קונטרסים ע' שז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, סע\"ב</a> ובהערה 21."],["2080","173","<b>במעשה דבעש\"ט </b>[א: דהבעש\"ט]: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680384\" data-slug=\"torat-chaim\" data-id=\"2300680384\">תו\"ח ויחי רמט, ג</a> ובהערה 40. סה\"מ תרל\"ג ח\"א ע' סו. וש\"נ."],["2081","174","<b>לשואלו</b>: א: מה שישאלוהו. ב: שישאלוהו."],["2082","175","<b>דאיידי דטריד למיבלע</b>: ראה חולין קח, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצה. תו\"ח נח סג, ג הערה 44."],["2083","176","<b>כמ\"ש בס\"י וקבען בפה</b>: ראה שם פ\"ב, מ\"ג."],["2084","177","<b>טעם</b>: זט: גם."],["2085","178","<b>פיה. . פתח בחכ' כמו פתח ר\"פ</b>: ראה אמ\"ב פתח השער ח, סע\"ב ואילך. לקמן פ' ויקהל שפז, ד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מב."],["2086","179","<b>רזא דרזין</b>: לשון הזהר בכ\"מ. ראה זהר בראשית מה, ב."],["2087","180","<b>השכל הנעלם מכל רעיון</b>: ראה פיוט אל מסתתר. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' עתר ובהנסמן במראי מקומות לשם. מאמרי אדה\"א בראשית ע' ח. וש\"נ."],["2088","181","<b>סייג לחכ' שתיקה</b>: אבות פ\"ג, מי\"ג. ראה גם לקמן פ' יתרו רסז, ד. תצוה שמז, ג."],["2089","182","<b>דמלה בסלע ומשתוקא בתרין</b>: ראה מגילה יח, א. לקמן פ' בשלח קמג, א. מאמרי אדה\"א נ\"ך ע' שנח ואילך. וש\"נ. תו\"ח ח\"ש קמ, ד."],["2090","183","<b>סדכ\"ס דלית מח' תפיסא בי'</b>: זהר יתרו פט, א. תרומה קמו, ב. תקו\"ז בהקדמה יז, א."]]],[2300540543,"<b>וזהו</b> שא' משה שהי' שורש נשמתו בבחי' ההתכללות דא\"ס דעצמות ממש כנ\"ל שזהו ונחנו מ\"ה בעצם כנ\"ל, לא איש דברים אנכי להיות שלא הי' יכול לבא בגילוי בבחי' גילוי בפה הדבור כלל, להיותו בבחי' ההעלם דהעלם שא\"א להביא העלם המח' וחכ' בדיבור, ולכן נק' כבד פה וכבד לשון בתושבע\"פ ושבכ'<sup data-n=\"2091\">184</sup> ג\"כ, כי בחי' פה ולשון דתושב\"כ ושבע\"פ הוא אשר בא לידי גילוי אותיות עכ\"פ ובחי' משה הי' ממ\"ע שהוא בחי' פנימיות ח\"ע הכלולה בעצמות ממש שא\"א לבוא בגילוי הדבור <span data-k=\"pg\">סו</span> ּ כלל כו' וד\"ל. ועכ\"ז אדרבה מזה עצמו הי' שפל ועניו מכל האדם כו' דכאשר ירד מבחי' ההעלם שבעצמות לבחי' התיקון דהיינו חכמה שבדבור הנ\"ל, ראה יתרון מעלה רבה בבחי' התיקון דאדם בבחי' הדיבור דוקא שיש בזה בחי' השלימות העליון שלמעלה גם מהתכללות דע\"ס בעצמות והוא בעצמות ממש כנ\"ל (והוא בבחי' דבור שזהו עיקר בחי' מדבר כנ\"ל שלזה הטעם האדם הוא בעל בחירה<sup data-n=\"2092\">*185</sup> דוקא ומושל בכל דצ\"ח בבחי' יש גמור להיות[ו] דומה לעליון ממש שהוא בחי' יש האמיתי כמ\"ש במ\"א בענין חנוך ומשיח<sup data-n=\"2093\">185</sup>. וזהו בחי' משיח דכתי' בי' ורוח אלקים מרחפת נוגע ואינו נוגע שהוא מטי ולא מטי שמזה שרש התהוות הכלים דוקא כנ\"ל). ע\"כ אמר כבד פה בבחי' ענוה גדולה שלא הי' יכול להגיע לשלימות זה דפה העליון דאדם דתיקון מטעם זה אמר שלח נא כו' שהוא משיח שהוא בבחי' כלים דאדם דוקא כנ\"ל וד\"ל.\n[ח]<sup data-n=\"2094\">186</sup> <b>ויאמר</b> ה' אליו מי שם פה לאדם כו' השיב למשה על טענתו כמ\"ש<sup data-n=\"2095\">187</sup> כי כבד פה כו', לפי ששרש נשמתו אינו מבחי' הכלים דאדם דבחי' התיקון כנ\"ל וע\"כ הי' עניו מכל האדם דוקא כנ\"ל, הלא מי אשר שם פה לאדם כו', פי' לאדם בקמץ תחת הלמ\"ד שמורה על אדם הידוע<sup data-n=\"2096\">188</sup> והוא בחי' אדם העליון דאצי' שעל הכסא כו' שהוא בחי' אדם דיושר דבחי' התיקון כו', הלא אנכי ה' בחי' מהו\"ע א\"ס ב\"ה ממש, שעלה ברצונו הפשוט שבעצמות ממש שיהי' כח העליון הזה בבחי' כלים דאדם שכללותו הוא בחי' הפה המדבר כנ\"ל, א\"כ יוכל להיות הרצון הזה הקדום שיהי' בפיך ג\"כ בחי' כח העליון הזה, וז\"ש אנכי אהי' עם פיך כו' הגם שנתמשך<sup data-n=\"2097\">189</sup> מבחי' מ\"ע דהעלם בעצמות שלזה הוא כבד פה כנ\"ל.",[["2091","184","<b>כבד פה וכבד לשון בתושבע\"פ ושבכ'</b>: שמות ד, י. ראה זהר (רעיא מהימנא) צו כח, רע\"א. מאמרי אדה\"א דברים ח\"ג ע' תתצו. וש\"נ. שמות ח\"ב ע' שלא ואילך. וש\"נ. נ\"ך ע' ס. לעיל יב, ב. יט, ד. לקמן פ' וארא פ, ב. בשלח ריז, א. יתרו רנו, ג. תצוה שכג, ג. שמז, א. פקודי תס, ד."],["2092","*185","<b>האדם הוא בעל בחירה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380239\" data-slug=\"likkutei-torah\" data-id=\"4001380239\">לקו\"ת אמור לח, ב</a>. עטרת ראש ע' 84. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680349\" data-slug=\"torat-chaim\" data-id=\"2300680349\">תו\"ח תולדות קנה, א</a> ואילך."],["2093","185","<b>בענין חנוך ומשיח</b>: ראה גם לעיל כט, ב ובהערה 91."],["2094","186","<b>(ח)</b>: ד: (ו)."],["2095","187","<b>כמ\"ש</b>: אד: במה שאמר."],["2096","188","<b>לאדם בקמץ תחת הלמ\"ד שמורה על אדם הידוע</b>: ראה גם המאמרים שנסמנו בריש המאמר. מאמרי אדה\"ז תקס\"ג ח\"א ע' קלא. לקמן פ' וארא פא, ב. ד\"ה מי שם פה תשי\"ט (סה\"מ תשי\"ט ע' 599) ושם: הנה הלמ\"ד היא קמוצה והרי זה כמ\"ש האדם בה\"א הידיעה."],["2097","189","<b>שנתמשך</b>: זט: שנשמתך."]]],[2300540560,"<b>וביאור</b> הענין הנה מבואר למעלה ששורש התהוות הכלים<sup data-n=\"2098\">190</sup> קדם לשרש התהוות האורות (וכמו ציור אברים בבטן שקדם להתהוות הצורה, שבנין הכלים קודם לבנין האור כו'), והענין הוא שציור אדם באברים עלה תחלה ברצון הקדום שהוא כלול בעצמות א\"ס ממש. ויובן זה ע\"פ הידוע שז\"א נק' אנפי זוטרי<sup data-n=\"2099\">191</sup> כמשל הרביא לגבי האדם הגדול, כמו שכל אריכות הבנין או כדור הארץ מצטייר בלוח קצר מאד וכשונה לתלמידו דרך קצרה<sup data-n=\"2100\">192</sup> כו', אבל יש בקיצור מכל מה שבאריכות היותר מופלג. וזהו אדמה לעליון לאדם הגדול שזהו בחי' א\"ק בכללות, וידוע שזהו כל בחי' האריכות דמדות וחכ' ורצון ותענוג שבא מאור העצמות בבחי' רצון הפשוט שנק' רצון המוחלט בעצמו טרם שבא להיות בבחי' התפשטות שאין בזה בחי' הגבלה כלל, כי זהו בחי' ע\"ס הגנוזות ממש בעצמות שמאירים כמו שהן ואמנם נתצמצמו מאד לבוא בבחי' קיצור גדול מאד והן ע\"ס דאצי' בכלל שכלולים בז\"א כו', ושם דוקא שרש התהוות הכלים ואברים דז\"א תחלה לאורות שלה (כמו באדה\"ר שעשה ציור גופו קודם ואח\"כ ויפח באפיו<sup data-n=\"2101\">193</sup> נשמת חיים וכמ\"ש נעשה אדם בצלמינו<sup data-n=\"2102\">194</sup> כו' וכנ\"ל דבנין הכלים קדם כו' שזהו עיקר הנק' צלמינו כו', והוא שורש למה שיש כח עליון ביותר בבחי' הכלים בהתכללותם זע\"ז מצד שקרובים יותר לעצמות הא\"ס ברצונו הפשוט ממש, והוא מ\"ש <span data-k=\"pg\">134</span> ּ מי שם פה לאדם הגדול שהוא בחי' א\"ק בכלל שנק' אדם דבריאה בכלל וע\"י וא\"א נק' אדם דיצי' וז\"א נק' אדם דעשי' כידוע בפי' כל הנקרא בשמי<sup data-n=\"2103\">195</sup> ולכבודי בראתיו יצרתיו אף עשיתיו). אך זהו כאשר בא האור מן העצמות להיות בבחי' אדם שיהי' דומה לעליון ממש שזהו דוקא ע\"י בחי' התכללות דכלים, שבאמצעות התכללות<sup data-n=\"2104\">196</sup> יחד דוקא דומה לעצמות, שאין זה יכול להיות באורות שיוצאים מפורדים בבחי' עיגולים דתהו או גם בע\"ס הגנוזות ברצון הפשוט הרי בחי' שרש הכלים קדם כנ\"ל. אבל בבחי' מהו\"ע א\"ס ב\"ה ממש קודם שבא לכלל העלם וגילוי דע\"ס רק כמו שהוא בעצמותו ממש יכול להיות בהיפוך ג\"כ, והוא שיהי' בחי' הכח העליון שבהתכללות אמיתי' באורות דע\"ס גם אחר שיוצאים מחולקים או גם בהתכללותם בעצמות כל מה שיש בכח הכלים דתיקון להיות כמו פה דאדם דתיקון, ושלא יהי' כח זה בכלים דאדם כלל ויהי' להיפך הסדר דעכשיו בתהו ותיקון כמו כי לא אדם הוא להנחם<sup data-n=\"2105\">197</sup> כו' מבחי' דין לחסד ומחסד לדין משום דכל שינוי רצון והתחלפות האורות בא מצד בחי' הכלים דאדם, אבל",[["2098","190","<b>מבואר למעלה ששורש התהוות הכלים</b>: לעיל פ' שמות מו, א."],["2099","191","<b>שז\"א נק' אנפי זוטרי</b>: ראה חגיגה יג, ב (הערה במאמרי אדה\"א דברים ח\"ג ע' תתקא). וראה ג\"כ תו\"א ר\"פ תרומה. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקא. תקס\"ח ח\"א ע' תקסה. שער היחוד קלב, ב. מאמרי אדה\"א קונטרסים ס\"ע שמג ואילך. שם ע' שסב."],["2100","192","<b>וכשונה לתלמידו דרך קצרה</b>: פסחים ג, ב. ראה גם לקמן פ' ויקהל תכד, א. מאמרי אדה\"א הנחות תקע\"ז ע' קמג. וש\"נ. שער האמונה יד, ב. המשך תרס\"ו ע' תא."],["2101","193","<b>ויפח באפיו</b>: בראשית ב, ז."],["2102","194","<b>נעשה אדם בצלמינו</b>: שם א, כו."],["2103","195","<b>א\"ק. . אדם דבריאה. . כל הנקרא בשמי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670542\" data-slug=\"torat-chaim\" data-id=\"2300670542\">תו\"ח בראשית כט, ג</a> ובהנסמן לשם."],["2104","196","<b>התכללות</b>: אבו: התכללותם."],["2105","197","<b>כי לא אדם הוא להנחם</b>: שמואל-א טו, כט."]]],[2300540576,"בעצמיות ממש אין שם התחלפות ושינוי להיותם בבחי' א\"ס ממש והוא בבחי' האורות דוקא. ועכ\"ז הרי הם כלולים זה עם זה בתכלית לפי שהוא ית' שלימותא דכולא<sup data-n=\"2106\">198</sup> ואין דבר משלים אותו לכך יכול להיות מאותו<sup data-n=\"2107\">199</sup> דבר והיפוכו כו', וכמשל התכללות כחות הנפש במהו\"ע הנפש שיוכל להתכלל חסד בדין ודין בחסד מצד עצמות הנפש שמושלל לגמרי מכל כחות שלה גם מרצון ותענוג ע\"כ ממילא לא<sup data-n=\"2108\">200</sup> יוכל להתכלל חו\"ג כו'. וכך הוא בע\"ס הכלולים בעצמות המאציל שכלולים זה עם זה בתכלית להיותם נק' ע\"ס בלי מ\"ה בלי מהות<sup data-n=\"2109\">201</sup> כלל ע\"כ יוכללו ב' הפכים כאחד. וראי' מבחי' הקו\"ח שאחר הצמצום להיותו בבחי' עצמות הא\"ס שקודם הצמצום<sup data-n=\"2110\">202</sup>, ע\"כ יש בכחו לאכללא שמאלא בימינא כו' ולהחליף האורות בכלים שאינו שלהם כמו אור החסד בכלי הגבורה כו', וגם הקו\"ח הזה הרי הוא מקור כל מדידה<sup data-n=\"2111\">203</sup> דאו\"כ בבחי' הגבול דוקא וה\"ז דבר והיפוכו (כמקום ארון אינו מן המדה<sup data-n=\"2112\">204</sup> כו'). ע\"כ יוכל להפוך גם מסדר ההשתלשלו' דתהו ותיקון שנק' עגולים ויושר להיות בחי' התכללות דכלים דיושר בבחי' העגולים דתהו דוקא, אע\"פ שהם זה תחת זה בהתחלקות. מאחר שבעצמות הא\"ס יוכל להיות דבר והיפוכו בע\"ס הגנוזות והתחלקות והתכללות כמו כי לא אדם הוא להנחם שזהו מצד בחי' ההתחלקות דוקא שלא ישונה מדין לחסד לעולם, ובאמת הרי כלולים דין וחסד זה בזה מצד בחי' ההתכללות שבעצמות דלאו מכא\"מ כלל<sup data-n=\"2113\">205</sup> כמשל התכללות כחות הנפש בעצמיות הנפש כו' ומטעם הנ\"ל, א\"כ הרי גם בהתחלקות דעיגולים דתהו והתכללות דיושר דתיקון יוכל להתהפך ממש להיות בחי' התכללות בעיגולים דתהו וההתחלקות ביושר דתיקון, להיותו למעלה מעלה מבחי' ההמשכה דע\"ס לגמרי שיכול להיות דבר והיפוכו כא' (כמו המשפילי לראות בשמים כו' משום דמגביהי לשבת<sup data-n=\"2114\">206</sup>, הגם שהוא דבר והיפוכו דענין מגביהי לשבת הוא במהו\"ע ממש דגם מח' א' שצופה ומביט כל ההשתלשלו' דקו\"ח כו' עד סוף העשי' בסקירה א'<sup data-n=\"2115\">207</sup> גם הוא כלא חשיבא ממש <span data-k=\"pg\">סז</span> ּ לגבי מהו\"ע כו', ועכ\"ז יכול להיות משפילי לראות בשמים כו' בהשגחה פרטית על כל דרכי בנ\"א ולהיות מלך אלקים גם על גוים<sup data-n=\"2116\">208</sup> בהשגחה פרטית משום דאינו נתפס כלל במח' אחת הנ\"ל לפי שמגביהי לשבת כו', וכך יובן בבחי' התהו שיוכל להיות בבחי' התיקון כו'). וזהו מי שם פה לאדם כו', פי' מי שם כח ההתכללות הזאת בבחי' התיקון וכח ההתחלקות בעיגולים דתהו שזהו כסדר ההשתל' שעלה ברצון הקדום דמח' הקדומה כו',",[["2106","198","<b>שהוא ית' שלימותא דכולא</b>: ראה תקו\"ז בהקדמה (יז, ב). עבודת הקדש ח\"א חלק היחוד רפ\"ח."],["2107","199","<b>מאותו</b>: בו: מאיתו."],["2108","200","<b>לא</b>: א: ליתא."],["2109","201","<b>ע\"ס בלי מ\"ה בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["2110","202","<b>הקו\"ח. . עצמות הא\"ס שקודם הצמצום</b>: ראה שער היחוד פט\"ו. לקמן פ' בשלח קנה, ב. קצב, סע\"ג ואילך."],["2111","203","<b>הקו\"ח. . לאכללא. . מקור כל מדידה</b>: ראה שער היחוד שם. לקמן פ' בשלח קע, ג."],["2112","204","<b>כמקום ארון אינו מן המדה</b>: יומא כא, א. ראה מאמרי אדה\"א ויקרא ח\"א ע' קפח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670578\" data-slug=\"torat-chaim\" data-id=\"2300670578\">תו\"ח נח עה, ג</a> ובהערה 38 שם."],["2113","205","<b>דלאו מכא\"מ כלל</b>: ראה תקו\"ז בהקדמה (יז, ב)."],["2114","206","<b>המשפילי לראות. . דמגביהי לשבת</b>: תהלים קיג, ו. ה."],["2115","207","<b>שצופה ומביט. . בסקירה א'</b>: ראה ברכת זכרונות. ר\"ה יח, א. מאמרי אדה\"א נ\"ך ע' קלה. וש\"נ. קונטרסים ע' רא. לקמן פ' בשלח קסג, ג. ויקהל שפט, א."],["2116","208","<b>מלך אלקים. . על גוים</b>: תהלים מז, ט."]]],[2300540592,"הלא אנכי ה' שהי' ברצונו הפשוט שיהי' תחלה בחי' ההתחלקות דעיגולים ואח\"כ ההתכללות דיושר וא\"כ מה שהוא שם כח עליון זה בבחי' כלים דיושר דתיקון הוא מעצמות א\"ס ב\"ה הנק' אנכי. וז\"ש מי שם פה לאדם דתיקון כו' ג\"כ הרי מאנכי זה יוכל להיות להיפך שיהי' הרצון הפשוט שיהי' בנשמת משה שהוא מבחי' העיגולים מבחי' ההתכללות דוקא מבחי' האדם דתיקון, וז\"ש ואנכי אהי' עם פיך שיהי' גם בנשמתך מבחי' פה דאדם דתיקון שיהי' בו כל הכח העליון שבפה דאדם העליון לפי שיכול לעשות שינוי בסדר ההשתל' דתהו ותיקון לעשות מבחי' תהו בחי' תיקון ובחי' התיקון יהי' בחי' התהו כו' מטעם הנ\"ל שיכול להיות דבר והיפוכו מצד בחי' העצמות ממש דלאו מכל אינון מדות כלל וד\"ל.\n[ט]<sup data-n=\"2117\">209</sup> <b>והנה</b> ראי' ומופת לכל זה שיוכל להיות להיפך מתהו תיקון ומתיקון לתהו [הוא] ממה שאמר יעקב והי' הוי' לי לאלקים<sup data-n=\"2118\">210</sup> הרי שם הוי' שהוא בחי' מקיף (שהוא סוכ\"ע בכלל) נעשה אליו בבחי' או\"פ בכלי שהוא שם אלקים, וכן כל התו\"מ הרי הוא להמשיך שם הוי' שיהי' בבחי' אלקים כמ\"ש וידעת היום כו' כי הוי' הוא האלקים<sup data-n=\"2119\">211</sup> כו', וכמו שאנו או' בכל הברכות ברוך אתה הוי' אלקינו מלך שיתברך שם הוי' מבחי' ההעלם לבא לגילוי בבחי' אלקים שיקרא אלקינו ממש כו' (ובנעילה דיוכ\"פ או' ז' פעמים כי הוי' הוא האלקי'<sup data-n=\"2120\">212</sup> בהיפוך שיעלה שם הוי'<sup data-n=\"2121\">213</sup> מלמטה למעלה להיות בבחי' אלקי' שבעליון, וזהו כמו שבחי' התיקון יהי' בבחי' המקיפי' דעיגולים דתהו כידוע)<sup data-n=\"2122\">214</sup>. וזהו היפך דסדר ההשתל' דמקיף ופנימי שמבחי' או\"פ שבעליון נעשה מקיף לתחתון, ומ\"ש והי' הוי' לי לאלקים הרי מקיף נעשה פנימי כו' ומפנימי נעשה מקיף כו'. וזהו שרמז באמרו<sup data-n=\"2123\">215</sup> בנו של רישב\"ל לאביו עולם הפוך ראיתי<sup data-n=\"2124\">216</sup> עליונים למטה שהן בחי' עיגולים דמקיפים נעשה בחי' או\"פ בהגבלה ותחתונים שהן בבחי' פנימי' נעשו למעלה בבחי' מקיף, ואמר לו עולם ברור ראית לפי שכל בחי' שלימות התיקון שנק' עולם ברור היינו כשבחי' מקיפים העליונים נעשו בבחי' או\"פ למטה כו'. וראי' מזה עצמו שמשה הי' מבחי' מקיפי' עליונים דח\"ע",[["2117","209","<b>(ט)</b>: ד: (ז)."],["2118","210","<b>והי' הוי' לי לאלקים</b>: ויצא כח, כא. ראה לקמן פ' וארא סה, ב. מאמרי אדה\"א דברים ח\"ג ע' א'עט. תו\"ח ויצא קסז, ד."],["2119","211","<b>וידעת. . הוי' הוא האלקים</b>: ואתחנן ד, לט. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'סא. בראשית ע' שפה. הנחות תקע\"ז ע' שמו."],["2120","212","<b>ובנעילה. . כי הוי' הוא האלקי'</b>: בהוספת תיבת ”כי\" מובא גם במאמרי אדה\"א בראשית ע' קעג. וש\"נ. הנחות תקע\"ז שם."],["2121","213","<b>ובנעילה. . שיעלה שם הוי'</b>: ראה מאמרי אדה\"א בראשית שם. וש\"נ. נ\"ך ע' כה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540480\" data-slug=\"torat-chaim\" data-id=\"2300540480\">תו\"ח שם קסח, א</a>. לקמן פ' בשלח רלו, א."],["2122","214","<b>כידוע)</b>: ניתוסף ע\"פ אבו."],["2123","215","<b>שרמז באמרו</b>: אב: שרמז. ו: שאמר."],["2124","216","<b>רישב\"ל. . עולם הפוך ראיתי</b>: פסחים נ, א. ב\"ב י, ב (דר' יהושע)."]]],[2300540607,"וירד למטה בבחי' התיקון להיות עיקר ומקור לתו\"מ שהן בבחי' התיקון דאדם, וכמ\"ש וזאת תורת האדם כו' וכתיב תורה צוה<sup data-n=\"2125\">217</sup> לנו משה דוקא וכמו ויקם עדות ביעקב כו'<sup data-n=\"2126\">218</sup> ותורה שם בישראל כו', ואע\"פ שהי' כבד פה וכבד לשון מטעם הנ\"ל שהי' בבחי' מ\"ה ממש כו', הרי במ\"ת כתיב משה ידבר והאלקים<sup data-n=\"2127\">219</sup> כו' משום שא\"ל אנכי אהי' עם פיך כו' כנ\"ל), ולפי<sup data-n=\"2128\">220</sup> שעיקר השראת המקיפים הוא בבחי' הכלים דתו\"מ דוקא וכמ\"ש במ\"א עמ\"ש אחת שאלתי<sup data-n=\"2129\">221</sup> כו' שבתי בבית ה' ואז ממילא יומשכו כל המקיפים לחזות בנועם ה' כו', לפי ששרש הכלים הוא בבחי' המקיפים דוקא, וזהו ענין תפלה <span data-k=\"pg\">136</span> ּ למשה<sup data-n=\"2130\">222</sup> איש האלקי' כו' מעון אתה היית לנו בבחי' המקיף היותר עליון כו', בטרם הרים יולדו שהן מדות דתיקון ובטרם בנין הנוק' שנק' ארץ<sup data-n=\"2131\">223</sup> כו' מעולם עד עולם אתה אל כו', ומעון אותיות נועם<sup data-n=\"2132\">224</sup> והוא מה שמסיים ויהי נועם<sup data-n=\"2133\">225</sup> ה' עלינו כו' לפי שמעשה ידינו בכלים מכלים שונים דתו\"מ כוננהו מטעם הנ\"ל וד\"ל). והוא<sup data-n=\"2134\">226</sup> ענין טעמי תו\"מ שיתגלו לע\"ל ע\"י משיח שהוא בבחי' פנימי' ע\"י<sup data-n=\"2135\">227</sup> כו' ע\"י מעשה המצות דעכשיו שהן רק בחי' כלים, הרי אנו רואים שמבחי' מקיפים עליונים נעשו בבחי' גילוי האור בכלים לע\"ל בימי משיח שזהו היפך סדר ההשתל' דמקיף ופנימי וד\"ל).\n[י]<sup data-n=\"2136\">228</sup> <b>והנה</b> ראי' ומופת ברור [ב]יותר לכל זה הוא מענין כוונת ברכות המצות שהן בחי' מקיפים דוקא, והמצות עצמן הן רק בבחי' כלי להשראת או\"פ<sup data-n=\"2137\">229</sup> כידוע בס' הקבלה. וזהו שמברכים עובר לעשייתן<sup data-n=\"2138\">230</sup> דוקא לפי שע\"י הכוונה שבברכות המצות נמשך בחי' אור המקיף דוקא שעי\"ז יוכל להיות היחו\"ע שבמצוה עצמה, והגם שברכות המצות מד\"ס<sup data-n=\"2139\">231</sup> והמצות עצמן דאוריי' וכמ\"ש במ\"א ע\"פ ישקני מנשיקות פיהו שהן ברכות המצות שמברכים בפה הגם שהן מד\"ס, הרי טובים דודיך<sup data-n=\"2140\">232</sup> שהן ד\"ס יותר מיינה של תורה<sup data-n=\"2141\">233</sup> דפנימי' טעמי המצות שנק' יין כי גימט' סוד<sup data-n=\"2142\">234</sup>, לפי שזה עצמו שיתגלה טעמי וסודות התורה הוא ע\"י המשכת המקיפים דברכות המצות כו'. וזהו ג\"כ ענין מאה ברכות שמברכים בכל יום שהן מקיפי' העליונים דע\"ס דכתר<sup data-n=\"2143\">235</sup>",[["2125","217","<b>תורה צוה</b>: ברכה לג, ד."],["2126","218","<b>ויקם עדות ביעקב כו' </b>[א: ליתא]: תהלים עח, ה."],["2127","219","<b>משה ידבר והאלקים</b>: יתרו יט, יט."],["2128","220","<b>כנ\"ל) ולפי</b>: אזט: כנ\"ל (ולפי."],["2129","221","<b>אחת שאלתי</b>: תהלים כז, ד. ראה ד\"ה זה וביאוריו במאמרי אדה\"ז תקס\"ג ח\"ב ע' תשד ואילך. מאמרי אדה\"א שמות ח\"ב ע' תיא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680228\" data-slug=\"torat-chaim\" data-id=\"2300680228\">תו\"ח וישלח קפג, ד</a>. לקמן פ' בשלח קפב, ב."],["2130","222","<b>תפלה למשה</b>: תהלים צ, א."],["2131","223","<b>בטרם הרים. . מדות. . בנין הנוק' שנק' ארץ</b>: תהלים שם, ב [ושם: ומעולם — ראה לקמן פ' פקודי תנז, א הערה 300]. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תיב. וש\"נ. קונט' דור לדור (מכ\"ק אדה\"א קה\"ת תשנ\"ב) ע' 27."],["2132","224","<b>ומעון אותיות נועם</b>: ראה לקו\"ת להאריז\"ל תהלים שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670483\" data-slug=\"torat-chaim\" data-id=\"2300670483\">תו\"ח נח נה, ב</a> ובהערה 16."],["2133","225","<b>ויהי נועם</b>: תהלים שם, יז."],["2134","226","<b>והוא</b>: א: וזה. בו: וזהו."],["2135","227","<b>משיח. . פנימי' ע\"י</b>: ראה הגהת צמח במבוא שערים ש\"ה ח\"א ספ\"ד. שע\"ת ח\"א נה, ד ובהנסמן לשם. מאמרי אדה\"א נ\"ך ע' ר. וש\"נ. קונטרסים ריש ע' שנב. לקמן פ' בא צו, ג."],["2136","228","<b>(י)</b>: ד: (ח)."],["2137","229","<b>ברכות המצות. . והמצות עצמן. . או\"פ</b>: ראה פע\"ח (שער ספירת העומר) שכ\"ב, קרוב לספ\"ג."],["2138","230","<b>שמברכים עובר לעשייתן</b>: פסחים ז, ב. ראה מאמרי אדה\"א דברים ח\"א ע' קמד ואילך. נ\"ך ע' שדמ. וש\"נ."],["2139","231","<b>שברכות המצות מד\"ס</b>: ראה ברכות טו, א. רמב\"ם הל' ברכות פ\"א, ה\"ב וה\"ג. שו\"ת פאר הדור (להרמב\"ם) סכ\"ו."],["2140","232","<b>ישקני. . טובים דודיך</b>: שה\"ש א, ב. ראה מאמרי אדה\"ז כתובים ח\"ב ע' ז ואילך. לקמן נה, א."],["2141","233","<b>טובים דודיך. . מיינה של תורה</b>: ראה ע\"ז לה, א וברש\"י שם."],["2142","234","<b>יין כי </b>[זט: ליתא]<b> גימט' סוד</b>: ראה עירובין סה, סע\"א."],["2143","235","<b>מאה ברכות. . דע\"ס דכתר</b>: מנחות מג, ב. ראה גם לקמן פ' בשלח קס, ד. יתרו רסח, ג. מאמרי אדה\"ז תקס\"ח ח\"א ע' שצה ואילך. תקס\"ט ע' ל. שע\"ת קלא, א."]]],[2300540621,"כו' וזה פלא גדול לכאורה, אך צ\"ל משום דבחי' הכלים דמעשה המצות שרשם בבחי' מקיפים דוקא כנ\"ל, ע\"כ צריך לברך תחלה להמשיך בחי' המקיף שמזה ממילא יומשך או\"פ בכלי בגוף מעשה המצות כו'. ונמצא מובן עכ\"פ דמצד בחי' הכלים דוקא נמשך בחי' המקיפים (וראי' לזה מתש\"י ותש\"ר, דתש\"י לכ\"ע צריך ברכה לפי שהכלי של תש\"י הוא לבחי' המל' שמקבל מהלב דז\"א צריך להמשיך בחי' מקיף מטעם הנ\"ל, אבל תש\"ר שהוא עצמו בבחי' מקיף דמוחין דז\"א וכמ\"ש כי שם הוי' נקרא עליך אלו תש\"ר<sup data-n=\"2144\">237</sup> כו', וכידוע בבחי' ד' בתים שהן בבחי' בליטה ע\"ג הראש<sup data-n=\"2145\">238</sup> כו', א\"צ להמשיך בחי' מקיף, להיות שצריך להמשיך מקיף עליון ביותר שיהי' מקיף על המקיף דתש\"ר ע\"כ נסתפקו אם צריך לברך על תש\"ר<sup data-n=\"2146\">236</sup> כו' וד\"ל). וא\"כ הרי מה שיש בכח הכלים בבחי' התכללו' דנתב\"ס כו' זהו בא מצד בחי' המקיפים שכלול בהן דבר והיפוכו יחד כו', ואע\"פ שיוצאים מפורדים בהתחלקות כו' הרי בחי' התהו נעשה בבחי' התיקון דכלים, ולא עוד אלא ששרש הכלים נעלה מאד גם מבחי' המקיפים עד שלפ\"ע הכלי דוקא יומשך בחי' המקיף, ומאחר שהמקיפי' אינם באים ונמשכים רק מצד הכלים הרי המקיפים אלו בחי' מקבלים מהכלים אע\"פ שבמקיפי' אין בחי' כלי כלל כו' וד\"ל. ועיקר הראי' ממה שאנו מוצאים בחי' הכלי דתיקון במקיפי' עצמן והוא בענין ברכות המצות במה שהן בפה ודיבור דוקא והרי כלי הפה הוא בחי' כלי כשאר כלים דאדם ולא עוד אלא שהוא עיקר בחי' התיקון דנפש השכלי' הוא נפש המדברת דוקא (שהוא בא בבחי' יש היפך בחי' האין כנ\"ל), <span data-k=\"pg\">סח</span> ּ ואיך יומשך בחי' המקיפי' דברכות בהבל שיוצא מן הפה דוקא שאינו רק כלי",[["2144","237","<b>כי שם הוי'. . תש\"ר</b>: תבוא כח, י. ראה ברכות ו, א."],["2145","238","<b>ד' בתים שהן בבחי' בליטה ע\"ג הראש</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670492\" data-slug=\"torat-chaim\" data-id=\"2300670492\">תו\"ח נח נה, ג</a>. לקמן פ' ויקהל תלב, ג."],["2146","236","<b>דתש\"י לכ\"ע צריך ברכה. . נסתפקו. . על תש\"ר</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ה, סי\"ג. סי\"ד. סכ\"ג. פע\"ח (שער התפלה) ש\"א, פ\"א ופ\"ה. (שער התפילין) ש\"ד, פ\"י. לקוטי שיחות בא (כרך כו) ס\"ע 402 ואילך. נדפס גם באגרות קודש שלו ח\"א ע' רצג. וראה שם ח\"ב ע' נה-נח וע' רעו."]]],[2300540635,"לאו\"פ (ויפלא ג\"כ איך המקיף נמשך על או\"כ דמצות עצמה מצד הכלי דוקא כנ\"ל), שהרי ידוע שאין הכלים רק לבחי' או\"פ דוקא בכל המצות ולא למקיף כו' ואיך יהי' בהיפך שהפה עצמו נעשה כלי למקיף (וכן יפלא על [הבל] הדיבור דד\"ת נעשה אור מקיף<sup data-n=\"2147\">*239</sup> לנשמה כמ\"ש במ\"א בענין ואשים דברי בפיך<sup data-n=\"2148\">239</sup> ובצל ידי כסיתיך כו'). אלא מוכרח לומר שמצד עצמו' אוא\"ס ב\"ה שלמעלה מעלה מבחי' מקיף ופנימי בכלל ובפרט יוכל לעשות בחי' מקיף בחי' פנימי שיומשך ע\"י כלי דוקא בכלי הפה כו', וכן מבחי' כלי דתיקון שהוא הפה יהי' בבחי' התהו שיומשך בו בחי' מקיף דוקא כו'. וזהו שא' למשה [ו]אנכי אהי' עם פיך להיות גם פי[ו] דמשה שהוא מבחי' מקיף ג\"כ בבחי' תיקון ליתן תו\"מ ולתקן לישראל כו', משום דמי שם פה לאדם כו' דתיקון הלא אנכי כו' כי כל יכול לעשות מתהו תיקון ומתיקון תהו, וראי' מקשר וחיבור דמקיפים בכלים וכלי' במקיפים כו', וזהו שע\"י משה נעשה עיקר בחי' התיקון דתו\"מ כו' וד\"ל (וכמו מברכות המצות נמשך גילוי העלם דטעמי מצות כו' וכנ\"ל). וכן ראי' מחילוף האור בכלי שאינו שלו כו' שיכול לעשות ג\"כ היפך האור לכלי והכלי לאור, כידוע שהאור הוא בחי' אין והכלי הוא בחי' יש<sup data-n=\"2149\">240</sup> המגביל כו' ויכול להיות היש בבחי' אין והאין בבחי' יש כו', כמו המשפיל עצמו הוי' מגביהו<sup data-n=\"2150\">241</sup>, כמשה שהי' עניו כו' מ\"ה בעצם נעשה בחי' יש דכלים דתומ\"צ כו' כמ\"ש משה ידבר כו' שמבחי' אין ומה נעשה יש, ומבחי' יש נעשה בחי' אין האמיתי כמו משיח שגבה מאד ונק' אדם אדמה לעליון ממש וז\"ש מ\"ה שמו מה שם בנו<sup data-n=\"2151\">242</sup> וד\"ל (וזהו עליונים למטה ותחתונים למעלה וד\"ל).",[["2147","*239","<b>[הבל] הדיבור. . אור מקיף</b>: נסמן לקמן פ' בשלח קפא, ב."],["2148","239","<b>ואשים דברי בפיך</b>: ישעי' נא, טז. ראה מאמרי אדה\"ז תקס\"ג ח\"ב ס\"ע תשפג ואילך. לקו\"ת דרושים לשמ\"ע פד, ב. מאמרי אדה\"א דברים ח\"ד ע' א'שמ ואילך."],["2149","240","<b>שהאור. . אין והכלי. . יש</b>: ראה ביאוה\"ז בשלח מ, א."],["2150","241","<b>המשפיל עצמו הוי' </b>[זט: ה']<b> מגביהו</b>: עירובין יג, ב."],["2151","242","<b>מ\"ה שמו מה שם בנו</b>: משלי ל, ד [ושם: ומה שם — נסמן לעיל א, ג]. ראה גם מאמרי אדה\"א במדבר ח\"א ע' רסט וע' רצה. דברים ח\"א ע' לד ובהנסמן בהנ\"ל. לעיל א, ג. וש\"נ. כט, ב. לקמן פ' בשלח קנו, ד."]]],[2300540050,"<b>ב\"ה שבת פ' וארא</b>\n<span data-k=\"pg\">138</span> ּ<b>וארא</b> אל אברהם<sup data-n=\"2152\">1</sup> ואל יצחק<sup data-n=\"2153\">2</sup> ואל יעקב באל שדי ושמי הוי' לא נודעתי להם כו', כתיב קרוב ה' לכל קוראיו<sup data-n=\"2154\">3</sup> כו', הנה ברייתו של עולם ברישא חשוכא<sup data-n=\"2155\">4</sup> והדר נהורא, כמ\"ש ויהי ערב ויהי בקר<sup data-n=\"2156\">5</sup> יום א', להבין למה ברישא חשוכא הלא התהוות הכלים הי' אחר התהוות האורות בעולם העקודים<sup data-n=\"2157\">6</sup> כו'. אך הענין שכל עיקר המשכת האור הי' רק בשביל הכלי ואם לא הי' בדעת המאציל התהוות הכלים לא הי' ממשיך האור כלל, נמצא שאע\"פ שבפועל הגילוי האור קדם אבל במקור ההעלם המהווה הכלי קדמה. ויובן זה ע\"פ משל אור שפע שכל הרב לכלי תלמידו המקבל ממנו שכשעלה ברצון הרב להשפיע לו ההשגה מוכרח הי' שיצוייר תחלה בהשגת הרב איכות אופן שכל התלמיד והשגתו את הסברא שיהי' אחר השפעתו לו בגילוי, דהיינו איכות אופן ההגשמה שיגשם בקבלתו את אור שפע שכל הרב כו', וציור זה באיזה אופן יהי' הגשמת התלמיד כו' הוא תלוי ברצון הרב כו' וע\"פ אותו האופן שהוא רוצה הגשמת המקבל כן יומשך אח\"כ אור שפע ההשגה והסברא בגילוי כדי שיהי' בפועל ממש הגשמת כלי המקבל כו', נמצא שבמקור ושרש ההתהוות האור והכלי, הכלי קדם ובפועל והגילוי האור קדם וד\"ל. וע\"פ משל זה יובן במדת חסדו של הקב\"ה הנק' אור חסד דאצי' כשהי' צריך להתהוות ממדה ואור זה שהוא אור א\"ס נשמת אברהם<sup data-n=\"2158\">7</sup> בעל גבול מאין ליש כידוע, והוא ענין ברייתו ש\"ע שהנשמה הוא הכלי והחשך המגביל ומעלים את אור א\"ס, יהי' שרש הכלי והחשך במקור ועצם המדת חסד דאצי' תחלה לאור השפע ממדת החסד דאצי' לה[ו]ות מאין ליש וד\"ל, וזהו ויהי ערב תחלה במדת חסד דאצי' הנק' יום א' ואח\"כ ויהי בוקר להשפיע כו'. וענין והדר נהורא הוא כמ\"ש ויקרא אלקי' לאור יום<sup data-n=\"2159\">8</sup>, שאלקים הוא צמצום<sup data-n=\"2160\">9</sup> הכלי המקבל, קורא תמיד לאור ההוי' המאיר בו שיאיר בו בבחי' פנימית יותר<sup data-n=\"2161\">10</sup> כנז' בזהר ע\"פ אלקים אל דמי לך<sup data-n=\"2162\">11</sup> כו' קארי תדיר לנהורא עילאה למען יזמרך כבוד<sup data-n=\"2163\">12</sup> ולא ידום כו'. ולהבין זאת איך ביכולת הכלי להמשיך בקריאתו את האור בו בבחי' פנימי'",[["2152","1","<b>וארא אל אברהם</b>: מאמר זה הוא כנראה הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז. חלק קטן מהמאמר נדפס בשינויים ובתוס' הגהות באוה\"ת וארא כרך ח ע' ב'תתפח-ט. והמאמר בשלימותו עם הגהות מכ\"ק אדמו\"ר מהר\"ש בסה\"מ תרכ\"ח ע' סח [ושם מתחיל: והי' מדי חודש, ובכותרת: שר\"ח שבט ש\"פ וארא]. ושם בע' עז נמצא עוד פעם חלק מהמאמר בקיצור [ומתחיל בפסוק וארא, כבמאמר דילן]. המועתק להלן במראי מקומות מסה\"מ תרכ\"ח הם הערות כ\"ק אדמו\"ר מהר\"ש. ראה עוד ע\"ד המאמר וזמן אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["2153","2","<b>וארא אל אברהם ואל יצחק</b>: וארא ו, ג [ושם: אל]."],["2154","3","<b>קרוב ה' לכל קוראיו</b>: תהלים קמה, יח. השייכות דפסוק זה — ראה לקמן הערות 10. 22."],["2155","4","<b>ברייתו של עולם ברישא חשוכא</b>: שבת עז, ב (כגי' רש\"י)."],["2156","5","<b>ויהי ערב ויהי בקר</b>: נסמן לעיל יח, א."],["2157","6","<b>התהוות הכלים. . העקודים</b>: באוה\"ת כאן (ע' ב'תתפח) מציין: בע\"ח בשער מטי ולא מטי. ראה גם ע\"ח (שער עקודים) ש\"ו, פ\"ג."],["2158","7","<b>חסד. . נשמת אברהם</b>: נסמן לקמן נו, ג."],["2159","8","<b>ויקרא אלקי' לאור יום</b>: בראשית א, ה."],["2160","9","<b>שאלקים הוא צמצום</b>: נסמן לעיל לד, ד."],["2161","10","<b>יותר</b>: בסה\"מ תרכ\"ח כאן (ע' עז) ניתוסף: וז\"ע קרוב ה' לכל קוראיו. ראה לקמן הערה 22. לעיל הערה 3."],["2162","11","<b>אלקים אל דמי לך</b>: תהלים פג, ב. ראה זהר (היכלות) פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב."],["2163","12","<b>למען יזמרך כבוד</b>: תהלים ל, יג."]]],[2300540088,"יותר מאחר שמן התעבות האור נעשה בגשמי הכלי<sup data-n=\"2164\">13</sup> כמשל כח הראיי' שכלית בכלי העין שמתגשמת לפי כלי העין ואין ערוך ביניהם כלל כו' ואיך ימשיך העין הגשמי להראיי' שכלית כו', אך להיות כי במקור האמיתי הקודם לאור המשפיע המהווה של הכלי נצטיירה שם תחלה להאור, וכל המשכת האור הי' רק בשביל הכלי כנ\"ל, לכן ביכולת הכלי לעורר המקור האמיתי שימשיך את האור לתוכה ביתרון האור והשפע וד\"ל.\n[ב] <b>ובעבודת</b> ה' יובן זאת בהיות כי כמו חשך הלילה שבעוה\"ז קדמה לאור היום הבא אח\"כ והוראת החשך הוא ההגשמה שכל בנ\"א ישינים בהסתלקות חיותם כאילו אינם, וגם השמים והארץ אינם נראים לראות העין וכאילו אינם, ו[כ]שיאיר היום כאלו מתחדשים בחיות חדש שנראה לעין מהות העולם וגם בני האדם חיים בפנימית חיותם כו'. וכן בשנה ונפש בדוגמא זו ממש, דהיינו שברוחניות של גשם העולם יש ג\"כ לילה וחושך קודם בהסתלקות הפנימית <span data-k=\"pg\">סט</span> ּ ויהי' בחי' מדבר שברוחניות בבחי' שינה, דהיינו בבחי' נפש הנק' אדם תתאה המחי' כל העולמות שהוא כח הפועל אלקי בנפעלים כידוע יהי' ערב תחלה בבחי' שינה והסתלקות (ולכן אפי' תרעין דג\"ע שהוא יסוד דנוק'<sup data-n=\"2165\">14</sup> שיקבלו הנשמות השגת אלקות אסתימו בליליא<sup data-n=\"2166\">15</sup> ) כמו<sup data-n=\"2167\">16</sup> שיסגור האדם ביתו בלילה מפני השודדים בלילה כו' וד\"ל), ואז קארי תדיר ולא שכיך לנהורא עילאה לפנימי' שבמדת מלכותו ית' הנק' הוי', עד שבבקר אור הוי' הפנימי' מאיר באלקים חיים<sup data-n=\"2168\">17</sup> כו' ואז ויריעו וישמחו בתוס' אור פנימי' החיי' גם כל בני אלקים<sup data-n=\"2169\">18</sup> וד\"ל. וזהו וארא אל אברהם שאברהם הוא אור החסד ואברהם אוהבי<sup data-n=\"2170\">19</sup>, שהוא התקשרות של נפש אלק[י]ת בהוי' כשקם בבוקר מן השינה והי' נשמתו כל הלילה מגושמת מפני שברוחניות מקור חוצב נשמתו יש חושך כו', וכשקם להתפלל בנפשו האלקי' ומתבוננת בהוי' הי' הוה ויהיה<sup data-n=\"2171\">20</sup> דהיינו האור האלקי המהווה העולם והכלי המוגבל כידוע וכשמתקשרת בהוי' אז תאיר הנפש בהתקשרות זו בבחי' פנימית האור ההוי' הממשיכה כו', וזהו וארא את שם הוי'<sup data-n=\"2172\">21</sup> אל אברהם<sup data-n=\"2173\">22</sup> וד\"ל. והנה",[["2164","13","<b>שמן התעבות האור נעשה. . הכלי</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ג. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשנג. מאמרי אדה\"א נ\"ך ע' קלד. וש\"נ."],["2165","14","<b>תרעין. . יסוד דנוק'</b>: ראה רמ\"ז לזהר בהר קז, ב."],["2166","15","<b>תרעין דג\"ע. . אסתימו בליליא</b>: ראה זהר לך צב, א. וישלח קעב, א. ויחי רמב, ב. בהר קז, ב. סידור שער המילה קמז, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370054\" data-slug=\"torah-or\" data-id=\"3901370054\">תו\"א לך יב, ג</a>."],["2167","16","<b>בליליא) כמו</b>: בסה\"מ תרכ\"ח כאן (ע' סט): בליליא כמו."],["2168","17","<b>באלקים חיים</b>: ואתחנן ה, כג."],["2169","18","<b>ויריעו. . כל בני אלקים</b>: איוב לח, ז."],["2170","19","<b>ואברהם אוהבי</b>: ישעי' מא, ח."],["2171","20","<b>בהוי'. . ויהיה</b>: ראה זהר (רע\"מ) פינחס רנז, ב. שעהיחוה\"א פ\"ז. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680292\" data-slug=\"torat-chaim\" data-id=\"2300680292\">תו\"ח מקץ ריט, ד</a> הערה 62."],["2172","21","<b>וארא את שם הוי'</b>: בסה\"מ תרכ\"ח כאן ס\"ע סט ניתוסף: המהוה את הכלי. וראה שם ס\"ע עח ד\"ה נראה."],["2173","22","<b>אברהם</b>: בסה\"מ תרכ\"ח כאן ע' סט ניתוסף: וזהו\"ע קרוב ה' לכל קראיו כו'. וראה לעיל הערה 10."]]],[2300540126,"כתיב חי חי הוא יודוך<sup data-n=\"2174\">23</sup> כו' שהם ח\"י ברכות<sup data-n=\"2175\">24</sup> של אלקים ואדנ\"י שהוא הנק' אדם תתאה בתחלת הארת הבקר<sup data-n=\"2176\">25</sup>, פוקח עורים<sup data-n=\"2177\">26</sup> המה אור ההוי' בכלי העין הנק' עיני כל<sup data-n=\"2178\">27</sup> מארי דאשגחותא<sup data-n=\"2179\">28</sup> כידוע שיופקח אור הוי' להמשיך בבחי' פנימית ואז יופקח ג\"כ הכלי העין לראות לפי ערכה, כמו כשניעור האדם מן השינה תחלה יופקח אור הראי' שכלית עד שיהי' ההכרח בפיקוח העין הגשמי כו', וכן עד\"ז בכל המשכות האורות בכלים מכלים שונים דבי\"ע כידוע, ובדרך כלל המה ח\"י ברכות<sup data-n=\"2180\">29</sup> ח\"י הויות מלמטה למעלה (הוי' באד'<sup data-n=\"2181\">30</sup> ) כו', ואח\"כ כשכבר מאירי' אורות המצומצמי' בהכלים אז ח\"י ברכות מאמיתית ההויות שבשמ\"ע<sup data-n=\"2182\">31</sup> ברוך אתה הוי' מלמעלה למטה וד\"ל.\n[ג] <b>ואל</b> יצחק, הנה ענין הקריאה של אלקי' להוי' בכל נפש מישראל המתקשרת באה' רבה להוי' הי' הוה ויהי' אהבה זו הוא המשכת אור ההוי' של הנפש אלקית והוא התראות שם הוי' באהבה דאברהם בבקר, וזהו וארא אל אברהם שהוא שילוב הוי' באד'<sup data-n=\"2183\">32</sup> כו'. וכן וארא אל יצחק אחר המשכת הוי' דאברהם שהוא התקשרות האהבה רבה כו' יתוסף באור האהבה זו השמחה והתענוג וגודל החדוה בהתבוננו' ענין ההוי', ותוס' זו באור האהבה היא תוס' מרובה על העיקר שהעונג והחדוה הוא למעלה מן השכל וההשגה אלא שמשתלשלי' מאד ומתלבשי' בלבוש ההשגה וההתבוננו' כידוע ענין התגלות ע\"י הבינה<sup data-n=\"2184\">33</sup>, ובאתעדל\"ת של הנפש מעוררת ג\"כ בבחי' אצי' המשכת העונג והחדוה הנשפלת בבינה ומשם נמשך אור ההוי' של המדה כו', ונמצא אור הוי' זו הנמשכת מאם הבנים<sup data-n=\"2185\">34</sup> כשהיא שמחה בהתגלות ע\"י כו' היא תוס' מרובה על שם הוי' דאברהם אוהבי וד\"ל. וזהו צחוק עשה לי אלקים<sup data-n=\"2186\">35</sup>, פי' מאין בא לנפש המשכה נפלאה כמו שהוא הצחוק והחדוה בהתבוננו' שהוא בחי' בינה יין<sup data-n=\"2187\">36</sup> המשמח<sup data-n=\"2188\">37</sup> כו' הוא ע\"י אלקים דלתתא המגביל את אור ההוי' כידוע. ושרש אלקי' זה שהוא הכלי הוא למעלה מן האור במקור ושרש כנ\"ל, דהיינו בבינה אם הבנים קדמה הכלי לאור כמשל השפעת השכל מן הרב הוא בחי' ו' וכשהוא מתבונן עדיין בשכלו איכות המקבל כנ\"ל הוא בחי' ה' <span data-k=\"pg\">140</span> ּ ראשונה כמ\"ש במ\"א<sup data-n=\"2189\">38</sup> בדרך",[["2174","23","<b>חי. . יודוך</b>: ישעי' לח, יט [ושם: יודך. ראה הנסמן בשע\"ת מג, א. ש\"א ס, ב. בסה\"מ תרכ\"ח כאן (ריש ע' ע) תוקן בגוכי\"ק: יודך, ומציין לישעי' שם]."],["2175","24","<b>ח\"י ברכות</b>: בסה\"מ תרכ\"ח כאן (ע' עח) ניתוסף: השחר."],["2176","25","<b>ח\"י ברכות. . הבקר</b>: ראה פע\"ח (שער התפלה) ש\"א, פ\"ו. (שער הברכות) ש\"ב, פ\"ד. (ובאופן אחר) ש\"א, פ\"ז (ד\"ה ואלה ממוסיף).. ש\"ב, פ\"ה ופ\"ז. אוה\"ת בלק ס\"ע א'כג ואילך. שער הכולל פ\"א, ס\"ו ואילך. (וראה ג\"כ לקמן עד, סע\"ב ואילך. אוה\"ת על ענינים ע' שה ואילך)."],["2177","26","<b>פוקח עורים</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקפח. לקמן עד, ג. אוה\"ת שם. המשך תער\"ב ח\"ב ע' תשלט."],["2178","27","<b>עיני כל</b>: זכרי' ד, י [ושם: עיני' ה' משוטטים בכל הארץ]. דהי\"ב טז, ט [ושם: עיניו משוטטות בכל הארץ]."],["2179","28","<b>מארי דאשגחותא</b>: ראה זהר (אד\"ר) נשא קלו, ב. (אד\"ז) האזינו רצג, ב. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670162\" data-slug=\"torat-chaim\" data-id=\"2300670162\">תו\"ח וירא צט, א</a> הערה 1. לקמן פ' בשלח קסה, רע\"ד. תצוה שלג, ד."],["2180","29","<b>חי חי. . ח\"י ברכות</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתט. וש\"נ. נ\"ך ע' יח."],["2181","30","<b>מלמטה למעלה (הוי' באד')</b>: בסה\"מ תרכ\"ח כאן ע' ע מפרש: להיות כי זהו ענין שילוב הוי' באד' לכן נק' מלמטה למעלה. לקמן פ' בשלח קצו, ג."],["2182","31","<b>ח\"י ברכות. . הבקר. . שבשמ\"ע</b>: ראה גם מאמרי אדה\"ז תקס\"ט ע' קפ. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370320\" data-slug=\"torah-or\" data-id=\"3901370320\">תו\"א יתרו עב, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370320\" data-slug=\"torah-or\" data-id=\"3901370320\">ש\"א עב, א</a>."],["2183","32","<b>שילוב הוי' באד'</b>: ראה מבו\"ש ש\"ג ח\"ב ספ\"ה. שהיחוה\"א פ\"ז. לקמן פ' בשלח קצו, ג. מאמרי אדה\"א דברים ח\"ב ע' תמה־ נ\"ך ע' כ־ הנחות תקע\"ז ע' שמו ובהנסמן בהנ\"ל. שע\"ת מז, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680273\" data-slug=\"torat-chaim\" data-id=\"2300680273\">תו\"ח ויצא קסז, ב</a>. וישב רג, ד."],["2184","33","<b>הבינה</b>: א: בבינה. בסה\"מ תרכ\"ח כאן (ע' ע) כבפנים. בבוך 1013 (הוא העתק המאמר דתרכ\"ח) תוקן וא\"א לברר אם תוקן כבפנים או כא."],["2185","34","<b>בבינה. . מאם הבנים</b>: נסמן לעיל יז, א."],["2186","35","<b>צחוק עשה לי אלקים</b>: וירא כא, ו."],["2187","36","<b>בינה יין</b>: ראה זהר נשא קכז, א. מאמרי אדה\"א ויקרא ח\"א ע' לג. וש\"נ. בראשית ע' תקעא."],["2188","37","<b>יין המשמח</b>: ס' שופטים ט, יג. תהלים קד, טו. ראה גם מאמרי אדה\"א בראשית ע' רפח."],["2189","38","<b>כמ\"ש במ\"א</b>: ראה גם אגה\"ת פ\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380219\" data-slug=\"likkutei-torah\" data-id=\"4001380219\">לקו\"ת אמור לג, ב</a>. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסא. ע' תתצח. פלח הרמון בשלח ע' קצו בשם הה\"מ."]]],[2300540164,"פרט בכל התהוות דבר מה כו'. וזהו כי הוי' הוא אלקי'<sup data-n=\"2190\">39</sup> שהוא התכללות האור הנשפע במקורו האמיתי בחי' בינה דעתיד לאתגלייא כו' וכנז' בזהר ע\"פ ועבד הלוי הוא<sup data-n=\"2191\">40</sup> כו', אבל אלקים שלמטה מן הוי' ביכולתו להמשיך אלקים עילאה מאחר שבשרש ובמקור הוא קדם שם וכנ\"ל, וזהו צחוק עשה לי אלקים דלתתא וד\"ל. וכן בעבודת ה' עיקר החדוה הניתוסף באהבה דאברהם הוא ע\"י התבוננות הצמצום וההסתר של אלקים וחשקו לצאת מן ההגבלה ועי\"ז תתגבר האהבה בהוי' ברשפי אש התשוקה ואז יהי' החדוה מן ההתחדשות של היפך הצמצום כו' וד\"ל. והנה כתיב אז תתענג על הוי'<sup data-n=\"2192\">41</sup> שהתענוג הוא ענין ראשית נקודת הנפש כשנמשכת ממקור חוצבה המהווה אותה שהוא בחי' יחידה שבה, וידוע שמן המשפיע יושפע המתהווה בבחי' אותיות לבד ולכן ירבו אופני התענוג הנשמה לפי אופני המשכתה אם מחסד דאצי' אם מגבורות כו', אבל בזאת יתרון התענוג שבנפש שהיא בחי' נקודה הראשונה שבה והיא למעלה ממדריגת האור האלקי הנשפע בהתחלקות קוין שבה חב\"ד ומדות ומו\"ד שאע\"פ שהאור אלקי הנשפע עליו ה[ו]א בחי' אלקי', אבל מתצמצם הוא רק לפי אופן כלי הגבלתה כמשל אור הראי' שכבר נתגשם בכלי העין כידוע, אבל כשמתפשטת ויוצאה מכלל קוין ובאת' לעיקר הנקודה היא באה לעצם מקורה האמיתי שהמשיכה ואז היא למעלה ממדריגו' בחי' הוי' שבפרטיות כחותי' וזהו אז תתענג על הוי' שבה וד\"ל.\n[ד] <b>והנה</b> הנשמות הנהני' מזיו השכינה<sup data-n=\"2193\">42</sup> מאחר שהמה מתענגי' על הוי' מקבלים המה מן המקור האמיתי שלהם והוא ענין זיו השכינה, דענין שכינה ידוע שהוא בחי' אלקות המתפשט להוות בעלי גבול<sup data-n=\"2194\">*43</sup>, ויש בדרך כלל במדת התפשטו' זו של אלקי' י\"ס, והנשמות הנהני' והמתענגי' מקבלים מבחי' הזיו שהוא הארת עונג העליון שבמל' דאצי' הנשפלת באור בינה של מל' דאצי' והוא מקור ג\"ע העליון הנק' חיי העוה\"ב<sup data-n=\"2195\">43</sup> שכל התהוות בעלי גבול א\"א<sup data-n=\"2196\">44</sup> אלא ממדות עליונות, אלא כשנפשטי' מכל כחות הנפש ובאים לבחי' יחידה שבהם אז המה באים לכמו שהיו במעי אמם שהיא בינה שבמל' כו' קודם",[["2190","39","<b>כי הוי' הוא אלקי'</b>: ואתחנן ד, לה. לט."],["2191","40","<b>ועבד הלוי הוא</b>: נסמן לעיל פ' שמות לד, א."],["2192","41","<b>אז תתענג על הוי'</b>: ישעי' נח, יד. ראה גם לקמן פ' בשלח רט, ד. מאמרי אדה\"א דברים ח\"ג ע' א'קי. נ\"ך ע' תסז ובהנסמן בהנ\"ל. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680135\" data-slug=\"torat-chaim\" data-id=\"2300680135\">תו\"ח ויחי רמא, ב</a>."],["2193","42","<b>הנשמות הנהני' מזיו השכינה</b>: ראה ברכות יז, א."],["2194","*43","<b>בעלי גבול</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נז, ב</a>)."],["2195","43","<b>העוה\"ב</b>: בסה\"מ תרכ\"ח כאן ניתוסף: שע\"ז ארז\"ל יפה כו' קורת רוח בעוה\"ב מכל חיי עוה\"ז כו' לפי."],["2196","44","<b>א\"א</b>: שם: א\"א להיות."]]],[2300540201,"שיגדלם אימא כו' וד\"ל. אך להיות כי אינם מקבלים עונג העליון כמו שהוא בעצם אלא זיו ממנו לבד המתפשט ומלבש<sup data-n=\"2197\">45</sup> בירידה גדולה בלבוש השכינה כו' כמו שהנשמות עיקר התענגם הוא ע\"י השג[ו]תיהם באלקים כנז' בזהר שלח<sup data-n=\"2198\">46</sup> כו', לכן נק' העוה\"ב יש<sup data-n=\"2199\">47</sup> להנחיל אוהבי יש<sup data-n=\"2200\">48</sup> שבחי' בינה נק' יש לגבי חכ' ורצון ותענוג כמו שבינה היא הראשית ואין האמיתי לגבי מלכות כמו\"כ ממש הוא בחי' מל' ויש לגבי מקוריי' המעלימי', שמן רדל\"א עד בינה המה מקוריי' שבהעלם ומן בינה עד מל' המה מקוריי' הגלוי' ובינה נק' דעתיד לאתגלייא כידוע וכנז' בזהר כמה דאיהו תמינאה<sup data-n=\"2201\">49</sup> כו' וד\"ל. ואפי' העונג הנשפל בבינה הוא יש שמרגיש דבר מה כידוע וד\"ל. אבל תשובה ומע\"ט המה הגבה למעלה מחיי העוה\"ב, כי המצות המה רצונותיו ית' הפשוטי' בתכלית הפשיטות, והעונג שברצון אינו מורגש כלל שהרצון אינו בכלל התפשטות אור וכלי כלל כמו חו\"ב, ולכן לא יהי' בערך הרגשת דבר ויש כמו שהאדם שכלו והשגתו יתפס לדבר מה בכלי <span data-k=\"pg\">ע</span> ּ מוחו אבל רצונו לא ידע מקום וכלי לרצונו ויהי' שוה אצלו רצונו להניע רגלו כמו רצונו להשכיל השכלה כו', מפני שאין לרצון תפיסא אמיתי' בכלי הגוף, ומ\"מ באמת הוא נתפס בכל כלי הגוף ונשמעי' כולם בשוה להרצון וד\"ל. ולכן יובן למשכיל שהרצון נק' חשך<sup data-n=\"2202\">50</sup> מפני שהוא מקור האמיתי שבהעלם מכל כלי הגוף מאורותיהם כו', ולכן הנשמות בהשג[ו]תיהם אף שיתענגו לא יוכלו לקבל מכתר שבמ' דאצי' שאין הענג אשר שם ערוך אליהם להיות בבחי' תפיסא בם, כי איהו תפיס בכולהו עלמין<sup data-n=\"2203\">51</sup> ולית מאן דתפיס כו' וכמ\"ש ישת חשך סתרו<sup data-n=\"2204\">52</sup> שהוא בחי' אריך ונק' ג\"כ כי אתה הוא האלקי' לבדך<sup data-n=\"2205\">53</sup>, שכינה<sup data-n=\"2206\">54</sup> שבמ' דאצי' אע\"פ שהוא למעלה מן הוי' שהוא מדות שבמל' כו', אבל לא נק' אלקי' לבדך אלא שאלקי' דבינה הוא בחי' היש והתגלות ההעלם מקורו שהוא מזל ונקה מן העלם הרצון וכמ\"ש במ\"א שמהות כח ההתבוננות נמשך התהוותו מאין ליש ממזל והארת מ\"ס דא\"א, ובהעלם הרצון אין ערוך להארת המזל הנמשך כמשל יניקת השערות כמ\"ש<sup data-n=\"2207\">55</sup> וע\"ז כתי' אין ערוך לך<sup data-n=\"2208\">56</sup> למהותך ועצמותך שברצונך הפשוט כו' וד\"ל.\n<b>וזהו</b> תחת אשר לא עבדת<sup data-n=\"2209\">57</sup> את ה' אלקיך בשמחה ובטוב לבב מרוב כל, שחיי העוה\"ב נק' רוב כל כי בינה שבמל' דאצי'",[["2197","45","<b>ומלבש</b>: שם: ומתלבש."],["2198","46","<b>הנשמות. . בזהר שלח</b>: ראה גם לקמן פ' בא צב, ג. וש\"נ."],["2199","47","<b>נק' העוה\"ב יש</b>: ראה גם לעיל פ' שמות לד, סע\"א. וש\"נ."],["2200","48","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["2201","49","<b>כמה דאיהו תמינאה</b>: ראה זהר תרומה קסה, א."],["2202","50","<b>שהרצון נק' חשך</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' עדר."],["2203","51","<b>איהו תפיס בכולהו עלמין</b>: ראה זהר (רע\"מ) פינחס רכה, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קפב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670220\" data-slug=\"torat-chaim\" data-id=\"2300670220\">תו\"ח נח סו, ג</a> בהערה 30."],["2204","52","<b>ישת חושך סתרו</b>: תהלים יח, כב."],["2205","53","<b>כי אתה הוא האלקי' לבדך</b>: מלכים-ב יט, טו־ ישעי' לז, טז [בהוספת תיבת ”כי\"]."],["2206","54","<b>שכינה</b>: בסה\"מ תרכ\"ח כאן (ע' עב): כי שכינה."],["2207","55","<b>כמ\"ש</b>: כמו שיתבאר."],["2208","56","<b>אין ערוך לך</b>: ברכת יוצר לשבת."],["2209","57","<b>תחת אשר לא עבדת</b>: תבא כח, מז. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתמח. נ\"ך ע' לה. לקמן נג, ד."]]],[2300540234,"הוא הכולל כל הנבראים מו' ימי המעשה שבמדת מל' ית' כידוע, ולכן כתי' לא תחסר כל בה<sup data-n=\"2210\">58</sup>, והשמחה וטוב לב הגנוז בלב ואינו נראה כשהוא משים כל מחשבתו ושכלו באותיות התורה שהמה רצונותיו ית' הרי נפשו קשורה במהותו ועצמותו ית', ואע\"פ שהענג שבנפשו אינה מרגשת הענג העליון דאצי' העצמי הגנוז ברצון המצוה להיות כי הושפלה המצוה בעניני זה העולם בלבושי נוגה כו', עכ\"ז הוא הגבה למעלה מהרגשת עונג הנפש בהתענגה על הוי' בתפלה או<sup data-n=\"2211\">59</sup> שהרי בקבלתה ממקורה הוא רק זיו העונג לבד שמתגשם בבינה כנ\"ל, וגם היא עצמה בהרגשת העונג שבה שהוא תופס מקום ויש כו', ובלימוד התורה אינה בהרגשות התענוג והרי היא כאמיתי' ביטול עצמותה שאינה מרגשת עצמותה כלל כשמתקשרת כל כחותי' באותיות התורה, וגם הרי אותיות התורה המה נובלות חכמה שלמעלה<sup data-n=\"2212\">60</sup> שהיא מו\"ס דא\"א חכמה שברצונו הפשוט למה ירצה כך כו' והרי מקושרת היא בעצמותו ית' ולכן המצוה גדול משכר המצוה וע\"כ שכר מצוה מצוה<sup data-n=\"2213\">61</sup> וד\"ל. וזהו אשר קדשנו והגביהם<sup data-n=\"2214\">62</sup> מאד נעלה במצותיו<sup data-n=\"2215\">63</sup> רצונותיו ישת חשך סתרו כנ\"ל וד\"ל. וזהו שהשמחה וטוב לב הגנוז במעשה המצות הוא יותר טוב מרוב כל, וזהו עד יעבור עמך הוי'<sup data-n=\"2216\">64</sup> כשיעברו בנ\"י במעשה המצות את הוי' שיעלו ויתקשרו מאד נעלה ברצונו הפשוט למעלה מבחי' הוי', שהוא מקור חיי העולמים לבד, אבל אותיות התורה הנק' הר נחלתך ומכון לשבתך פי' כלים להשראת רצונו הפשוט וכשתביאמו ותטעמו<sup data-n=\"2217\">65</sup> שיתקשרו היטב כמו הנטיעה המקושרת בארץ והיתה לאחדים שלא תנתק לעולם כו', כמו\"כ כאשר יתקשרו בקשר אמיץ נש\"י באותיות התורה ויהי' מכון עצמותו ית' אז עם זו קנית<sup data-n=\"2218\">66</sup> וד\"ל.\n[ה] <b>וזהו</b> אני חומה<sup data-n=\"2219\">67</sup> ושדי כמגדלות, הנה אני הוא אין<sup data-n=\"2220\">68</sup> וידוע שיש ב' מיני אין<sup data-n=\"2221\">69</sup>, א' המקור ליש והוא בחי' אין לו, והב' שאין ערוך שיושפל להיות אין ליש כו', והנה <span data-k=\"pg\">142</span> ּ חכמה מאין תמצא<sup data-n=\"2222\">70</sup> ממזל הח' דאריך הרי האין של החכמה הגנוז ברצון נק' אין של יש ונמשך ממקור האין האמיתי שהוא החכמה שברצון הנעלמה מאד נעלה הארה בעלמא להיות מקור לחכמה הנגלית והוא כמשל מותרי מוחין<sup data-n=\"2223\">71</sup> המגדלים השערות כמ\"ש במ\"א. אבל מ\"ס עצמו הוא האין האמיתי שאין ערוך להיות מקור לאיזה",[["2210","58","<b>לא תחסר כל בה</b>: עקב ח, ט."],["2211","59","<b>או</b>: בתו\"ח כאן הניח מקום פנוי. א: אוצג\"ע ( ) אוצב\"ע ( ). בסה\"מ תרכ\"ח כאן (ע' עב): או בתורה."],["2212","60","<b>נובלות חכמה שלמעלה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["2213","61","<b>שכר מצוה מצוה</b>: נסמן לעיל ז, ב."],["2214","62","<b>והגביהם</b>: א ובסה\"מ תרכ\"ח כאן (ע' עג): והגביהנו."],["2215","63","<b>אשר קדשנו. . במצותיו</b>: נוסח ברכת המצות. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לא וע' קפו. דרך מצותיך ע' קסח."],["2216","64","<b>עד יעבור עמך הוי'</b>: בשלח טו, טז. ראה גם הנסמן לעיל א, ב הערה 21."],["2217","65","<b>הר נחלתך ומכון לשבתך. . וכשתביאמו ותטעמו</b>: בשלח שם, יז."],["2218","66","<b>עם זו קנית</b>: המשך הכתוב עד יעבור."],["2219","67","<b>אני חומה</b>: שה\"ש ח, י."],["2220","68","<b>אני הוא אין</b>: ראה פרדס (שער אם הא\"ס הוא הכתר) ש\"ג, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקמד. מאמרי אדה\"א דברים ח\"א ע' רלד. הנחות תקע\"ז ע' ב."],["2221","69","<b>ב' מיני אין</b>: ראה גם מאמרי אדה\"ז על ענינים ע' קעה. שערי אורה שער הפורים ע' 124 ואילך. מאמרי אדה\"א בראשית ס\"ע לז ואילך. וש\"נ. לקמן פ' בשלח קפו, ד. ויקהל תלח, ד."],["2222","70","<b>חכ' מאין תמצא</b>: איוב כח, יב. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתק-א. לעיל פ' שמות לו, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תט."],["2223","71","<b>מותרי מוחין</b>: ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' שמג. ענינים ע' קעו. מאמרי אדה\"א ויקרא ח\"ב ע' תנח וע' תשעח. דברים ח\"א ע' רכו ואילך."]]],[2300540266,"התהוות דבר מה אפי' להיות כח ההשכלה להשכיל כל דבר כו'. וזהו אני חומה חכמה שבתושב\"כ ושבע\"פ הוא בחי' חכים ולא בחכ' ידיעא<sup data-n=\"2224\">72</sup>, ואפי' אותיות התורה שהן לבנונית הכתב והשחור של אותיות שבהם גנוז ח\"ס המה הגבה למעלה מערך שרש כל הנאצלים והוא בחי' מקיף על כל הנשמות ולא יכלו נשמות דאברהם ויצחק להיות להם תפיסא בבחי' אור הוי' וכלים דאלקי' בשמי הוי', פי' שמי של עצמות[י] ממש, אע\"פ שהוא גם שם והוי' שהמה אותיות התורה עכ\"ז לא נודעתי שמי שהוא הויות וכלים שבמ\"ס, שהוא ענין הוא ושמו לבד<sup data-n=\"2225\">73</sup>, שכמו שהוא לבדו הוא ברצונו הפשוט כן שמו של רצונו לבדו הוא ונשגב שם העצם מכל הארות המזלות בחי' אין של היש, ולכן לא נודעתי אליהם אלא בבחי' מקיף לבד כמשל החומה המקפת מבחוץ כו'. אבל באל שדי נראיתי להם בבחי' או\"פ כו', וענין אל שדי הוא כמ\"ש ברכות שדים<sup data-n=\"2226\">74</sup>, ושדי כמגדלות, שהחלב שבשדים הוא המובחר שבכל חיות הדם שבגוף שהרי דם נעכר ומן המובחר שבו נהפך לחלב<sup data-n=\"2227\">75</sup>, והוא בזכר אחר שנהפך המאכל לדם ובא ללב מן<sup data-n=\"2228\">*76</sup> המובחר שבו יוצא מן הלב עד גידי המוח ושם נהפך מהות כח הדם לגמרי ונעכר ונעשה מהות חלב, כי מיץ חלב<sup data-n=\"2229\">76</sup> לבן ואותו המיץ מתפשט בגידי' ומחי' ומחזיק כח השכל ואח\"כ מתפשט מגידי המוח לחיות רוחניות דק מאד לכל האברים והוא חיות נעלם מאד מערך מזג האברים, והעונג המורגש באדם אחר שעשה המאכל חיזוק במוחו הוא החיות הדק מאד שבמיץ חלב המחי' את המוח והוא בא מן הפיכת הדם כו' וד\"ל. נמצא שהחיות הנעלם במיץ חלב שבגידי המוח הוא האין של היש של הדם המחי' שבלב וכשנהפך ונעכר לגמרי ממהותו בא לכלל אין של חיות המוח וד\"ל. ובאשה הוא בריבוי יותר הפיכת הדם למיץ חלב שבמוחה עד שנשפע ונתגשם ממנו חלב ממש בשדיים כדי שיקבל התינוק ההשפעה היותר פנימי' שנמשך מחיות ההעלם שבמוחה. והוא היתרון של יניקה על עיבור, שבעיבור אין לו מוחין מצד שניזון מדמה של אם מה שאוכלת ונהפכת לדם לבד כו' כי הוא כא' מאברי' לבד וד\"ל, אבל ביניקה יש לו מוחין מחלב האם הנמשך מן מוחה בהפיכת הדם שלה וד\"ל.\n[ו] <b>והנה</b> עפ\"ז יובן למשכיל ענין ברכות שדיים שהוא ההשפעה היותר פנימית שבאדם להיותה נמשכת מהעלם שבמוח, והנה עיקר ההעלם שבמוח שאין המיץ חלב שבמוח מחייהו כלל הוא החלל שבתוך המוח הגשמי ששם אין גידי המוח מתפשטי' והוא א\"צ לחיזוק כי הוא מאד נעלם מהגשמת המוח הגשמי ובחלל ריקן זה הוא השראת חכמה הנעלמת מאד שלמעלה מכח המשכיל, כי כח המשכיל ההשכלות",[["2224","72","<b>חכים ולא בחכ' ידיעא</b>: ז\"ח יתרו לד, ד. ת\"ז (בהקדמה) יז, ב."],["2225","73","<b>הוא ושמו לבד</b>: נסמן לקמן נג, ב."],["2226","74","<b>ברכות שדים</b>: ויחי מט, כה."],["2227","75","<b>דם נעכר. . נהפך לחלב</b>: נדה ט, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370478\" data-slug=\"torah-or\" data-id=\"3901370478\">תו\"א שמות קח, ב</a>. מאמרי אדה\"א במדבר ח\"ב ע' תמד ואילך. ע' תפב ואילך."],["2228","*76","<b>מן</b>: בסה\"מ תרכ\"ח כאן (ע' עד): ומן."],["2229","76","<b>כי מיץ חלב</b>: משלי ל, לג."]]],[2300540295,"שורה על המוח הגשמי <span data-k=\"pg\">עא</span> ּ וגידי המוח ממשיכים אותו שישרה והוא חיזוק שמחזיקי' כח המשכיל כו'. אבל בחלל הריקן זהו<sup data-n=\"2230\">77</sup> השראת א\"ס<sup data-n=\"2231\">78</sup> שאינו מערך כח המשכיל, שכח המשכיל ממותרי מוחין דילי' הנק' מזל כנ\"ל אין בגידי המוח כח לחזק ולהמשיך רק בחי' המותרי מוחין שבחלל שיתן כח ועוז לכח המשכיל היונק ממנו שיתפשט במוח הגשמי כו' וד\"ל. אבל המ\"ס שבחלל אין ערוך לגידי המוח שם שיהיו גורמין ההמשכה וההתפשטות שם כו' וד\"ל. והוא להיותו בחי' אין האמיתי שאין ערוך שיהי' מקור ליש, ולכן אין מהפיכת הדם שהוא היש לאין שבגידי המוח גורם לו המשכה כלל כו' רק לאין של היש ימשיכו ע\"י העלאת מ\"ן שלהם כשנהפך היש לאין וד\"ל. וכמשל המצייר כלי ברצון ותשוקה שיתענג אח\"כ כשהכלי כבר נגמרת, ואותו העונג שאחר גמר הכלי הוא אותו העונג עצמו שהכריח רצונו לצייר, ושניהם הוא התפשטות העונג להיות אין ומקור לפעולת הציור, אלא שזה הי' תחלה לפעולת הציור, לא הי' נרגש כ\"כ, והעונג הוא אחר הפעולה נרגש הוא אחר העשי' והפעולה הנק' יש ונהפך לאין שהוא העונג ממנו וד\"ל. כמו\"כ ענג הנרגש אחר הפיכת הדם לחלב שבמוחו נראה לו שהוא בא אל עצמיות שלו הוא רק אין של היש, אבל בחי' יחידה שבו שאינו מחיה את הגוף אינו נרגש כלל להיותו אין האמיתי שאין הארה ממנו לחיות כלי הגוף והוא המקיף האמיתי וד\"ל.\n<b>ועתה</b> יובן למשכיל למעלה ענין אני חומה ושדי כמגדלות, אני חומה הוא בחי' מ\"ס עצמו והוא ענין שמי הוי' בחי' תחתונה שבמאציל שנקרא בשם עצמיות א\"ס ב\"ה, והוא שרש כל הנאצלים מצד הארת המזלות ממותרי המוחין והוא ענין ישת חשך סתרו הוא המקיף שבהעלם האמיתי, אשר אין ערוך להפיכת דם שהוא מקוריי' הגלויי' הנק' אורות הנאצלים שהמה מקוריי' לחיי העולמים כו' שנהפך היש לאין ע\"י העלאת מ\"ן עד רום המעלות כו' ומתעורר העונג הוא האין של היש רוחצת<sup data-n=\"2232\">79</sup> בחלב<sup data-n=\"2233\">80</sup> והוא ג' שעות האחרונות שמשחק עם לויתן<sup data-n=\"2234\">81</sup> שיסוד ז\"א עולה עד יסוד דע\"י<sup data-n=\"2235\">82</sup> ע\"י ארץ שנתנה יבולה<sup data-n=\"2236\">83</sup> מלמטה בהעלאת מ\"ן כו', אבל אין ערוך לך למהותך ועצמותך בחי' אין האמיתי המקור למזלות מזל הח' ומזל הי\"ג שהמה ממשיכים אור חכ' דאצי' ואור בינה, וחו\"ב נק' עיני העדה<sup data-n=\"2237\">84</sup> שהם אלדד ומידד<sup data-n=\"2238\">85</sup> היונקים ממשה והם היונקים משדיים שהשדיים שהחלב עדיין בהם בהעלם אלא שנתגשם להיותו כבר נמשך ממקור המוח הגשמי, ועיקר תכלית הדקות שבחלב שבשדיים הוא חיזוק המשכיל שנמשך ממותרי מ\"ס מזלות דא\"א. ולכן שמי הוי' פי' אף הארות המזלות שהם כלי ושם לעצמות מו\"ס לא נודעתי להם",[["2230","77","<b>זהו</b>: א: שבו."],["2231","78","<b>א\"ס</b>: א: מ\"ס."],["2232","79","<b>היש רוחצת</b>: כ\"ה גם בסה\"מ תרכ\"ח כאן."],["2233","80","<b>רוחצת בחלב</b>: שה\"ש ה, יב [ושם: רחצות]."],["2234","81","<b>ג' שעות. . לויתן</b>: ע\"ז ג, ב."],["2235","82","<b>שיסוד ז\"א. . דע\"י</b>: ראה גם שעה\"י קכח, א ובהערה 5. מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות ע' 23."],["2236","83","<b>ארץ שנתנה יבולה</b>: ע\"פ תהלים סז, ז."],["2237","84","<b>וחו\"ב נק' עיני העדה</b>: שלח טו, כד. ראה גם מאמרי אדה\"א דברים ח\"ג ע' תשמ."],["2238","85","<b>אלדד ומידד</b>: בהעלותך יא, כו. ראה גם בענין אלדד ומידד ע\"ח שער הכללים פ\"ג. מבו\"ש ש\"ה ח\"ב פ\"ג. שער ההקדמות דרוש ד' בזמן הלידה והיניקה (קסו, ב). לקו\"ת ושער הפסוקים להאריז\"ל בהעלותך שם. ביאוה\"ז שלח צב, סע\"ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370478\" data-slug=\"torah-or\" data-id=\"3901370478\">תו\"א שמות קח, ב</a>. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע קנב. תקס\"ז ע' רלב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380465\" data-slug=\"likkutei-torah\" data-id=\"4001380465\">לקו\"ת שלח לח, ב</a>. לקמן פ' בשלח רמו, א."]]],[2300540323,"והוא אותיות התורה כנ\"ל, אבל באל שדי הגילוי בנשמותיהם וד\"ל. וכל זאת בשביל שלא הי' להם התורה עדיין שהוא בחי' חכ' שבהעלם ובלימוד התורה מתקשרת הנשמה במהות חכמתו ית' חכים ולא בחכ' ידיעא והוא בחי' חשך שבמ\"ס אשר קדשנו במצותיו, ונהנים מזיו עילאה דע\"י<sup data-n=\"2239\">86</sup> המתלבש בבינה שבמל' דאצי' כנ\"ל הוא למטה מן מדרגו' הלימוד בזה העולם שמתקשרת בעונג העצמי שאינו נמשך לחו\"ב הגלויים כנ\"ל. אך אע\"פ שמחיי עוה\"ב נהני' מזיו גדלה מעלת תורה ומע\"ט בעוה\"ז, אבל ממדרגו' שהם בשבת לא גדלה, שאז אין נהנין מזיו כמו שאר ימי השבוע, שכמו שבג\"ע התחתון <span data-k=\"pg\">144</span> ּ מתעלין הנשמות בשבת ע\"י העמוד לג\"ע העליון כנז' בס' הבהיר<sup data-n=\"2240\">87</sup>, כך בג\"ע יתעלו יותר שיופשטו ממדרגו' ג\"ע העליון הנמשך מבינה שבמל' דאצי' לבד, אלא כתיב בהו אז תתענג על הוי' שעולין בי\"ג נהרי דאפרסמונא דכיא<sup data-n=\"2241\">88</sup> שהוא הארות העונג העצמי ולא הזיו ממנו לבד, כי מדי שבת בשבתו יבא<sup data-n=\"2242\">89</sup> לכלל ביטול האמיתי מכל כחות הנפש עד בחי' יחידה שבה לבד, וזהו להשתחוות לפני הוי'<sup data-n=\"2243\">90</sup> כמו קודם שיגדלו במעי אימא ליזון מדמה כו' וד\"ל, אלא כמו שהוא עדיין בלא התחלקות ציור כלל והי' בו טיפת מו\"ס וד\"ל.",[["2239","86","<b>מזיו עילאה דע\"י</b>: נסמן לעיל פ' שמות לה, ב."],["2240","87","<b>העמוד. . בס' הבהיר</b>: נסמן לעיל פ' שמות ו, ד."],["2241","88","<b>בי\"ג נהרא דאפרסמונא דכיא</b>: נסמן לעיל פ' שמות לד, ב."],["2242","89","<b>מדי שבת בשבתו יבא</b>: ישעי' סו, כג."],["2243","90","<b>להשתחוות לפני הוי'</b>: ישעי' שם [בדילוג]."]]],[2300540051,"<b>בס\"ד</b>\n<span data-k=\"pg\">150</span> ּ<b>ענין</b> יחוד קוב\"ה ושכינתי'<sup data-n=\"2244\">1</sup>, פי' שכינה ידוע שהוא כח הפועל<sup data-n=\"2245\">*3</sup> בנפעל<sup data-n=\"2246\">2</sup> כח<sup data-n=\"2247\">**3</sup> התפשטו' חיות הנפש בתוך כלי הגוף, אך כלי אברי הגוף אף שהם גשמיי' וערך חיות רוחני'",[["2244","1","<b>ענין יחוד קוב\"ה ושכינתי'</b>: מאמר זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז. נדפס בשינויים במאמרי אדה\"ז אתהלך לאזניא ע' עד [סיבת השינויים כנראה הוא מפני שהדרושים שב”אתהלך לאזניא\" הם ”דרושים דלאזניא כ\"י מו\"ח והוגהו מר' ליב מאהליווער\" — כמ\"ש שם ע' רסב]. ראה עוד ע\"ד מאמר זה וזמן אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["2245","*3","<b>כח הפועל בנפעל</b>: נסמן לקמן עה, א הערה 187."],["2246","2","<b>שכינה. . כח הפועל בנפעל</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"ב ס\"ע שסג. ענינים ע' תמה."],["2247","**3","<b>כח</b>: אב: כמו."]]],[2300540089,"שבהם הוא בתכלית הדקות, עכ\"ז אנו רואים שיכאב ההכאה לחיות שבאצבע, שבודאי לא יהי' הכאב לגשם האצבע אלא להחיות רוחני שבו, וקודם התפשטות החיות באצבע לא יתכן לו שירגיש כאב ההכאה אלא מצד התלבשותו בגשם האצבע, ועכ\"פ כשנתלבש והי' לאחדים עם גשם האצבע הרי הוא מרגיש הכאב ומתפעל כו'. והנה עד\"ז לא יתכן לומר באלקי' חיים<sup data-n=\"2248\">3</sup> המחי' את הנברא מאין ליש שיתפעל ח\"ו מן גרעון הנברא, וע\"ז כתיב כי נשגב שמו<sup data-n=\"2249\">4</sup> אפי' בבחי' התפשטו' דהתפשטו' שהוא כח הפועל אלקי המתלבש בנברא להיות כי אין ערוך כלל בין בורא לנברא כידוע, ולא כמו חיות הנפש לאבר הגוף שיש להם ערך אלא שזה דק וזה גס כו' וד\"ל.\n<b>והנה</b> בישראל עם קרובו<sup data-n=\"2250\">5</sup> כתי' בכל צרתם לו צר<sup data-n=\"2251\">6</sup> קרי וכתיב, שמצד התפשטו' מדת מלכותו ית' להחיות העולמות הרי אין מדת הקב\"ה שהוא כח ההתפשטו' <span data-k=\"pg\">עה</span> ּ שלו במדת מל' כמו כח התפשטות הנפש המחי' את הגוף, מדת ב\"ו הוא הנפש בעל גבול אבל הוא ית' נשגב שמו מכל העולמות כנ\"ל, וזהו לא בא', אבל מצד קרבת נשמות בנ\"י שהם חלק אלקי' ממש<sup data-n=\"2252\">7</sup>, אע\"פ שהם נבראי', מ\"מ מקושרים בעצמיות אלקות יותר כידוע, ולכן לו צר בוי\"ו בכל צרתם, והוא לא מצד האמת מאחר שנשמתם בעל גבול אע\"פ שהם בבחי' חלק כידוע עכ\"ז נשגב שמו עליהם ג\"כ וד\"ל. רק שזהו בחי' חסד והמשכה מאלקים חיים כשיחמול עליהם שיהא לו צר בכל צרתם, ואף שיהי' לו צער, צער זה הוא חסד גדול שידלג ממהו', להיות צרתם לו צר וד\"ל. וכוונת המשכת לו צר כדי שאז יבטלו כל המקטרגי' עליהם, כי ה' אוהב משפט<sup data-n=\"2253\">8</sup> יושב ודן<sup data-n=\"2254\">9</sup> כו', מצד התפשטו' מלכותו ית', אבל כשהמלך חומל על אוהבו מצד שהוא מקושר בעצמותו יכול הוא לבטל בחטא האוהב מדת המשפט שאינה אלא בבחי' התפשטות חוקיו במדינה, והאוהב מקושר הוא בבחי' פנימית המלך שלמעלה מן התפשטותו וד\"ל.\n<b>וענין</b> קודב\"ה לשון קדוש הוא מובדל<sup data-n=\"2255\">10</sup> כמשל חיות הנפש מה שאין מופשט<sup data-n=\"2256\">11</sup> כלל בכלי הגוף שבאמת לא תתפעל כלל",[["2248","3","<b>באלקי' חיים</b>: ואתחנן ה, כג."],["2249","4","<b>כי נשגב שמו</b>: תהלים קמח, יג."],["2250","5","<b>בישראל עם קרובו</b>: שם קמח, יד."],["2251","6","<b>בכל צרתם לו צר</b>: ישעי' סג, ט. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תש ובהנסמן במ\"מ לשם. שה\"א ב, ב ובהערה 17."],["2252","7","<b>חלק אלקי' ממש</b>: ראה איוב לא, ב. דברי שלום לר' יצחק אדרבי דרוש שלישי (ויניצייא שנ\"ז ו, א ושם: שהן חלק מעצמותו ית'). אילת אהבים לר' שלמה אלקבץ שה\"ש א, ב (ירושלים תשל\"ג ט, ב). פרדס (שער הכוונה) של\"ב, רפ\"א. אור נערב ח\"א, ספ\"ג. ראשית חכמה שער האהבה פ\"א (ד\"ה עוד נתבאר — נג, ב). שער הקדושה פ\"ו (ד\"ה ובענין אם עטיפת ציצית — קמב, ד). רוממות אל תהלים כט, א. שושנת העמקים שה\"ש ז, יא. מדרש שמואל אבות פ\"ב, מ\"ה (ד\"ה אי נמי אמר אל תפרוש מן הצבור). סדר היום כוונת לעולם יהא אדם (ע' 49). כלי יקר בראשית א, לא. ב, ז. יתרו כ, יב. יג. תרומה כו, א. של\"ה בית חכמה יח, א. מס' חולין קטו, ב. מס' פסחים מצה עשירה קנח, ב. קסה, ב. מס' שבועות קפח, ב. קצד, ב. הקדמת מהרנ\"ש לפע\"ח. ובהוספת תיבת ממש <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא</a> רפ\"ב. שפע טל בהקדמה. חוקר ומקובל ח\"ג, פ\"א. מאור עינים פ' יתרו (לו, א ד\"ה אך) בשם מורו. פרי הארץ לרמ\"מ מוויטעבסק פ' וישב (ז, ב). מאמרי אדה\"א ויקרא ח\"א ע' שעג. וש\"נ."],["2253","8","<b>כי ה' אוהב משפט</b>: תהלים לז, כח."],["2254","9","<b>יושב ודן</b>: ע\"ז ג, ב."],["2255","10","<b>לשון קדוש הוא מובדל</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ\"ו</a> (ע' סו). מאמרי אדה\"ז תקס\"ו ע' קז: וזה הכלל בכ\"מ שנז' תיבת קדוש שהוא לשון הפרשה והבדלה. מאמרי אדה\"א ויקרא ח\"ב ע' תקסד. וש\"נ. שע\"ת עב, ג ובהערה 14. לקו\"ש במדבר (כרך יח) ע' 21 הערה 36. לקמן נד, ב. פ' תצוה שנח, א ובהערה 81."],["2256","11","<b>מופשט</b>: אב: מתפשט."]]],[2300540127,"בהרגשת כאב האברים והוא בחי' מקי[ף] על הגוף והוא ענין סוכ\"ע, שממכ\"ע הוא נמשל עכ\"פ בדוגמת התלבשות החיות בכלי הגוף, אע\"פ שאינו אמת כי נשגב שמו וד\"ל, עכ\"ז הוא בדוגמא זו כו'. אבל סוכ\"ע ענינו הוא עצמיות אור א\"ס ב\"ה שאינו מתפשט בעולמות כלל לחיות<sup data-n=\"2257\">12</sup> ראש ומקור לחיות הנברא. יובן מזה למשכיל בענין קבלת זיו השכינה בג\"ע<sup data-n=\"2258\">13</sup> שהנפש אלקי' הנברא תקבל ממקו' חוצבה בבחי' פנימי' שבה ופנימי' המשפיע אותה והוא ענין הזיו כידוע, אבל המצות מעשיות בזה העולם כמו ציצית מאד נעלים נהנין<sup data-n=\"2259\">14</sup> מזיו שבג\"ע, שהרי הציצי' החוטי' הגשמיי' הם מלבושי נוגה, אלא שהנפש מלבישם, וכמו\"כ הלבשה זו תלבש הנפש בציצית דלעילא בבחי' אצי' שהרי מצוה נק' אבר דמלכא<sup data-n=\"2260\">15</sup>. ופי' מלכא הוא הקב\"ה שהוא מובדל מכל העולמות כנ\"ל, ומצות ציצית הוא אבר ולבוש לעצמו' אוא\"ס ב\"ה וכמ\"ש במ\"א<sup data-n=\"2261\">16</sup>, וא\"כ הוא מאד נעלה מזיו השכינה כידוע בענין ציצית כנפי ז\"א דאצי' הם ל\"ב נתיבות חכמה<sup data-n=\"2262\">17</sup> המאירי' במוחי' דנוק' דז\"א דאצי' וד\"ל, וזהו אשר קדשנו במצותיו<sup data-n=\"2263\">18</sup> במצות<sup data-n=\"2264\">19</sup> הביא נשמות ישראל<sup data-n=\"2265\">20</sup> לבחי' קדש שהוא סוכ\"ע וכו'. ולכן יפה שעה אחת<sup data-n=\"2266\">21</sup> בתשו' ומע\"ט מכל חיי העוה\"ב שהוא זיו מל' דאצי' מהתפשטות<sup data-n=\"2267\">22</sup> ממנה אבל הציצית המה מוחי' פנימי' לה וד\"ל.",[["2257","12","<b>לחיות</b>: אב: להיות."],["2258","13","<b>קבלת זיו השכינה בג\"ע</b>: ראה ברכות יז, א. לעיל נ, ב. לקמן נח, ב."],["2259","14","<b>נעלים נהנין</b>: בג: נעלים מן נהנין."],["2260","15","<b>מצוה נק' אבר דמלכא</b>: נסמן לעיל פ' שמות מו, ב הערה 123."],["2261","16","<b>ומצות. . במ\"א</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380053\" data-slug=\"likkutei-torah\" data-id=\"4001380053\">לקו\"ת פקודי ג, ב</a> ואילך. לקמן נד, ג ובהנסמן לשם."],["2262","17","<b>ציצית. . ל\"ב נתיבות חכמה</b>: ראה גם לקמן נו, ב. וש\"נ."],["2263","18","<b>אשר קדשנו במצותיו</b>: נוסח ברכות המצות. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לא וע' קפו. דרך מצותיך ע' קסח."],["2264","19","<b>במצות</b>: ב: שבמצות."],["2265","20","<b>נשמות ישראל</b>: א: כנ\"י."],["2266","21","<b>יפה שעה אחת</b>: אבות פ\"ד, מי\"ז [בדילוג]."],["2267","22","<b>מהתפשטות</b>: בג: והתפשטות."]]],[2300540052,"<b>ב\"ה שבת שמברכין ר\"ח ניסן</b>\n<b>יוצר</b> אור ובורא<sup data-n=\"2268\">2</sup> חשך<sup data-n=\"2269\">1</sup>, הנה ההפרש שבין פסוקי דזמרה לברכת יוצר וכן<sup data-n=\"2270\">3</sup> ברכת יוצר לק\"ש הוא שבק\"ש הוא יחוד אצי' בבריאה<sup data-n=\"2271\">4</sup>, ובברכות<sup data-n=\"2272\">5</sup> יוצר הוא רק היכלות הבריאה<sup data-n=\"2273\">6</sup> ופסוקי דזמרה הוא רק היכלות דיצי'<sup data-n=\"2274\">7</sup>. ולהבין זה הנה ידוע שכל העולמות בי\"ע הם שנפלו משבירת הכלים דאצי'<sup data-n=\"2275\">*8</sup> הנק' מלכין קדמאין כו'. והיינו שמחמת פירוד ופירור השפעות שבבחי' אצי' נתהוה מהם בע\"ג, ואפי' [ה]מלאכים דבריא' שרובן טוב<sup data-n=\"2276\">8</sup> ואין בהם תערובות רע כלל רק מה שנתפסי' ליש ודבר מה הוא בחי' יש דקדושה, והוא שרש ופנימי' לקליפ' נוגה דבריאה ששם מתערבין טוב עם רע, אבל היכלות דקדושה שבנשמת האדם בחי' חכ' שבה הוא מבחי' הטוב שבנוגה, להיות כי ענין <span data-k=\"pg\">152</span> ּ החכמה האלקי' הוא",[["2268","2","<b>יוצר אור ובורא חשך</b>: ברכת יוצר. ישעי' מה, ז."],["2269","1","<b>יוצר אור ובורא חשך</b>: מאמר זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז. נדפס בשינויים במאמרי אדה\"ז אתהלך לאזניא ע' עה [טעם להשינויים — ראה הנרשם ברד\"ה שלפנ\"ז (נא, ג)]. הנוסח שבאתהלך לאזניא נדפס בשינויים והגהות וכו' באוה\"ת ואתחנן ע' שצב [ושם ההתחלה: הנה ההפרש בין ק\"ש ובין ברכותי']. ראה עוד ע\"ד המאמר וזמן אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["2270","3","<b>וכן</b>: אבד: ובין."],["2271","4","<b>שבק\"ש. . אצי' בבריאה</b>: ראה אור התורה ואתחנן כאן ע' שצב בהגהת הצמח צדק."],["2272","5","<b>ובברכות</b>: אבד: ובברכת. ובאור התורה כאן כבפנים."],["2273","6","<b>ובברכות יוצר. . היכלות הבריאה</b>: פע\"ח (שער הק\"ש) ש\"ח, פ\"א."],["2274","7","<b>ופסוקי דזמרה. . היכלות דיצי'</b>: פע\"ח (שער הזמירות) ש\"ז, פ\"א. פ\"ד."],["2275","*8","<b>דאצי'</b>: כ\"ה גם באד. ב: דנקודים."],["2276","8","<b>דבריא' שרובן טוב</b>: ראה ע\"ח (שער ק\"נ) שמ\"ט, פ\"ו. מאמרי אדה\"א בראשית ע' צז, וש\"נ."]]],[2300540090,"התפיסא וההשגה ביטול הנבראי' למקור חוצבם ושהוא ית' מהווה ומחי' אותם מאין ליש, נמצא שאהבה הנולדת מחמת ההתבוננות זו היא עיקרה מצד הנבראי' שהמה בטלים למקור החיים והנבראים הם מנוגה שנפלו בשבירת הכלים כו', א\"כ גם החכמה המשגת ביטול הנבראים הוא מבחי' נוגה, שהרי אין השגתה אלא יש ודבר של הנבראי' כו', אך הוא הטוב שבנוגה שהוא עיקר השגת ה' הוא הביטול שלהם למקורם כו', וא\"כ גם האהבה והתשוקה שנולדה מחמת טעם זה שהנבראי' בטלים ממציאותם הוא אהבה שנתחדשת מחמת טעם, ואין זה עיקר מהות ניצוץ אלקות, שהאהבה והתשוקה שבניצוץ אלקות להכלל במקורה אין שם התחדשות אהבה דהיינו שתהי' נולדת מחמת איזה טעם כו' אלא הוא בבחי' תמידי' מחמת עצמי' התקשרותה במקור חוצבה כמו עלי' והסתלקות אור השלהבת למקור האש היסודי שתמיד יתנועע<sup data-n=\"2277\">*9</sup> מצד שעצמותו נמשך לשרשו כו', ולא יהי' בו שינויי' בזה שלא יתנועע אלא כשיניעוהו ע\"י דבר אחר כו', ונמצא כשלא יהי' דבר אחר המניעו יתבטל תנועתו ויעמוד במ\"א כו', אלא יהי' תנועתו בתמידות בלי אמצעות דבר אחר כו', כמו\"כ תשוקת ניצוץ אלקות, מאחר שהוא חלק אלק' ממש ממילא יהי' תנועתו בתמידו' להכלל במקור החיים בלי אמצעו' ד\"א שיניענו כו' וד\"ל. אבל כשהתשוקה לה' תתעורר ע\"י התבוננות איזה טעם מפני שהוא המחי' והנבראים בטלים כו', ה\"ז כמשל ד\"א המניע ומעורר תשוקת הניצוץ כו', שהרי אם יהי' הטעם בטל תבטל לפ\"ע גם התשוקה מאחר שהיא נולדת עתה וד\"ל. ועפ\"ז יובן למשכיל שהנבראי' נק' טוב שבנוגה מפני זה, להיות כי מקבלין דין מן דין<sup data-n=\"2278\">9</sup>, פי' שמתפעלי' בגודל התשוקה לה', מאחר שרואי' התהוות עצמותם מאין ליש ה\"ז כד\"א המניע כו', ולכן יהי' בהם שינויי' בתשוקת' פעמי' בתגבורת ופעמים בקטנות לפ\"ע ד\"א שהוא המניעם כו', שהוא בחי' חכמה שבהם המשגת התהוותם וד\"ל. אך מובן שאעפ\"כ א\"א להתגלות ניצוץ אלקות אלא ע\"י החכ' שהוא נפש השכלית שבאדם שמתהפכת לרע ג\"כ להשכיל ענינים זרים כו', ובלעדי החכ' להכיר בוראו מצד שהוא מחי' הנבראים כו', הי' הסתלקות ניצוץ אלקות שהוא הרצון בלי טעם כלל לא<sup data-n=\"2279\">*10</sup> הי' מאיר כלל בכלי הלב הגשמי שנמשך אחר הבלי העולם איך יהי' בו התנועה העצמי' להדבק ולהכלל (בלי טעם ביטול הנבראים כו', אע\"פ שאינן בטילים רק שתהי' גודל",[["2277","*9","<b>יתנועע</b>: ב: יתנענע. ג: מתנונע. אד: כבפנים"],["2278","9","<b>מקבלין דין מן דין</b>: ת\"י ישעי' ו, ג."],["2279","*10","<b>לא</b>: ב: ולא. אגד: כבפנים."]]],[2300540128,"התשוקה להוי' שאין לו תחלה והוא בחי' אור א\"ס ב\"ה<sup data-n=\"2280\">10</sup>, אבל החכמה וההתבוננו' ביחו\"ע ויחו\"ת איך שהז' רקיעים שבכל עולם לפי ערכו בטילים באחד כו' היא המוציאה העלם הרצון לידי גילוי שיחפוץ להדבק בא' בלי שום טעם והתבוננו' כלל והוא ענין ואהבת עתיד כו', שע\"י החכמה שבשבחי פסוקי דזמרה וברכת יוצר אור תגיע לבחי' ניצוץ האלקי שהוא הכרח האהבה והרצון מאליו מצד עצמיותה כנ\"ל לא מצד הטעם שע\"ז ואהבת בלשון ציווי<sup data-n=\"2281\">*11</sup>, לפי שבהעדר החכמה תבטל האהבה כנ\"ל וד\"ל, אבל האהבה שע\"י ציווי החכ' תמשיך גילוי הכרח האהבה מצד עצמיו' כנ\"ל והוא ואהבת לשון עתיד וד\"ל (והרמב\"ם<sup data-n=\"2282\">11</sup> הי' לו נשמה גבוה והתפעלותו ע\"י התבוננו' סבור הי' שמחמת התבוננותו והשגתו <span data-k=\"pg\">עו</span> ּ לבד היתה עוצם התפעלותו ואינו כן שהשגתו לא הי' רק גרמא בעלמא להוציא מן ההעלם כנ\"ל<sup data-n=\"2283\">12</sup> ).\n<b>וזהו</b> שבק\"ש הוא יחוד אצי' בבריאה דהיינו המשכת ותנועת ניצוץ אלקות מצד העצמי' שלה המקושרת במקור חוצבה בבחי' אצי' כו' כשמתגלים ע\"י החכ' והשגות באלקות נק' יחוד הארת אצי' בבריאה טוב שבנוגה כנ\"ל וד\"ל. אבל בברכת יוצר אור אע\"פ שההשגות בשבחי' הם מאד נעלים ונק' היכלות דבריאה שאין בהם תערובות כלל כשהם מופשטים מכל גשם להיות מתגדל מהם הלא דבר הוא שזהו בחי' נוגה להתהפך כו' וד\"ל, עכ\"ז בבחי' בריאה הם בלא הארת בחי' אצי' בהם דהיינו התקשרות מצד עצמיות כמו המשכת בן אל האב שהוא רק מפני שהוא נלקח ממנו ואינו יודע שום טעם בשבחי אביו וכל העתים שוות אצלו, ואפילו יראה חסרונות באביו לא יוגרע ההמשכה כלל כו', אבל העבד או אפי' התלמיד יהי' התקשרות שלו רק לפי אופן קבלתו מן הרב וכו', והוא התהוות עצמותו כנ\"ל וד\"ל. ועכ\"ז יש יתרון בגילוי הרצון ע\"י חכמה יותר מכמו שהי' בלא חכמה כמו בשעת ק\"ה<sup data-n=\"2284\">13</sup> כידוע, להיות כי חשך הנוגה שרואה יש ודבר מסתיר מאד הגילוי תשוקת הרצון שלא תבא כ\"א לעתים רחוקים, אבל ע\"י החכמה הרי בירר הרע מן הנוגה ואף שיראה עולם ומלואו הרי מבין ומשיג שהם בטלים למקורם כו', ולכן תתחזק הרשימו כל היום שלא תחשיך רע דנוגה רק מצד החכמה כו', אבל מצד הרצון מפני העלמו מחושך הנפש השכלית דנוגה אף שהיתה מתגלית אין רשימו שלה חזק כלל שמיד יסתירנה העולם וד\"ל.\n<b>והנה</b> ההפרש שבין פסוד\"ז וברכת יוצר שזה נק' יצירה וזה בריאה ושניהם בסידור שבחיו שהוא עיקרא ושרשא",[["2280","10","<b>ב\"ה</b>: כנצ\"ל: ב\"ה)."],["2281","*11","<b>ואהבת עתיד. . ציווי</b>: ואתחנן ו, ה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381047\" data-slug=\"likkutei-torah\" data-id=\"4001381047\">לקו\"ת סוכות פ, ד</a>. לקמן פ' ויקהל תלו, ג."],["2282","11","<b>(והרמב\"ם</b>: ד ניתוסף: ז\"ל. ראה גם מאמרי אדה\"ז כתובים ח\"א ע' קכד. שני המאורות להרי\"א מהאמליע (קה\"ת תשל\"ב) ריש ע' קי."],["2283","12","<b>(והרמב\"ם. . כנ\"ל)</b>: באוה\"ת כאן לא הועתק. וכן ליתא בג."],["2284","13","<b>ק\"ה</b>: קידוש השם."]]],[2300540165,"דכ\"ע<sup data-n=\"2285\">14</sup> כו', וכולא קמי' כלא חשיב<sup data-n=\"2286\">15</sup> כו'. אך בפסוד\"ז כל עיקר ההשגה אינה אלא ביטול מל' דאצי' מקור כל המוגבלי' דבי\"ע לגבי ז\"א דאצי' עד בחי' מקור מוחין דז\"א שהוא בחו\"ב דאצי'. וזהו ברוך אתה הוי'<sup data-n=\"2287\">16</sup> אלקי ישראל דאצי' מן העולם דאצי' עד י\"ס דבי\"ע כו', שנק' ועד העולם כו', וכן כל ההעלאות עד\"ז מן הללו את ה' מן השמים<sup data-n=\"2288\">17</sup> כו' וד\"ל. אבל בברכת יוצר אור הוא השג' ביטול כל עיקר עולם אצי' שהוא חכ' דאצי' לגבי עולם הנקודים<sup data-n=\"2289\">18</sup> שהוא בחי' תחתונה שבמאציל כו', להיות כי י\"ס דאצי' המה נק' נאצלים ולא<sup data-n=\"2290\">19</sup> נאצל כמו לשון נתהווה בבריאה אלא ששם הוא בבחי' נפרד ונאצל הוא בבחי' עצמיות, אבל מאחר שנאצל עתה הוא שנאצל ותחלה הי' כלול בעצמותו, ואין לו ערך לגבי העצמיות כמו האדם הגשמי כשלא יתגלה בו כחות נפשו באיזה אהבה או שכל גלויי' כו', אז נק' הוא האדם העצמי, אבל מה שמתגלי' בו שכליו' ומדות המה הארות בעלמא שמתהווי' בזמנים שונים ובקטנות וגדלות כו' וד\"ל. ולכן בברכת יוצר נזכר כללות ענין י\"ס דאצי' שהמה בבחי' עשי' בבחי' עצמיו' כמו ערך עשיי' לגבי מחשבו' ודבור בנפרד לזולתו כו', כמו\"כ ערך גילוי כחות הנפש בעצמיי' לגבי העצמיי' שבלא גילוי הוא נק' בשם עשיי' וד\"ל. וזהו מה רבו מעשיך שבכל עולם דאצי' המתחדש בטובו יסוד דעתיק דאצי' כל מ\"ב<sup data-n=\"2291\">20</sup> חו\"ב דאצי' כולם בחכ' עשית, פי' כולם הם בחי' העשיי' לגבי עולם העקודי' שהוא למעלה מבחי' עשיי' שבנקודי' הוא שרש התהוות אותיות וכלים דאצי', אבל בעקודים אין שם שרש <span data-k=\"pg\">154</span> ּ כלים להיות כי הוא לבוש האמצעי לגבי א\"ק כו', שהוא לבוש הבל הדיבור שהוא הגבה למעלה מלבוש העשיי' כו', ובדיבור הכל בכלי א'<sup data-n=\"2292\">21</sup> שהוא אותיות הדיבור שהם אורו' רבים בהבל א' שבפה ולא יהי' שינוי הבלי' לכל אות בפ\"ע כו', אבל בכח המעשה לכל המשכת כח פועל הציור יהי' בנפעל ציורי' מחולקי' לפי רבוי כחות הנמשכי' וד\"ל. כי בדרך כלל עולם העקודי' הוא קיבוץ הבלי' דאח\"פ דא\"ק, ועולם האצי' הוא לבוש המעשה וד\"ל. וזהו המאיר לארץ ולדרים עלי', פי' שמבחי' תחתונה שבמאציל כל הנאצלי' יומשך ר\"ר על גודל שפלות ערך הנאצלי' ויומשך לכולם בשוה לראשם ולסוף כל דרגי' שבהם בשוה דהיינו לארץ שהוא מל' דעולם האצי' ולכל הדרי' עלי' שהוא אדם דאצי' ולמקור חו\"ב שבו כו', וכשמאירי' ר\"ר תחלה ע\"י העלאת מ\"ן שלהם שהם בוכין אנן בעינן למהוי<sup data-n=\"2293\">22</sup> כו' אז יתחדשו ענין אצילותם מחדש. וזהו שאח\"כ ומחדש בכל יום בטובו מעתיק דעולם האצי', כל מעשה בראשי' בכל יום ומדה מאינון יומין עילאי'<sup data-n=\"2294\">23</sup> כידוע וד\"ל. אבל המלך המרומם הוא בחי' עתיק דכל הנאצלי' הוא מרומם ונשגב בערך",[["2285","14","<b>עיקרא ושרשא דכ\"ע</b>: זהר בהקדמה יא, ב."],["2286","15","<b>וכולא קמי' כלא חשיב</b>: נסמן לעיל פ' שמות לח, א."],["2287","16","<b>ברוך אתה הוי'</b>: תהלים קו, מח. דהי\"א טז, לב [בהוספת תיבת ”אתה\" — ראה מאמרי אדה\"ז תקע\"א ע' נד. (לקמן פ' בשלח קסב, א). אוה\"ת נ\"ך כרך ג ס\"ע א'שכח]. דהי\"א כט, י [ושם: אבינו מעולם]. רש\"י ברכות נד, א ד\"ה כל חותמי. תענית טז, ב ד\"ה אבל."],["2288","17","<b>הללו את ה' מן השמים</b>: תהלים קמח, א."],["2289","18","<b>הנקודים</b>: כ\"ה גם באד. באוה\"ת כאן (ע' שצד): עקודים — אבל הוא הנוסח דאתהלך לאזניא כאן (כמובא לעיל בריש המאמר)."],["2290","19","<b>ולא</b>: כ\"ה גם באד. ב: ולשון."],["2291","20","<b>מ\"ב</b>: ד: מע\"ב מעשה בראשית."],["2292","21","<b>בעקודים. . כלים. . הכל בכלי א'</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"א. (שער מול\"מ) ש\"ז, פ\"א. מבו\"ש ש\"ב ח\"ג פ\"ז. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' סד ואילך."],["2293","22","<b>שהם בוכין אנן בעינן למהוי</b>: נסמן לעיל פ' שמות ב, ב הערה 92."],["2294","23","<b>מאינון יומין עילאי'</b>: (לשון ה)זהר ח\"ש קכט, א."]]],[2300540202,"מכללות עולם האצי' ולכן נק' עתיק שנעתק לגמרי מהיומין<sup data-n=\"2295\">24</sup> ומדות דאצי', וזהו המתנשא מימות עולם דאצי' להיות כי החכמה אע\"פ שבחי' חיצוני' שבה הוא המקור לחיות המדו' שבה כידוע ולא הפנימי' שבה, עכ\"ז יש לה ערך עם המדות, שהרי בהשכיל באיזה דבר יתגלה מיד המדה לאותו הדבר כו', אבל בהעונג המכריח הרצון שירצה אותו הדבר כו', עדיין אין שם שום רמז לאיזה תולדות מדה אהבה או התפארו' כו', אלא באותו הדבר עדיין אצלו בבחי' עצמיי' שבו עד שכשירצה לאותו הדבר הוא צמצום עצמותו מן הדבר כו' וד\"ל. והנה המתענג מבגד נאה שהוא יפה מאד בציורי', הרי כשכבר מלובש והולך בבגד הנאה לפני זולתו יתהווה בו מדת ההתפארו' להתפאר בבגדו זה לפני זולתו שבעיני זולתו יתראה לאיש יפה ע\"י יופי הציור הבגד כו', אבל כשהבגד הי' שטוח על הכותל רק העונג ממנו כשילבשנו יתפאר בו כו', נמצא שעונג זה הוא מקור מדת ההתפארו' שיהי' מהות ההתפארו' נמצא בו ולא מקור להוליד המדות התפארות שאינה אלא בשעה שהוא מלובש שהשכל ימשיך ההתפארו' כו' (וע\"פ משל זה יובן לשון מפואר (שיש הפרש בין מפואר כמו משובח דהיינו שנתפאר אבל מפואר בחולם שהוא שעושה התפארת) הנאמר בבחי' עתיק שאין הכוונה שהוא מקור להוליד מדת ת\"ת דאצי', כמו למשל האדם המפואר בשעת התלבשו בבגד נאה כו', אלא הכוונה הוא פאר ההתפארות שהוא יותר יפה מן התפארת עצמה כמו נזר ועטרה השטוחה על הכותל שאין בה התפארת מצד עצמותה כו', רק כשילבשנה אדם בראש[ו] יהי' מאד יפה ומהודר מחמתה נמצא שמקבל תפארת ממנה אבל היא עצמה פאר תפארתו וד\"ל). ועפי\"ז יובן למשכיל שג' דברים אלו משובח ומפואר ומתנשא שבמדות דאצי' הכל הוא בת\"ת דאצי' ובת\"ת דאימא שהוא עטרת תפארת לז\"א<sup data-n=\"2296\">25</sup> דאצי' כידוע כולם אין ערוך למלך המרומם שהוא פאר התפארת ושבח התשבחו' כו', כמ\"ש ישראל (דאצי') אשר בך אתפאר<sup data-n=\"2297\">26</sup> בעטרה שעטרה לו אמו<sup data-n=\"2298\">27</sup> וד\"ל. וכן במתנשא שהוא כתר מל' אין ערוך לכתר ז\"א וכתר מל' דאצי' שנעשו מת\"ת דאימא כו', לגבי כתר דע\"י המלך המרומם לבדו כו', שהתנשאותו הוא מקור האמיתי שימצא שום התנשאות בעולם וד\"ל. וזהו אלקי עולם <span data-k=\"pg\">עז</span> ּ ו\"ק דאצי' שהוא מהארת בחי' תחתונה שבמאציל, והוא שרש כל הנאצלים שהמה נק' מעשה ידיו לבד כו', והמש[י]ך עליהם הארת מקיפי' להיות",[["2295","24","<b>עתיק שנעתק לגמרי מהיומין</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"ב ס\"ע תקלב. תקס\"ה ח\"ב ע' תתקמא. לקמן פ' בשלח קמב, סע\"ב ובהערה 48. מאמרי אדה\"א בראשית ע' רסא. קונטרסים ע' רפט. ובהנסמן בהנ\"ל. שעה\"י קכו, א."],["2296","25","<b>ובת\"ת דאימא. . לז\"א</b>: ראה ע\"ח (שער מוחין דצלם) שכ\"ג, רפ\"ה ורפ\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["2297","26","<b>ישראל. . אשר בך אתפאר</b>: ישעי' מט, ג."],["2298","27","<b>בעטרה שעטרה לו אמו</b>: שה\"ש ג, יא."]]],[2300540235,"צור ומשגב בעדם, והם ד' מיני מקיפים אדון עוזינו<sup data-n=\"2299\">28</sup> צור משגבינו וכו'.",[["2299","28","<b>ד' מיני מקיפים אדון עוזינו</b>: ברכת יוצר. ראה גם לקמן פ' בשלח קעא, ד. רלו, א ואילך. משפטים רצט, ד. מאמרי אדה\"א דברים ח\"ג ע' תתנה. וש\"נ. שע\"ת פג, ב ובהערה 17."]]],[2300540053,"<b>ליל שבת שבתוך חג הפסח</b>\n<b>עריבים</b> עלי דברי סופרים<sup data-n=\"2300\">1</sup> יותר מיינה של תורה<sup data-n=\"2301\">2</sup>, הנה תחלה צריך להבין פי' אור א\"ס<sup data-n=\"2302\">*3</sup> הנז' בע\"ח תמיד שאין ר\"ל אור וזיו<sup data-n=\"2303\">3</sup> של א\"ס ומהותו ועצמותו ית' נקרא א\"ס ואורו נקרא אור א\"ס, שהרי לא שייך לומר על מהותו ית' שאין לו סוף, [שענין אין לו סוף] ואין לו תחלה כו' הוא על התפשטות דבר מה שאז שייך לומר שאין סוף ואין תחלה להתפשטות<sup data-n=\"2304\">4</sup> שתתפשט בלי גבול כו', אבל על העצם שאינו בערך התפשטות זיו והוא הנק' מאור ולא אור לא שייך לו' אין קץ וסוף כו', כמשל זיו השמש שעל אלה<sup data-n=\"2305\">5</sup> זיו השמש שייך לומר אין קץ וסוף להתפשטות האור עד למרחוק מאד אלו הי' כן כו', אבל על המאור שהוא השמש עצמו שאינו בגדר וסוג הארה וזיו כלל לא שייך לו' אין קץ להארתו כו'. או כמו התפשטו' חיות עצם הנפש אלו הי[תה] התפשטו' שלה להחיות גופי' בלי גבול שייך לומר שאין להתפשטו' קץ כו', אבל להעצם שאינו בגדר חיות להחיות לא שייך לומר אין לו גבול כו'. וא\"כ מובן למשכיל פי' אור א\"ס שהאור הוא הנק' א\"ס והוא בחי' מל' דא\"ס כמשארז\"ל [קודם שנברא העולם] היה הוא ושמו לבד<sup data-n=\"2306\">6</sup> כמו<sup data-n=\"2307\">7</sup> קודם שהאציל וברא כו', והוא הנק' מאציל הע\"ס דעקודים נקודים וכל פרטי הנאצלים הוא רק מן בחי' זיו ואור עצמותו ית' והוא הנק' א\"ס, ופירושו שאין קץ וגבול להתפשטו' אור עצמותו<sup data-n=\"2308\">8</sup> ית' להאציל נאצלים בלי מספר ממש<sup data-n=\"2309\">9</sup> כמ\"ש לתבונתו אין מספר<sup data-n=\"2310\">10</sup>, פי' אף שבהמשכת אורות דאצי' בכלים ואותיות להוות הבעל גבול הרי יש מספר לבעלי גבול וגם זמן קיומם קצוב שית אלפי שני<sup data-n=\"2311\">11</sup> כו', אבל בחי'",[["2300","1","<b>עריבים עלי דברי סופרים</b>: מאמר זה הוא דרוש כ\"ק אדה\"ז ונרשם בשעתו ע\"י כ\"ק אדה\"א. קיצור מהדרוש נדפס באוה\"ת על מארז\"ל ע' מח. ראה עוד ע\"ד המאמר ותאריך אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["2301","2","<b>עריבים. . של תורה</b>: ראה ע\"ז לה, א וברש\"י שם."],["2302","*3","<b>אור א\"ס</b>: ראה גם לקמן פ' ויקהל שפח, ג."],["2303","3","<b>וזיו</b>: אה: נק' זיו."],["2304","4","<b>סוף. . להתפשטות</b>: אה: לו סוף ו[אין לו] קץ לההתפשטות."],["2305","5","<b>אלה</b>: הט: אור."],["2306","6","<b>קודם. . ושמו לבד</b>: ראה ד\"ה ויאמר ה' גו' מה תצעק אלי תרמ\"ד, תרנ\"א ס\"ט [ושם: בפר\"א פ\"ב]. וש\"נ. ראה פדר\"א פ\"ג. הנסמן במ\"מ למאמרי אדה\"ז על פרשיות התורה ח\"א לע' שיג. מאמרי אדה\"א דברים ח\"ד ע' א'רעא. לקמן פ' ויקהל שפח, ד."],["2307","7","<b>כמו</b>: הט: ליתא."],["2308","8","<b>אור עצמותו</b>: אה: אורו."],["2309","9","<b>ממש</b>: אה: ליתא."],["2310","10","<b>לתבונתו אין מספר</b>: תהלים קמז, ה."],["2311","11","<b>שית אלפי שני</b>: ראה ר\"ה לא, א. הנסמן במאמרי אדה\"א בראשית ע' נג."]]],[2300540091,"נפש שבכל עולם ועולם הוא ממש אור א\"ס שהאציל ראשית הקו כו', פי' כי עולם שנה<sup data-n=\"2312\">13</sup> נפש<sup data-n=\"2313\">12</sup> בכללו' וגם בפרטות בכל עולם ועולם<sup data-n=\"2314\">14</sup>, וכמו שבכללות נק' עולם כללות הנבראי' דבי\"ע, ושנה הוא ג\"כ זמן<sup data-n=\"2315\">15</sup> קצוב מאורות דאצי' ע\"י הכלים כי אלף שנה<sup data-n=\"2316\">16</sup> דבי\"ע כיום א' מיומין עילאין דאצי' כו', אבל בחי' נפש הוא עצמו' האורות<sup data-n=\"2317\">17</sup> הנאצלי' אין להם גבול ומספר כלל וכנז' באד\"ר ת' אלף<sup data-n=\"2318\">18</sup> כו'. וכיוצא בזה בכל פרט[י] בחי' הנפש והאור של הנברא הרי שרשו מבחי' נפש הכללי שהוא בחי' א\"ס ממש<sup data-n=\"2319\">19</sup>, וכמשל התפשטות חיות הנפש בכלי האברים נק' אור כמו כח הראי' [שנתפשט] בעין שאע\"פ שלפי אופן צמצום התפשטות כח הראי' כבר בעין לא יראה יותר מכפי אופן כלי מזג העין הגשמי המגביל כח הראות, אבל כח הראי' עצמה קודם התלבשותה הוא אור הראי' האמיתי', יראה בבחי' בלי גבול להתפשטות שלה כו'. ויובן עפ\"ז שבעולם האצי' אף שבכללותו אינו אלא ע\"ס רצון<sup data-n=\"2320\">21</sup> וחכמה כו' אבל יהי' התחלקות פרטיהם<sup data-n=\"2321\">20</sup> מעילה לעלול בלי גבול וקץ ממש כו' מאחר ששרש כל הנאצלים הוא [מ]בחי' תחתונה שבמאציל והמאציל הוא הנק' אור<sup data-n=\"2322\">22</sup> א\"ס פי' שהאור א\"ס כנ\"ל, וכמו שהמאציל האורות הוא בבחי' א\"ס כמו\"כ הנאצלים אין להם <span data-k=\"pg\">156</span> ּ גבול וקצבה כלל וכמ\"ש אנת הוא חד<sup data-n=\"2323\">23</sup> ולא בחושבן ר\"ל דבנאצלים אף שהם בלי גבול עכ\"ז יש הפרש בין חכמה דאצי' לבינה כו', אבל אנת חכים<sup data-n=\"2324\">24</sup> ולא בחכמה ידיעא פי'<sup data-n=\"2325\">25</sup> י\"ס הגנוזות<sup data-n=\"2326\">26</sup> במאציל עצמו אין שם הפרש בין חכמה לבינה כי אין החכמה ידוע ולא הבינה ידיעא כו' וכמ\"ש<sup data-n=\"2327\">27</sup> במ\"א<sup data-n=\"2328\">28</sup>.\n<b>והנה</b> כתיב ואהבת את הוי' אלקיך<sup data-n=\"2329\">29</sup> פי' את [הטפל<sup data-n=\"2330\">30</sup> ל]עיקר ההוי' והוא אור א\"ס ב\"ה המאציל כל הנאצלים בלי גבול וקץ כו', להיות כי צריך שתאיר בנפשו ההתבוננו' שמתבונן באור א\"ס ב\"ה שמחמתו נולדה האהבה והתשוקה הנולדת מהתבוננות זו היא הגורמת התגלות האור שתאיר אור א\"ס בהתגלות וזהו ואהבת את כו', וכמו שהאור האלקי המתגלה בנפשו לאחר האהבה והתשוקה הוא בחי' א\"ס כמו\"כ צריך להיות האהבה בלי גבול ובלי הפסק, והרי לא כן במדת האהבה שמוכרח שתפסק כרגע אף שהיתה מלב ונפש כו' ולכן הוא אומר ובכל מאדך<sup data-n=\"2331\">31</sup> בלי [גבול ובלי] הפסק כלל, והיינו בחי' אל דמי לך<sup data-n=\"2332\">32</sup> שלמעלה ממדת אהבה שאהבה נק' כסף<sup data-n=\"2333\">33</sup> ותשוקה ונולדת ונפסקת כו', אבל הזהב הוא בחי' התפעלות בעצמיות שלא יוכל לשקוט ולא ינוח מגודל רשפי אש מפני שניזוז ממקומו לגמרי",[["2312","13","<b>עולם שנה נפש</b>: ראה ס\"י פ\"ג, מ\"ג ואילך. מאמרי אדה\"א בראשית ע' נו. וש\"נ. שע\"ת ע, א ובהערה 8. לקמן פ' תצוה שכא, ב."],["2313","12","<b>עולם שנה נפש</b>: אה: ע\"ס יש."],["2314","14","<b>ועולם</b>: אה: ליתא."],["2315","15","<b>ג\"כ זמן</b>: אט: זמן ג\"כ."],["2316","16","<b>כי אלף שנה </b>[אה: שנים]: כ\"ה גם לקמן פ' ויקהל שצא, ב ושם נדפס מגוכי\"ק. וש\"נ."],["2317","17","<b>האורות</b>: אה: ליתא."],["2318","18","<b>באד\"ר ת' אלף</b>: ראה גם אוה\"ת וארא ריש ע' קצז ואילך."],["2319","19","<b>ממש</b>: ט: ליתא."],["2320","21","<b>ע\"ס רצון</b>: ראה סה\"מ תש\"ח ס\"ע 242 ואילך ובהערה שם. אוה\"ת יתרו ס\"ע תתלט ואילך. ביאוה\"ז — להצ\"צ — תשא (כרך א) ע' ערה ואילך."],["2321","20","<b>יראה. . פרטיהם</b>: אה: הי' יכול להיות ממנה התחלקות פרטיות."],["2322","22","<b>אור</b>: אה: ליתא."],["2323","23","<b>אנת הוא חד</b>: ת\"ז בהקדמה (יז, א)."],["2324","24","<b>אנת חכים</b>: ת\"ז שם (יז, ב). ראה לקמן פ' יתרו רסז, רע\"א."],["2325","25","<b>פי'</b>: אה: אפי'."],["2326","26","<b>י\"ס הגנוזות</b>: נסמן לעיל פ' שמות כח, ד."],["2327","27","<b>אין שם הפרש. . וכמ\"ש במ\"א</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' סד ואילך. אתהלך לאזניא ע' סט. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370043\" data-slug=\"torah-or\" data-id=\"3901370043\">תו\"א נח י, ג</a>."],["2328","28","<b>במ\"א</b>: אה: ניתוסף: בבחי' בלי גבול וה[ה]תפשטות שלה כו'. ויובן עפי\"ז שבעולם האצי' אף שבכללותה אין שם אלא ע\"ס רצון וחכ' כו', אבל יהי' כו'."],["2329","29","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה."],["2330","30","<b>את [הטפל</b>: ראה ברכות לו, ב."],["2331","31","<b>ובכל מאדך</b>: ואתחנן ו, ה."],["2332","32","<b>אל דמי לך</b>: נסמן לעיל מט, ד הערה 11."],["2333","33","<b>שהאהבה נק' כסף</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310055\" data-slug=\"tanya\" data-id=\"3401310055\">תניא פ\"נ</a>. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קפה. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370126\" data-slug=\"torah-or\" data-id=\"3901370126\">תו\"א וישב כו, ד</a>. תשא פו, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380441\" data-slug=\"likkutei-torah\" data-id=\"4001380441\">לקו\"ת בהעלותך לב, ד</a>. מסעי צ, סע\"ב."]]],[2300540129,"ולא ירגיש כלל בעצמותו, ולא יהי' בלבו לא אהבה ולא שום רצון רק גודל ההתפעלות לבד ולא ידע מהו, כמו מי שנתפעל ויצא מדעתו ולבו כשרואה מלך גדול וכדומה שאין אז בלבו שום אהבה ורצון כו' כידוע. ולהיות כי ההתפעלות עצמה הנ\"ל הוא סימן להתקשרות גדול[ה] בעצמיות הדבר שמתפעל מחמתו כידוע לכן כתיב ובכל מאדך שאין שיעור וגבול כלל להתפעלו' העצמי[ות] ולא תופסק כלל [וכלל], כמו עצמי[ות] הדבר שנתפעל מחמתו אין לו שיעור שהוא נק' אוא\"ס, כמו\"כ ההתפעלו' מחמתו כשהוא בקירוב אין לו הפסק כלל, ולכן כתיב אל דמי [לך] לא שכיך כלל וד\"ל. והנה מאחר שכן האיך אפשר ליפסק מהתפעלות העצמיי' והי' צריך שיתפלל אדם כל היום כולו<sup data-n=\"2334\">34</sup>, ואם יכול להפסיק אין זה מדרי' אל דמי לך ואינו אמת כו', ואם יפסיק מפני שירצה בהמשכות אלקות בבחי' עשיי' המצות ודברי לימוד התו' ה\"ז שפלות וירידה גדולה ולא ישמח בזה וכתיב תחת אשר לא עבדת<sup data-n=\"2335\">35</sup> ה' בשמחה ו[ב]טוב לבב דייקא כו'.\n[ב] <b>אך</b> הענין הוא דהנה ארז\"ל יפה שעה אחת<sup data-n=\"2336\">36</sup> בתשובה ומע\"ט [בעוה\"ז] מכל חיי העוה\"ב, והוא ענין<sup data-n=\"2337\">37</sup> ו[ב]טוב לבב מרוב כל, שהעבודה בתו\"מ בשמחה ו[ב]טוב לבב הוא יותר טוב ממדרגו' רוב כל הנק' חיי העוה\"ב<sup data-n=\"2338\">38</sup> וכמ\"ש במ\"א. ותחלה צריך להבין ענין רוב כל, דהנה כל נק' בחי' יסוד<sup data-n=\"2339\">39</sup> שהוא המקור העצמי לגבי מל' והוא המשפיע כללות החיות ונק' חי העולמים<sup data-n=\"2340\">40</sup> כידוע והוא יסוד ז\"א דאצי', ויסוד אבא הוא המשפיע היותר גדול להיות כי המדות נולדי' ממנו כידוע עד שיסוד אריך הוא הגדול מכולם ונק' רב כל<sup data-n=\"2341\">42</sup>. ובטובו<sup data-n=\"2342\">43</sup> הגדול ישוב חרון אפו<sup data-n=\"2343\">44</sup> כו', פי' טובו הגדול הוא להיות כי הולדת אור החכ' שיוליד המדות הוא מיסוד א\"א<sup data-n=\"2344\">45</sup> שהוא הרצון כידוע לכן השפעת הרצון הוא הגדול מכולם<sup data-n=\"2345\">41</sup> וכוללם יחד, פי' שלהיותו עיקר המקור שממנו נמצא כל נמצא כו' נק' בשם אריך, פי' אריכות כמו אריכות חבל ארוך שאין לו קץ שישתנה בו הראשית<sup data-n=\"2346\">46</sup> והסוף דמאחר שאין לו סוף אין לו ראשית<sup data-n=\"2347\">47</sup> א\"כ הגבוה שבו עם הנמוך שבו שוין ממש וד\"ל. וזהו הכלל שכל הגבוה יותר<sup data-n=\"2348\">48</sup> בעצם יכול להשפיל [את] עצמו ביותר למטה, כמו חכם <span data-k=\"pg\">עח</span> ּ מופלג מאד יוכל",[["2334","34","<b>שיתפלל אדם כל היום כולו</b>: ראה ברכות כא, א."],["2335","35","<b>תחת אשר לא עבדת</b>: תבוא כח, מז [ושם את ה\"א — ראה מאמרי אדה\"א במדבר ח\"ג ע' א'מח]."],["2336","36","<b>יפה שעה אחת</b>: אבות פ\"ד, מי\"ז."],["2337","37","<b>ענין</b>: אט: ניתוסף: בשמחה."],["2338","38","<b>רוב כל הנק' חיי העוה\"ב</b>: ראה לעיל נ, סע\"ג ובהערה 57."],["2339","39","<b>כל נק' בחי' יסוד</b>: ראה זהר (רע\"מ) פינחס רנז, א. מאמרי אדה\"א ויקרא ח\"א ע' רכד. דברים ח\"ב ע' תרפז ובהנסמן בהנ\"ל. לקמן פ' בא ק, ג הערה 178. בשלח ריט, ג. תצוה שנא, ד. פקודי תנה, ג."],["2340","40","<b>יסוד. . ונק' חי </b>[אהח: חיי]<b> העולמים</b>: ראה זהר מקץ קצג, ב. יאיר נתיב למאו\"א מערכת חי סכ\"ד. שעה\"י קלד, א."],["2341","42","<b>רב כל</b>: ט: רוב כל. אבל באוה\"ת כאן: רב כל, וכמו ורב טוב. אבל בסה\"מ תרנ\"ז ס\"ע קצז: רוב כל."],["2342","43","<b>ובטובו</b>: באוה\"ת כאן [ראה הערות 42. 41]: וע\"ז נאמר ובטובו."],["2343","44","<b>ובטובו הגדול ישוב חרון אפו</b>: כ\"ה גם באוה\"ת כאן. סה\"מ תרנ\"ז ס\"ע קצז. ראה (תפלת השחר) רבונו של עולם [ושם: ובטובך. . אפך]."],["2344","45","<b>ובטובו הגדול. . מיסוד א\"א</b>: ראה גם סידור סדר סעודת שבת רב, א [ושם: ובטובו]. מאמרי אדה\"ז על ענינים ע' קמב. ע' רח. ע' תה. שעה\"י קכה, א."],["2345","41","<b>ונק'. . מכולם</b>: אח: ליתא. וכנראה נשמט מפני תיבות הדומות. . מכולם. . מכולם. ולכאו' קטע זה לא הי' לפני הצ\"צ — ראה לקמן ברשימת הכת\"י בוך ח. וראה הערה הבאה."],["2346","46","<b>הראשית</b>: חט: הראש."],["2347","47","<b>ראשית</b>: אחט: ראש."],["2348","48","<b>שכל הגבוה יותר</b>: נסמן לעיל פ' שמות כא, ב."]]],[2300540166,"יותר להסביר דבר שכל לתינוק, יותר מחכם קטן ממנו מפני שאצל חכם הקטן ממנו יתפס שכל התינוק לדבר מה לפ\"ע כו', אבל לגבי חכם הגדול אין לשכל הקטן מקום כלל, לכן יוכל יותר להשפיל [את] עצמו כו'. הנה כמו\"כ מגודל עוצם ההשפע' כי רבה היא בבחי' התגלות העצמיי' לא יתפס מקום כלל הנמשכים בהשתלשלו' זה מזה שיהי' הפרש ביניהם בין הקטן והגדול שבהם ולכן כאשר יתגלה טובו הגדול ממילא ישוב חרון אפו מעירו, פי' חרון אפו הם מלאכי' המקטרגי' המצ[ו]מצמי' מאד מאלקי' חיים העומדי' על פרטי פרטי' להיות תופסי' מקום ולא יוכלו לסובלם כו', וכאשר מקור כל המקורי' מתגלה ממילא יבטלו כל הצמצומי' כו', ולא שצריך להכניעם ולה[ש]פילם באיזה מלחמה ונצחון אלא מאליהם מתבטלי' ממציאות' רק מצד ההתגלות לבד שנתגלה ההשפעה [ה]ראשונה הרבה מאד הנק' יסוד אריך אנפין וטובו הגדול וד\"ל.\n<b>ויובן</b> זה ע\"פ משל השפעת הרב לתלמיד[ים] הרבה ויש בהם המע[ו]לה ש[הוא מ]שפיע לקטני' הימנו והקטן לעוד קטן ממנו עד לאחר כמה השתלשלות המקבלים זה מזה תשתנה השגת הרב להיות מצומצמת מאד מאד בשכל תינוק קטן שישיגוה הוא לפי צמצום שכלו, אשר בקל יוכל לסותרה מיד לפי שאינו יודע הרחבת השכל ונימוקו כו', ולכן לא יוכל לסבול היפך צמצום השגתו כו'. והיותר גדול ממנו לא יתבטל מדבר קטן כמוהו אבל מדבר היותר גדול ג\"כ תסתיר ותחשיך השגתו כו', עד שהיותר גדול מכולם ג\"כ יסתיר ויחשך השגתו הרחבה ע\"י איזה סתירה וקושיא המחשיך לפי ערכו כו'. והסיבה לזה מפני שכולם שכלם מצומצם מאד בהשתלשלות מן השפעת הרב ולכן יוכלו הקושיות לבלבלם בקל כו', אבל כששומעי' כולם מחדש ההשגה מפי הרב כמו שהיא אצל הרב בנימוקה וטעמה הרחבה<sup data-n=\"2349\">49</sup> מיד כולם מתבטלים מכלי צמצומי השגתם ובכל א' לפי ערכו לא יבלבלוהו שום קושי', מפני שאז בשעת שמיעה אין במוחם אלא כפי השגת הרב כו', וגם ההפרש שבין הגדול לקטן לא יוכר אז בשעת התגלות השפעת שכל והשגת הרב במוחם כו'. נמצא שלביטול שלהם מצמצומם לא גרם רק התגלות ההשגה מפי הרב כו', כי כל עיקר התהוות צמצומי השגתם לא הי' רק מצד הסתלקות השגת הרב מהם וכ\"א מבין בפ\"ע כו'. וע\"פ משל זה ממש יובן למשכיל למעלה שא\"צ לביטול<sup data-n=\"2350\">50</sup> הקליפות משלחת מלאכי רעים הנק' חרון אפו כו' שום מלחמה ונצחון להכניעם ולבטלם כו' רק בהתגלות טובו מקור כל<sup data-n=\"2351\">51</sup> מקור",[["2349","49","<b>בנימוקה וטעמה הרחבה</b>: אה: בטעמו ונימוקו בהרחבה."],["2350","50","<b>לביטול</b>: אהח: לשום מלחמה לביטול. וראה בסמוך בפנים."],["2351","51","<b>מקור כל</b>: א: הגדול מקור כל. ה: הגדול."]]],[2300540203,"החיים העליונים אז ממילא יתבטלו מצמצומם. וזהו ישוב חרון אפו שישובו למקור חוצבם והי' כלא הי' וכמ\"ש בפרוח רשעים<sup data-n=\"2352\">52</sup> [כמו עשב] כו' ואתה מרום<sup data-n=\"2353\">53</sup> ה' הנה<sup data-n=\"2354\">54</sup> יאבדו ויתפרדו<sup data-n=\"2355\">55</sup> מיד כו', וכמ\"ש כהמס דונג<sup data-n=\"2356\">56</sup> מפני אש כן יאבדו רשעים מפני אלקים<sup data-n=\"2357\">57</sup> פי' כמו שהדונג כאשר נמס מפני האש אינו אלא כאשר מתגלה האש סמוך לדונג ממילא ומאליו ימס ויפול ולא עשה בו האש שום פעולה והמשכה שימס כו' כן יאבדו רשעי' מאליהם רק בהתגלות אלקות עליהם וד\"ל. וזהו ועברתי באמ\"צ אני ולא מלאך<sup data-n=\"2358\">58</sup> אני ולא שרף וכו' להיות כי קליפת מצרים הוא <span data-k=\"pg\">158</span> ּ בחי' חמור דקליפה<sup data-n=\"2359\">59</sup> [כמ\"ש] בשר חמורי' בשרם<sup data-n=\"2360\">60</sup> והוא תאות הניאוף מעשה בהמה, וכתיב ויהרוג ה' כל בכור<sup data-n=\"2361\">61</sup> כו' ואיך שייך לומר בהוי' שהוא [בחי'] רחמים מקור כל החיים כו' שיהרוג כו'. אך הענין דכתיב ועברתי שבהעברה והתגלות עצמות אור א\"ס ב\"ה שהוא טובו הגדול כנ\"ל<sup data-n=\"2362\">62</sup> אז ממילא נהרגו ונתבטלו כנ\"ל, ודוקא אני ולא מלאך<sup data-n=\"2363\">*63</sup> שאיזה מלאך שיהי' אפי' מהמלאכי' [עליונים] דעולם הבריאה או מהארת כלים דאצי' מאחר שנמשך בהשתלשלו' לא היתה הקליפה מתבטלת בהתגלותו לבד כמשל הנ\"ל שגם לערך הגדול יש קושי' וקליפה המחשיכו כו'. א\"כ גם תאוות הניאוף דמצרים אף שמאד מגושם הוא לגבי השגת מיכאל וכדומה עכ\"ז יחשיכנו קצת לפ\"ע ההשתלשלו' [שלו] כו', אבל כשמתגלה מקור כל המקורי' עילת העילות<sup data-n=\"2364\">63</sup> ית' דקמי' כחשיכה כאורה<sup data-n=\"2365\">64</sup> ממש שוין והוא הבדיל בין החשך והאור דהיינו בין קדושה לקליפה כו' ובהתגלותו לבד מתבטלת הקליפה לגמרי כו', כמו שכל הקרוב קמי' בקדושה עילאה מתבטל לגבי עצמותו ית'. וזהו דכתי' ויאמר ה' אל הנחש ואל בלעם<sup data-n=\"2366\">65</sup> כמו דכתי' ויאמר ה' אל משה<sup data-n=\"2367\">66</sup> כו' משום דקמי' כחשיכה כאורה [ממש] אך שהבדיל והרחיק ביניהם החשך כו' וד\"ל.\n[ג] <b>והנה</b> כתיב תחת אשר לא עבדת את ה' אלקיך בשמחה ובטוב לבב מרוב כל, שהעבודה במעשה המצות בשמחה וטוב לבב הוא טוב יותר מרוב כל וטובו הגדול המקור לחיי העוה\"ב, דהנה כתי' ועשיתם את כל מצותי<sup data-n=\"2368\">67</sup> והייתם קדושים לאלקיכם אני ה' אשר הוצאתי אתכם<sup data-n=\"2369\">68</sup> כו' ומהו הסמיכות לזה מיצ\"מ. אך הנה ידוע ענין פי'<sup data-n=\"2370\">69</sup> קדוש שהוא לשון מובדל<sup data-n=\"2371\">70</sup> והוא בחי' המשפיע שמובדל מערך המקבל בכל עולם לפי ערכו ומדריגתו כמו בשכינה תתאה מל'<sup data-n=\"2372\">71</sup> דאצי' ראש לשועלים<sup data-n=\"2373\">72</sup> דבי\"ע, ונק' מקור כל המקבלי', המשפיע למל' דאצי' נק' קדוש [ו]בלשון הגמ' הקב\"ה ובלשון הזהר קודב\"ה והוא",[["2352","52","<b>בפרוח רשעים</b>: תהלים צב, ח."],["2353","53","<b>ואתה מרום</b>: שם צב, ט."],["2354","54","<b>ה' הנה</b>: אה: ליתא. ט: לעולם ה' הנה."],["2355","55","<b>הנה יאבדו ויתפרדו</b>: תהלים שם, י [בדילוג. ושם: יתפרדו — ראה מאמרי אדה\"א במדבר ח\"ב ע' תרי. קונטרסים ע' שמב]."],["2356","56","<b>כהמס דונג</b>: תהלים סח, ג [בהוספת תיבת כן. ה: ליתא]."],["2357","57","<b>רשעים מפני אלקים</b>: אה: ליתא."],["2358","58","<b>ועברתי באמ\"צ אני ולא מלאך</b>: בא יב, יב. ספרי תבוא כו, ח. זהר (מהנ\"ע) וירא קיז, א. הגש\"פ."],["2359","59","<b>מצרים. . חמור דקליפה</b>: ראה מאו\"א מערכת חמור ספ\"ח. ד\"ה אסרי תקס\"ד נדפס ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680164\" data-slug=\"torat-chaim\" data-id=\"2300680164\">תו\"ח ויחי רלח, א</a>."],["2360","60","<b>בשר חמורי' בשרם</b>: יחזקאל כג, כ."],["2361","61","<b>ויהרוג ה' כל בכור</b>: בא יג, טו."],["2362","62","<b>כנ\"ל</b>: אה: כו'."],["2363","*63","<b>אני ולא מלאך</b>: ראה גם לקמן פ' בא קכב, ב. פקודי תמט, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670463\" data-slug=\"torat-chaim\" data-id=\"2300670463\">תו\"ח בראשית כז, ב</a> הערה 13."],["2364","63","<b>עילת העילות</b>: ת\"ז בהקדמה (יז, א)."],["2365","64","<b>כחשיכה כאורה</b>: תהלים קלט, יב. נסמן לקמן סד, א."],["2366","65","<b>ויאמר. . הנחש ואל בלעם</b>: נסמן לעיל פ' שמות כ, ב."],["2367","66","<b>ויאמר ה' אל משה</b>: שמות ד, ד."],["2368","67","<b>ועשיתם את כל מצותי</b>: שלח טו, מ."],["2369","68","<b>אני ה' אשר הוצאתי אתכם</b>: שלח שם, מא [ושם: ה\"א]."],["2370","69","<b>ענין פי'</b>: אה: פי'. ט: ענין ופי'."],["2371","70","<b>קדוש שהוא לשון מובדל</b>: ראה גם לעיל נא, ד. וש\"נ."],["2372","71","<b>בשכינה תתאה מל'</b>: ראה פרדס (שער עה\"כ) שכ\"ג, מערכת שכינה. מאמרי אדה\"א נ\"ך ע' רכו ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381162\" data-slug=\"likkutei-torah\" data-id=\"4001381162\">לקו\"ת שה\"ש ח, ב</a> ואילך."],["2373","72","<b>מל'. . ראש לשועלים</b>: ראה ז\"ח (מדהנ\"ע) שה\"ש עא, א. ע\"ח (שער סדר אצי') ש\"ג, פ\"א. (שער סדר אבי\"ע) שמ\"ז, פ\"ד. פ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' קעט."]]],[2300540236,"ז\"א<sup data-n=\"2374\">73</sup> דאצי' כידוע ונק' מלכא קדישא<sup data-n=\"2375\">74</sup>, וכן באו\"א נק' אימא שכינה עילאה<sup data-n=\"2376\">75</sup> ואבא שהוא המשפיע שהוא מובדל בערך<sup data-n=\"2377\">76</sup> נק' ג\"כ קדש עילאה<sup data-n=\"2378\">77</sup> בזהר ונק' ג\"כ מלכא עילאה<sup data-n=\"2379\">78</sup> וכו', וכן עד רום המעלות<sup data-n=\"2380\">79</sup> בבחי'<sup data-n=\"2381\">80</sup> תחתונה שבמאציל נק' קדוש לגבי שרש כל הנאצלים הנק' טובו הגדול בחי' יסוד דא\"א וכו', עד שמ[ל]' דא\"ס הנק' מאציל והוא אור א\"ס נק' שכינה לגבי המשפיע שהוא מהותו ועצמותו ית' והוא נק' מלכא וקדוש ומובדל בערך מאור א\"ס<sup data-n=\"2382\">81</sup> וד\"ל.\n<b>והנה</b> ידוע שהמצות נק' אברין דמלכא<sup data-n=\"2383\">82</sup> והכוונה על מלכא עילאה מכולם והוא מהותו ועצמותו ית', כי הנה מבואר במ\"א פי' אברי' דמלכא<sup data-n=\"2384\">83</sup> בז\"א דאצי' דהיינו שחוטי הציצי' ופ' קדש הגשמיי' מדצח\"מ<sup data-n=\"2385\">84</sup> הרי שרש התהוות[ם ו]מהותם הגשמי מאותיות מדותיו הנק' כלים דז\"א דאצי' והם נק' אברים דמלכא, וכמו שאדם התחתון מניח תפילין הגשמיי' על מצחו והם בליטה לבר כו' אז נמשך עליו איך שמהות הקלף הוא בשרש התהוותו שנק' שם אבר דמלכא כו'. וכן הקב\"ה שהוא אדם דאצי' ג\"כ מניח על מצחו אותו הקלף והתפילין<sup data-n=\"2386\">85</sup> כמו שהם בבחי' אותיות מאיברי' דמלכא עילאה מכולם שהוא מהותו ית', שהרי מצות תפילין דמארי עלמא<sup data-n=\"2387\">86</sup> שמניח על מצחו הוא בפקודת הוי' מלכא עילאה מכל הנאצלין שהוא מהותו ועצמותו ית', כדי שיהי' המשכת מוחין לז\"א דאצי' ע\"י מצות תפילין שיניח כו', <span data-k=\"pg\">עט</span> ּ וא\"כ<sup data-n=\"2388\">87</sup> נק' מצות תפילין שמניח ז\"א אבר דמלכא עילאה מהותו ועצמותו ית'. וכמו שבפי' אברי' דז\"א במעשה מצות [ד]אדם התחתון יש [בו] ב' פי' א' אבר לשון המשכה שנמשך במוח האדם איכות אופן פ' קדש כשהוא בבחי' אצי' שהוא מוחין והשגות כו'. ופי' הב' שהוא ממש אבר דז\"א וחלק ממנו, דהיינו שרש התהוות קלף וכתיבת האותיות כמו שהוא בכלים דאצי' נק' אבר ממנו ממש כמבואר שם. וכמו\"כ יובן באברים דמלכא עילאה מכולם שהוא מהותו ית' שהתפילין שמניח הקב\"ה המה נמשכים בשרש ממהותו ית' ממש והמה במקורם בבחי' אבר וחלק ממנו אף שלא יתכן לו[מר] שם חלק כו', אך שהם נמשכים בבחי' אצי' להיות מוחין [לז\"א] בחי' בליטה כו' ממשל<sup data-n=\"2389\">88</sup> דוגמת תפילין הגשמיי' על האדם הגשמי וד\"ל. נמצא שהמצות הם במהותו ועצמותו ית' ממש ולכן כתי' פקודי הוי'<sup data-n=\"2390\">89</sup> פי' מצות הנמשכים ע\"י הוי' ז\"א דאצי'. וזהו ועשיתם [את כל] מצותי מה שאני בעצמי ובמהותי אני<sup data-n=\"2391\">90</sup> ממשיך מצות על הוי' אדם דאצי' הם משמחי לב דז\"א יותר מרוב כל דהיינו יסוד דא\"א שרש כל הנאצלי' שאינו אלא מבחי' תחתונה שבמאציל שהוא אור וזיו לבד מן עצמותו ית', אבל",[["2374","73","<b>קודב\"ה והוא ז\"א</b>: ראה סידור שער התפילין ז, ג. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670350\" data-slug=\"torat-chaim\" data-id=\"2300670350\">תו\"ח נח סט, א</a> הערה 1."],["2375","74","<b>ז\"א. . מלכא קדישא</b>: ראה זהר בשלח נה, א ובמק\"מ שם. אמור ק, ב וביאוה\"ז שם פא, ג. אוה\"ת כאן."],["2376","75","<b>אימא שכינה עילאה</b>: ראה ת\"ז תל\"ח ובכסא מלך אות ע. תיקונים לז\"ח ק, סע\"ד. פרדס (שער עה\"כ) שכ\"ג, מערכת שכינה."],["2377","76","<b>בערך</b>: אה: מערך המקבל."],["2378","77","<b>ואבא. . קדש עילאה</b>: ראה גם לקמן נח, ב. וש\"נ."],["2379","78","<b>ואבא. . מלכא עילאה</b>: ראה זהר בראשית כב, א."],["2380","79","<b>עד רום המעלות</b>: ראה גם מאמרי אדה\"ז תקס\"ד ע' רלה."],["2381","80","<b>בבחי'</b>: אה: הבחי'."],["2382","81","<b>בערך מאור א\"ס</b>: אה: מערך אוא\"ס ב\"ה."],["2383","82","<b>שהמצות נק' אברין דמלכא</b>: נסמן לעיל פ' שמות נב, א הערה 123."],["2384","83","<b>פי' אברי' דמלכא</b>: ראה גם מאמרי אדה\"ז על ענינים ע' רל."],["2385","84","<b>מדצח\"מ</b>: ט: מדצ\"ח."],["2386","85","<b>הקב\"ה. . מניח. . והתפילין</b>: ברכות ו, א. ראה גם לקמן נו, ד. וש\"נ."],["2387","86","<b>תפילין דמארי עלמא</b>: ברכות שם."],["2388","87","<b>וא\"כ</b>: אה: וע\"כ."],["2389","88","<b>כו' ממשל</b>: אה: מלבר ממש. ט: מלבר כו' ממשל."],["2390","89","<b>פקודי הוי'</b>: תהלים יט, ט."],["2391","90","<b>אני</b>: אה: ליתא."]]],[2300540267,"המצוה עצמה היא בחי' אבר וחלק מן מהותו ממש וד\"ל, ולכן [כתיב] והייתם קדושים לאלקיכם פי' קדושים מובדל[ים] בערך דוגמת אלקיכם כו' וד\"ל.\n<b>ומעתה</b> יובן ענין השמחה וטוב לבב מעשיית המצות הוא יותר טוב מרוב כל להיות כי המצוה עצמה [הרי] היא חלק ואבר מעצמותו ית' וא\"כ בעשות הנפש את המצוה הרי מקושרת היא בעצמותו ית' מאליו וממילא תשמח הנפש בהמצוה עצמה, ולא שתהא הנפש בבחי' איזה העלאה להתקשר באור א\"ס כמו מדריגת אל דמי לך שאף שהוא התפעלות העצמות כנ\"ל, עכ\"ז עדיין לא נתקשר קישור אמיתי באור א\"ס ב\"ה אלא שנתקרב מאד עד שניזוז ממקומו כנ\"ל, וגם הקירוב הוא רק באור א\"ס ב\"ה מקור כל הנאצלים שהוא רם כו'<sup data-n=\"2392\">92</sup> כנ\"ל<sup data-n=\"2393\">91</sup>. אבל המצוה עצמה שהיא אבר דמלכא ממש כשהוא עושה אותה הרי מקושר ועומד הוא במהותו ועצמותו ית', ולכן שמחת הנפש במעשה המצוה אינה בכלל עבודה והעלאת מ\"ן כלל אלא מאליו הוא כו' כמשל המתענג ממאכל ערב כשכבר טעמו לחכו שאין בזה איזה צמאון [ו]כלות הנפש כו' מאחר שכבר הוא מתעדן בו כו', אבל כשאינו אוכלו ועדיין מונח לפניו אז תהי' תשוקה בנפש והתפעלות גדולה כו'. וזהו פקודי הוי' משמחי לב שהוא עריבו' הנפש כאשר השיגה תשוקתה כו', ולכן אחר התפלה יופסק ההתפעלו' העצמיות כנ\"ל מפני שירצה בעשיית המצוה עצמה שהיא שמחה וטוב לבב כנ\"ל ואין זה ירידה אלא עליי' האמיתי' של תשוקת אל דמי כו' וד\"ל.\n[ד] <b>אך</b> ענין תחת אשר לא עבדת בשמחה משמע שיש עבודה במעשה המצוה אלא שהעבודה צ\"ל בשמחה וטוב לבב כנ\"ל, ולהבין ג\"כ ענין [מארז\"ל] עריבים עלי ד\"ס יותר מיינה של תורה צריך להבין תחלה פי' יחוד קבה\"ו<sup data-n=\"2394\">93</sup> שבכל מעשה המצו[ת] כי ידוע שקדוש הוא לשון מובדל ומופלא מן המקבל הנק' שכינה בכל עולם לפי ערכו כנ\"ל, והנה יחוד קבה\"ו פי' לשון השפעה מן המשפיע למקבל והפרש גדול הוא מן<sup data-n=\"2395\">94</sup> עצמי[ו]ת המשפיע להשפעתו מבחי' חיצוני' שבו למקבל הימנו כידוע. ועתה יובן שמעשה המצוה עצמה הרי השמחה וטוב לבב באה מאליו מצד שכבר מקושרת הנפש בעצמותו ית' הרי הוא למעלה ממדריג' השפעה לשכינה עילאה מל' דא\"ס וכמ\"ש והייתם קדושים דוקא, אבל בברכת המצוה קודם שיעשנה באמרו בא\"ה<sup data-n=\"2396\">95</sup> אשר קדשנו כו' <span data-k=\"pg\">160</span> ּ הוא היחוד וההשפעה של המצוה שהוא אבר דמלכא שיהי' נמשך אור המצוה בשכי[נה] שהוא אור",[["2392","92","<b>רם כו'</b>: ט: רוב כל."],["2393","91","<b>וגם. . כנ\"ל</b>: אה: ליתא. וכנראה נשמט מפני תיבות הדומות: כנ\"ל. . כנ\"ל."],["2394","93","<b>יחוד קבה\"ו</b>: ראה גם לעיל נא, ג."],["2395","94","<b>מן</b>: אה: בין."],["2396","95","<b>בא\"ה</b>: אה: ברוך אתה ה'."]]],[2300540296,"א\"ס ב\"ה דהיינו אשר קדשנו במצותיו, פי' שיומשך מקדוש' המצוה עצמה הנק' מצותיו ואיברי' דמלכא עילאה על כל עילאי'<sup data-n=\"2397\">96</sup> כנ\"ל על כללות נשמות ישראל שאינן אלא בחי' מקבל מעצמותו ית' בשעת הברכה, שצ\"ל בבחי' עבודה והעלאת מ\"ן בשעת הברכה כשאומרים ברוך אתה מהותך ועצמותך למלך העולם שהוא אור א\"ס ב\"ה הנק' מל' דא\"ס כו'. נמצא כשהברכה של המצוה נאמרת בהתלהבות והתפעלות גדולה הוא נק' עבודה שיעבוד בהעלאת מ\"ן באמרו ברוך אתה מלך כו' פי' שיומשך מקדש העליון על כל העליוני' לשכינתי' כנ\"ל וכן וקדשנו ג\"כ כו', אבל עשיית המצוה עצמה כשמניח התפילין אז הוא למעלה ממדריג' היחוד ואין זו עבודה כלל רק שמחה וטוב לבב (וזהו שכל עיקר השגות רוה\"ק של האריז\"ל לא הי' רק ע\"י שמחת המצוה<sup data-n=\"2398\">97</sup> וד\"ל).\n<b>וזהו</b> [מארז\"ל] ערבים עלי ד\"ס המה ברכות כל המצות שיש בהם יחוד קבה\"ו ולכן נק' סופרי' ספר וסיפור<sup data-n=\"2399\">98</sup> משפיע ומקבל יותר מיינה של תורה, פי' יינה של תורה הם מעשה המצות נק' יין המשמח הלב בעשייתו המצוה והתורה, ונכנס יין יצא סוד<sup data-n=\"2400\">99</sup> כמו שיצא סוד השמחה והתענוג ע\"י היין כו' כן ע\"י מעשה המצוה עצמה כשתשמח הנפש ותערב בה כו' שמחה זו הוא יציאת הסוד קדש העליון עילת העילות [ית'] אשר מלובש בהמצוה שהיא אבר וחלק מעצמותו ית', ולכן המצות נק' יינה של תורה שהוא המוציא הסוד לגילוי וד\"ל. ומ\"מ ערבים עלי יותר מהם הדברי סופרים המה הברכות המשפיעי' לידי גילוי גמור אור המצוה בכל עולם לפי ערכו בעולם האצי' נעשה יחוד קובה\"ו כו'<sup data-n=\"2401\">100</sup> דאצי' להיות התגלות קדש העליון בהשגת בעלי גבול ע\"י הברכה ברוך אתה כו' וד\"ל. ובשרש האצי'<sup data-n=\"2402\">101</sup> נעשה [ה]יחוד באו\"א וכנ\"ל<sup data-n=\"2403\">102</sup>, וכן עד רום המעלות במהותו ועצמותו ית' למל' דא\"ס הנק' אור א\"ס ב\"ה, ולהיות כי ע\"י הברכה הוא בחי' השפעת הטוב הגנוז לתחתוני' לכן אומר הקב\"ה שהוא מהותו ית' ערבים עלי, אע\"פ שהוא שפלות וירידה גדולה מ\"מ ערבי' ומתוקי' עלי שיש תענוג גדול בגילוי ההשפעה למקבלי' מטבע הטוב להטיב<sup data-n=\"2404\">103</sup> כו'. וזהו ענין ישקני מנשיקות פיהו שהוא המשכת הבל העליון מנשיקת פי עצמותו ית' להבל התחתון המקבל שהוא אור א\"ס ב\"ה, וזהו דודי[ך]<sup data-n=\"2405\">104</sup> אתדבקות רוחא ברוחא<sup data-n=\"2406\">105</sup> עירוב הבלי' של המשפיע והמקבל זה בזה כו', והוא ד\"ס הערבי' וטובי' מיין מיינה של תורה וד\"ל. וזהו פי פערתי ואשאפה<sup data-n=\"2407\">106</sup> כי למצותיך יאבתי הוא השמחה וטוב לבב מן",[["2397","96","<b>עילאה על כל עילאי'</b>: ת\"ז בהקדמה (יז, א)."],["2398","97","<b>השגות. . האריז\"ל. . שמחת המצוה</b>: ראה ס' חרדים בהקדמה (תנאי המצות, התנאי הרביעי). לקמן פ' בשלח קמא, א [בכתבי האריז\"ל]. קמט, א [בע\"ח]. קנז, א. קסט, ג [בשם הרח\"ו]. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שמח ובהנסמן במראי מקומות לשם. מאמרי אדה\"א נ\"ך ע' כז. וש\"נ. דרושי חתונה ח\"ב ע' תנז."],["2399","98","<b>ספר וסיפור</b>: באוה\"ת כאן (ריש ע' נא): סופר וספר."],["2400","99","<b>ונכנס יין יצא סוד</b>: עירובין סה, סע\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680053\" data-slug=\"torat-chaim\" data-id=\"2300680053\">תו\"ח ויחי רלו, ב</a>."],["2401","100","<b>כו'</b>: אה: במל'."],["2402","101","<b>האצי'</b>: אהט: הנאצלי'."],["2403","102","<b>וכנ\"ל</b>: אה: ליתא."],["2404","103","<b>מטבע הטוב להטיב</b>: נסמן לעיל לד, ג."],["2405","104","<b>ישקני. . דודי[ך]</b>: שה\"ש א, ב."],["2406","105","<b>אתדבקות רוחא ברוחא</b>: ראה זהר משפטים קכד, ב."],["2407","106","<b>פי פערתי ואשאפה</b>: תהלים קיט, קלא."]]],[2300540324,"מצותיך כנ\"ל ופי פערתי לקבל הבל העליון באמרו הברכה וד\"ל, וכמשל ההבל שבתוך הגוף שלא יחי' ויתקיים בלי שישאף הבל האויר שבחלל העולם וכמשנ\"ת בעזר\"ה<sup data-n=\"2408\">107</sup>.",[["2408","107","<b>וכמשנ\"ת בעזר\"ה</b>: אה: וכנ\"ל וד\"ל. ט: וכמשנת\"ל וד\"ל."]]],[2300540054,"<b>ליל אחרון של פסח בעזר\"ה</b>\n<b>להבין</b> שרש המצות<sup data-n=\"2409\">1</sup>, הנה בלק\"א<sup data-n=\"2410\">2</sup> מבואר בענין יחוד הנפש שהיא מן מדת מלכותו ית' עם הקב\"ה שהוא מקור התו' והמצות והוא יחוד סוכ\"ע עם ממכ\"ע ע\"ש. ולהבין זאת דהלא הנפש אלקית היא רוחניות מאד והמצוה שבחוטי ציצית שמצמר ופשתים הם גשמיי' האיך ביכולת' להעלות הנפש ולייחדה במהותו ועצמותו ית' שהוא מקור המצוה. צריך להקדים לזה ענין אחר המבואר בלק\"ת להאריז\"ל<sup data-n=\"2411\">3</sup> במוצא פי ה' שבמאכל <span data-k=\"pg\">פ</span> ּ שיחי' את נפש האדם, אע\"פ שגם נפש הטבעי' של האדם יש בה גם מוצא<sup data-n=\"2412\">4</sup> פי ה' מי' מאמרות והיינו מאמר נעשה אדם<sup data-n=\"2413\">5</sup> והמאכל נמשך ממאמר יותר נמוך במדריגה והוא מאמר תדשא הארץ<sup data-n=\"2414\">6</sup> כו' והאיך ביכולתו להמשיך חיות לנפש האדם. אך הענין הוא דהנה בהמאכל יש טעם ומתיקות שיערב לנפש ואע\"פ שהוא בעצם בחי' דומם וצומח לבד עכ\"ז יורגש בו הטעם והמתיקות שהוא רוחני, ובזה יתרון מעלתו על מהות הנפש אדם שהרי אין בנפש שום טעם ומתיקות כלל. ואף שרוחני' הטעם הוא בבחי' גשמי' לגבי ערך רוחני' הנפש, עכ\"ז מהות הטעם ומתיקות כמו שהוא צ\"ל בחי ומדבר לפי ערכם הרי אין בנפש, שאע\"פ שהנפש תתעדן ותתענג מהשכלה הרי יש בהשכלה מתיקות, מ\"מ אין מהות השכל בבחי' טעם ומתיקות כלל רק שיתענג בו שומעו כו'. משא\"כ בתפוח יש בעצמו ומהותו הטעם והמתיקות קודם שיטעמנו אדם, וכן התענוג לראות הזהב הרי יש בזהב הדומם ההוד והתפארת שנפל מת\"ת דאצי', אך על הזהב הוא שורה ולא בעצמותו כו'. אבל הנפש שתתענג בהשכל אין בה כלל מהות הטעם והמתיקות רק כח התענוג לבד להתענג מאיזה דבר שיהי' בו טעם כו'. והסיבה לזה מפני שהנפש בהמשכתה ממקור חוצבה מאין ליש לא נמשכה בגילוי היש רק מה שנראה בה עתה והוא המדות לבד חסדי' וגבורות והתפארו' והוא מהות הנפש שתאהב או תשנא כו', ואע\"פ שיש בה גם השכל והטעם שתוליד האהבה וכן התענוג כו' הרי המה בהעלם ולא נגלה בה רק המדות לבד, להיות כי עיקר השתלשלו' שלה ממאמר נעשה אדם כו',",[["2409","1","<b>להבין שרש המצות</b>: מאמר זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז. ראה עוד ע\"ד המאמר וזמן אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["2410","2","<b>בלק\"א</b>: ב: ניתוסף: (פ ). ד: ניתוסף: ( ). פמ\"א."],["2411","3","<b>בלק\"ת להאריז\"ל</b>: ראה שם עקב ח, א. ג. כש\"ט (קה\"ת) סקצ\"ד. מאמרי אדה\"א בראשית ע' קד־ דברים ח\"ב ע' תקעה־ הנחות תקע\"ז ע' קכא ובהנסמן בהנ\"ל. שה\"א טז, ב ובהערה 10. פלח הרמון בשלח ע' קצב ואילך. יתרו ע' רלו. לקמן פ' תשא שפד, ב."],["2412","4","<b>גם מוצא</b>: ג: ממוצא."],["2413","5","<b>נעשה אדם</b>: נסמן לקמן בהערה 8."],["2414","6","<b>תדשא הארץ</b>: בראשית א, יא."]]],[2300540092,"והמאמר ההוא שבדבר ה' ורוח פיו ית' הוא מדת מלכותו ית' שקיבל מבעל המאמר שהוא בחי' דכר וסוכ\"ע<sup data-n=\"2415\">7</sup> כמ\"ש ויאמר אלקים נעשה אדם<sup data-n=\"2416\">8</sup> וכנז' בזהר דכל נשמתין ומלאכי' הוא מזיווג זו\"נ<sup data-n=\"2417\">9</sup> כו'. והרי ידוע שהדיבור שהיא מדת מל'<sup data-n=\"2418\">10</sup> לית לה מגרמה כלום<sup data-n=\"2419\">11</sup> אלא מה שמקבלת מהמשפיע והיא כלילא<sup data-n=\"2420\">12</sup> מכל דרגין, דהיינו שבהדיבור מתגלה כל העצמיות אם חסדי' או גבורות מכל<sup data-n=\"2421\">13</sup> פרטי פרטיהם מקטנם ועד גדלם כו', וכן מאמר נעשה אדם נתגלה בדיבור מסוכ\"ע אבל לא נתגלה רק מהות המדות לבד. ואע\"פ שבודאי יש שכל למדות אבל הוא בהעלם ולא נגלה, כמשל דבור האדם שמגלה מצפוני לבו ויכול לגלות אהבה פשוטה בלי טעם ושכל כלל אף שבודאי יש לו טעם ושכל לאהבה זו והוא המוליד האהבה בלבו כידוע אבל לא נגלה השכל בדבור, וכשירצה יגלה בדבור שכל וטעם לבד בלא מדה כלל אף שבודאי אותו השכל הנגלה בדבור הוא טעם לאיזה מדה והרי המדה כלולה בו אבל לא נגלית המדה והיא בהעלם ובחי' מעבר לבד בדבור ועיקר הגילוי אינה אלא השכל והטעם שבדבור כו'. ובגילוי האהבה בדבור הוא להיפך שהשכל להמדה הנגלית הוא בבחי' מעבר לבד כו' והוא כמשל הלבוש ממש שמכסה האדם לבל יראה גופו, כמו\"כ השכל מלובש ומכוסה בהמדה הנגלית דהיינו שהלבוש שהוא המדה נראה ונגלה והשכל נעלם בו כו', וכן בגילוי השכל והטעם הוא בהיפך שהמדה שבהטעם הנגלה מוסתר ומכוסה בלבוש הטעם כו'. וכ\"ז תלוי בהשפעת המשפיע בגילוי הדיבור, אם ירצה להשפיע מדה יהי' עיקר הגילוי מדה והשכל והתענוג וכל פרטיהם יהיו נעלמי' ומלובשי' בהמדה, ואם ירצה להשפיע שכל וטעם יהי' עיקר הגילוי הטעם וכל פרטי המדות [יהיו] כלולים <span data-k=\"pg\">162</span> ּ ומלובשים בו בהעלם כו'. וע\"פ משל זה יובן כמו\"כ בהשפעת נפש האדם מסוכ\"ע חי העולמי' הנק' ז\"א דאצי' לא הי' עיקר ההשפעה רק מדות לבד ולכן נק' אדם<sup data-n=\"2422\">14</sup> כו' והשכל וכל הפרטי' נעלמים בו (כמו שאדם דאצי' הוא רק ו\"ק<sup data-n=\"2423\">15</sup> אף שיש בו מוחי' הנמשכים מאו\"א כידוע, אבל עיקר הגילוי הם המדות כו'). אבל מאמר תדשא הארץ שבגילוי דבר אע\"פ שנשתלשל להיות כח מצמיח תבואה גשמי' עכ\"ז הרי אנו רואי' הנגלה בתבואה הוא הטעם והמתיקות, מפני שבמאמר תדשא הארץ שהוא כח המשכה אלקי' מאותיות מדותיו ית' כמ\"ש ויאמר אלקים וכידוע נגלה שם ג\"כ הטעם והמתיקות רוחניי' מאד והוא מהשפלת חיצוני' בינה עילאה דאצי' הנק' טעם כו', וכמשל הנ\"ל שיוכל להיות בגילוי הדיבור גילוי שכל וטעם בלי מדה ואע\"פ שבדבור מתגשם השכל והטעם עכ\"ז כמו שהטעם הוא במשפיע הרי הוא גבוה ונעלה מהמדות שבמשפיע וד\"ל. וכמו\"כ אע\"פ",[["2415","7","<b>בחי' דכר וסוכ\"ע</b>: ג: סוכ\"ע."],["2416","8","<b>ויאמר אלקים נעשה אדם</b>: בראשית א, כו."],["2417","9","<b>נשמתין ומלאכי' הוא </b>[ג: הן]<b> מזיווג זו\"ן</b>: ראה ע\"ח (שער מ\"ן ומ\"ד) של\"ט, דרוש ד. ביאורי הזהר אמור פא, ג. פינחס קטז, ד. קיח, א. מאמרי אדה\"א דברים ח\"ג ע' תשנד. וש\"נ."],["2418","10","<b>שהדיבור שהיא מדת מל'</b>: נסמן לעיל לד, א."],["2419","11","<b>מל' לית לה מגרמה כלום</b>: ראה זהר תולדות קלה, סע\"ב. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' כד. לקמן פ' בא צו, ד."],["2420","12","<b>כלילא</b>: ג: כלולה."],["2421","13","<b>מכל</b>: ב: וכל."],["2422","14","<b>ז\"א. . נק' אדם</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"ה."],["2423","15","<b>ז\"א. . ו\"ק</b>: ראה ע\"ח (שער המוחין) ש\"כ, פ\"א."]]],[2300540130,"שבמאמר תדשא שהוא נמוך במדריג' ממאמר נעשה אדם נשתלשל דומם התבואה וממאמר נעשה אדם נשתלשל נפש החי[ו]' עכ\"ז מצד [מקור] מוצא פי ה' שבמאכל יש בו טעם הרי הוא גילוי חיצוני' בינה עילאה שהוא למעלה מהשפעת מדה שהוא נפש החי וד\"ל.\n<b>אך</b> להבין ענין השפלת<sup data-n=\"2424\">16</sup> חיצוני' בינה עילאה דאצי' שהוא מקור למדות דאצי' שיהי' גילויו בדבר ה' עד שישתלשל טעם הגשמי שבדומם התבואה למה הוא כך. הנה ידוע ענין אני ראשון ואני אחרון<sup data-n=\"2425\">17</sup> כתר ומל' והוא בפסוק אני ה'<sup data-n=\"2426\">18</sup> שבסוף ק\"ש והוא ענין נעוץ תחב\"ס וסוב\"ת<sup data-n=\"2427\">19</sup>, פי' כתר הוא הרצון לבריאת העולמות והוא תחלה האמיתי שהוא המכוון בבריאה, וסוף מעשה הוא כח הפועל בנפעל להחיות רוח שפלים<sup data-n=\"2428\">20</sup> דבי\"ע, ונעוץ התחלה בסוף פי' שמאיר בסופא דכ\"ד שהוא מדת מלכותו ית' המקיף האמיתי שהוא רצונו ית'. וצריך להבין למה צריך שתהא ההארה של התחלה בסוף הלא כח הפועל האלקי ביכולתו להחיות רוח שפלים מצד עצמיות מדת התפשטות כו'. אך הענין הוא דרצה המאציל ית' שיהי' הפיכת החשך לאור ומרירו למיתקא כו', ואלו לא הי' הארת התחלה בסוף אלא הי' הכח הפועל אלקי מצד עצמו לבד מחי' כל הנבראי' והרי ההשתלשלו' רבות מאד בצירופי אותיות כידוע עד שמבין נקבי וחללי הצרופי'<sup data-n=\"2429\">21</sup> נתהווה חיות הקליפו' והחשך כידוע, א\"כ לא הי' ביכולת החשך להיות אור מאחר שנשתלשל ברבבות מדריגו' ונתרחק מאד מאור פני אלקי' חיים כידוע עד שיהא חושך גשמי ואיך יהפך לאור ויתעלה ויעלה למעלה מאופן השפלתו שנשפל מאד למטה כו'. אך מצד הארת התחלה בסוף הרי קמי' כחשיכה כאורה<sup data-n=\"2430\">22</sup> ממש מאחר שהוא למעלה מן הראש ואין הראשי' ערוך לו כמו שאין הסוף ערוך לו ושניהם רחוקי' ממנו בשוה, והוא כמו עיגול הרקיע סובב הארץ שלמעלה ולמטה סובב הוא בשוה וכמו שהוא רחוק מן מעלת הכדור כן הוא רחוק ממטה של הכדור כו' וכמ\"ש ומתחת זרועות עולם<sup data-n=\"2431\">23</sup>. ומצד הארת התחלה שהוא כתר מל' שהוא אני ראשון כמו\"כ ממש אני אחרון, לכן ביכולת החשך להתהפך לאור ולהיות נעוץ סופן בתחלתן שהוא ע\"י נעיצת תחלתן בסופן שהוא מתחת זרועות עולם, כמשל הגדול שמגביה את הקטן שמניח ומשפיל ידיו עד למטה מן התינוק שאז יכול להגביהו מהשפלתו ואם לא ישפיל ידיו למטה הימנו לא יוכל להגביהו <span data-k=\"pg\">פא</span> ּ כו', כמו\"כ מתחת זרועות עולם הארת סוכ\"ע שעי\"כ יוכל להיות יתרון אור מתוך החשך, ונמצא שהראש מצטרך לסוף והסוף מצטרך לראש, שיתרון מעלת האור",[["2424","16","<b>השפלת</b>: ג: השפעת. ראה לעיל שו\"ה מהשפלת."],["2425","17","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו. ראה גם פרדס (שער אם הא\"ס הוא הכתר) ש\"ג, פ\"א. ע\"ח (שער דרושי אבי\"ע) שמ\"ב, ספ\"א. לקו\"ת שבהערה הבאה. מאמרי אדה\"ז אתהלך לאזניא ע' רעז. שה\"א נח, ב. קא, א."],["2426","18","<b>אני ה'</b>: שלח טו, מא. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380503\" data-slug=\"likkutei-torah\" data-id=\"4001380503\">לקו\"ת שלח מז, ד</a>."],["2427","19","<b>נעוץ תחב\"ס וסוב\"ת</b>: ראה ס\"י פ\"א, מ\"ז."],["2428","20","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["2429","21","<b>נקבי וחללי הצרופי'</b>: ראה גם ביאוה\"ז וישב כא, סע\"ד ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א וישלח כו, ב</a>. מאמרי אדה\"ז תקס\"ו ע' פב. ענינים ס\"ע קפט. מארז\"ל ריש ע' רכז."],["2430","22","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["2431","23","<b>ומתחת זרועות עולם</b>: ברכה לג, כז. ראה גם בהנסמן לשע\"ת כג, א. לקמן עב, ב. פ' בא קטו, א. בשלח קסג, א. תצוה שלט, ג. פקודי תמט, ד."]]],[2300540167,"שהוא הראש מתוך הפיכת החשך הוא והיינו הארת הסוף בתחלה אבל הפיכת החושך א\"א בלי הארת התחלה והיינו שמצטרך הסוף לראש שיתעלה על ידו כו', ומאחר שמצטרכי' זה לזה ואין הראש יכול להיות בפ\"ע הרי אינו ראש כו', וכן אין הסוף יכול להיות בפ\"ע אלא נעוץ בתחלתו, והיינו מבלי שימצא ראש וסוף מפני הארת המקיף האמיתי המאיר את התחלה בסוף וסוף בתחלה מבלי שימצאו שניהם וד\"ל. וכמו\"כ ענין השפלת חיצוניות בינה עילאה דאצי' שהוא הראשית בהמשכת מוחי' לז\"א דאצי' להאיר בסופא דכל דרגין שבי' המאמרות שהוא מאמר תדשא שיהי' נמצא מהות טעם הגשם שבדומם התבואה שהוא למטה מן נפש החי, כדי שיהי' הטעם והמתיקות הגשמיי' נתעלה ע\"י אכילת האדם שיטעמנו ברוחניות נפשו שהוא הראש בי' מאמרות הגלויות והיינו סופו בתחלתו, ומה שבאמת במקור מוצא פי ה' בבחי' אצי' הטעם שבמאכל הוא הראש כנ\"ל, ומצד זה יחי' הטעם את הנפש והנפש תחי' ותקבל חיות קיומה הרי הראש צריך לסוף והיינו מבלי שימצא ראש וסוף, אבל אם לא הי' בהטעם השפלת חיצוניות בינה שהוא הראש לא הי' ביכולתו להחיות הנפש וכן לא הי' יכול להתברר הטוב שבמאכל ע\"י אכילת הנפש אלא הי' נשאר מגושם כו' וד\"ל.\n<b>ועתה</b> צריך להבין מדוע נשתלשלי'<sup data-n=\"2432\">24</sup> טעם דבינה עילאה דאצי' בדבר נמוך כ\"כ כמו הדומם דתבואה גשמי'. אך הענין שכל דבר גב[ו]ה מאד נעלה א\"א לו להתגלות כ\"א בהיותר נמוך<sup data-n=\"2433\">25</sup> במדריגה, כמו מי שמעמיק בהשכלה נפלאה מאד עד שא\"א לו להסביר בשכל והשגה כלל וכשימצא משל לההשכלה אז יוכל להשיגה בשכלו מתוך המשל, והנה המשל הוא דבר אחר לגמרי ואינו מערך השכל כלל, ועכ\"ז נתגלה העמקות של השכל במשל הגשמי מאד ובהשגה הרוחני' לא הי' יכול לבוא לידי גילוי, מפני שמאד נפלאת היא מערך ההשגה במוח ולפי שבמשל גשמי הוא שתאיר בבחי' לבוש לבד לכן יתגלה בו אבל ברוחני' ההשגה תאיר בבחי' אור ממש והרי נפלאת היא מההשגה לכן לא תוכל להתגלות שם כו'. וכן מי שאינו יכול להסביר שכלו והשגתו בדבור עכ\"ז יוכל לרמוז אותה באצבעו כמו די לחכימא ברמיזא<sup data-n=\"2434\">26</sup> שישכיל השכל מתוך רמז האצבע הגשמי מפני שהוא כמו לבוש לבד שיושפל ויתלבש בו השכל כו', אבל הדבור הוא מערך השכל דאבא יסד ברתא<sup data-n=\"2435\">27</sup> כידוע ובבחי' אור וכלי יוכל<sup data-n=\"2436\">*28</sup> לבוא לידי גילוי וד\"ל. וכן יובן זה ע\"פ משל אחר שאותיות החותם שבאבן טוב המבהיק מאד מאד שמחמת בהירות והבהקה לא יוכלו לראות חילוקי אותיות החותם אבל כשישימו האבן טוב בשעוה אז יוכרו האותיות, כי חשך השעוה יסתיר אור ההבהקה",[["2432","24","<b>נשתלשלי'</b>: בג: נשתלשל."],["2433","25","<b>שכל דבר גב[ו]ה. . בהיותר נמוך</b>: נסמן לעיל פ' שמות כא, ב."],["2434","26","<b>די לחכימא ברמיזא</b>: ראה רשב\"ם בראשית כג, טז. מדרש משלי כב, טו. זהר בראשית כו, ב. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשנב. מאמרי אדה\"א שמות ח\"א ע' סט."],["2435","27","<b>דאבא יסד ברתא</b>: נסמן לעיל פ' שמות מז, ב."],["2436","*28","<b>יוכל</b>: אוצ\"ל: לא יוכל."]]],[2300540204,"ויגלום חילוקי האותיות וכן עמקות ההשגה תגלה בחשך המשל וד\"ל. ועפי\"ז יובן למשכיל למעלה בכל דבר גבוה כמו לחם מן השמים<sup data-n=\"2437\">28</sup> שהוא מזונא שבבחי' אצי' נתגשם בדומם המן אשר דכוהו במדוכה<sup data-n=\"2438\">29</sup> כו', וכמו\"כ נז'<sup data-n=\"2439\">30</sup> באוה\"ח<sup data-n=\"2440\">31</sup> בענין פני <span data-k=\"pg\">164</span> ּ ארי' אל הימין<sup data-n=\"2441\">32</sup> שבקדושה המרכבה עילאה שמפני שהוא גבוה מכולם לא הי' ביכולתו להיות משתלשל בחיות טהורות הקרובי' בהשתלשלות אבל בחיות טמאות הרחוקו' מאד בהשתלשלות הוא שנתגלה מהותו ואף שאינו מערכו כלל, אבל דוגמתו הוא כמו נפש השור הגשמי הוא מעין ודוגמא פני שור הרוחני' מאד דמרכבה עילאה דבי\"ע כנודע ומפני שאינו גבוה כ\"כ כמו פני ארי' יכול להשתלשלו'<sup data-n=\"2442\">33</sup> בחיות טהורות כו' וד\"ל. וכמו\"כ יובן בהשפלת חיצוני' בינה עילאה דאצי' שהוא הגבה למעלה מבחי' אור חסד דאצי' כידוע, ומפני עוצם ההפלאה הוא שאינו יכול להתגלות בדבר הקרוב לו קצת כ\"א דוקא בדבר הרחוק מאד בהשתלשלו' והיינו הדומם שבתבואה הגשמי' יגלה בו הטעם והמתיקות, אבל בנפש החי שקרובה יותר בהשתלשלות הי' מאמרות לא הי' יכול להתגלה בו והוא מפני שבטעם הגשמי הוא בבחי' לבוש לבד כנ\"ל, אבל ברוחניות לא הי' מתגלה בבחי' אור ממש, והרי אין הנפש מערך בינה דאצי' כלל שתאיר בו בבחי' אור וכלי כו' אבל בבחי' לבוש כל מה שהדבר יותר נמוך יוכל יותר להתלבש בו וכמו עניני כבוד הגשמיי' נתלבשו בהם מקיפי' דאצי' וכמ\"ש במ\"א.\n<b>והנה</b> אחר כל הנ\"ל במוצא פי ה' שבמאכל שיתרונו על נפש החי הוא הטעם הנשפל בו ויתרון הנפש עליו אינו אלא בבחי' גילוי המאמרות לבד כנ\"ל. כמו\"כ בכל פרטי' הוא במצות<sup data-n=\"2443\">34</sup> הגשמיי' כמו חוטי צמר הגשמיי' הם דומם לבד נמשכי' מצירוף אותיות תדשא<sup data-n=\"2444\">35</sup> לבד, אבל באיכות אופן עשייתם דהיינו כשהם ל\"ב חוטין וכו' נשפל בהם ממש אורות דאצי' שהם ל\"ב נתי' חכמה<sup data-n=\"2445\">36</sup> הנמשכי' לנוק'<sup data-n=\"2446\">37</sup> מכנפי ציצי' דז\"א דאצי' שהם שערות דז\"א כו', וכמו טעם גשמי שבדומם התבואה שנתלבש בו טעם בינה דאצי' כנ\"ל שכל דבר הגבוה מאד דרכו להתלבש דוקא בנמוך כמו דומם וכיוצא בו, ואע\"פ שנפש האדם הוא ממאמר נעשה אדם והרי בהתגלות המאמרות היא גבוה ממצות ציצית, אבל לא נשפל בו אורות דאצי' בבחי' לבוש כמו בחוטי הציצית, והרי אין בנפש כ\"א הארה בעלמא מאותיות נעשה אדם שהוא בחי' ממכ\"ע סוף כל דרגין כידוע ובחוטי הציצית עצמן הרי יש בבחי' לבוש אורות דאצי' שהם מקור ומוחי' לחכמה שבי' מאמרות והם בבחי' סוכ\"ע למעלה מראשית וחכ' שבדבור כו'. וכן קלף של עור בהמה טהורה נמשך מאותיות מאמר תוצא",[["2437","28","<b>לחם מן השמים</b>: בשלח טז, ד."],["2438","29","<b>דכוהו במדוכה</b>: בהעלותך יא, ח."],["2439","30","<b>וכמו\"כ נז' באוה\"ח</b>: ג: וכמבואר בע\"ח."],["2440","31","<b>באוה\"ח</b>: אחרי יז, יד [ד\"ה ונראה]. ראה גם ביאוה\"ז תרומה נ, ד. מאמרי אדה\"ז תקס\"ה ח\"א ע' סד [נו\"ש]. וארא תקס\"ח [נדפס באוה\"ת וארא ע' קסד]. תקס\"ט ע' צ. מאמרי אדה\"א במדבר ח\"ב ס\"ע תעט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680095\" data-slug=\"torat-chaim\" data-id=\"2300680095\">תו\"ח וישלח קפט, א</a>."],["2441","32","<b>פני ארי' אל הימין</b>: יחזקאל א, י."],["2442","33","<b>להשתלשלו'</b>: בג: להשתלשל."],["2443","34","<b>פרטי' הוא במצות</b>: ג: פרטי המצות."],["2444","35","<b>חוטי צמר. . דומם. . אותיות תדשא</b>: ראה בסמוך בפנים ”קלף. . תוצא הארץ נפש חי'\"."],["2445","36","<b>ל\"ב חוטין. . ל\"ב נתי' חכמה</b>: ראה זח\"ג (תוספת) שא, א. מאמרי אדה\"א בראשית ע' שצד. וש\"נ."],["2446","37","<b>לנוק'</b>: ב: למל'."]]],[2300540237,"הארץ נפש חי'<sup data-n=\"2447\">38</sup> היא למטה מנפש המדבר שבאדם כו'. אבל הרי השפלת חכמה עילאה דאצי' באיכות אופן כתיבת פ' קדש שנא' בה וידבר ה' שהוא אלקות בבחי' א\"ס והוא אור חכמה דאצי' שאמר אל משה<sup data-n=\"2448\">39</sup> קדש לי כל<sup data-n=\"2449\">40</sup> חכמה כו', ואף שכתובה בקלף גשמי הרי נתלבש באותיות הכתיבה על אופן זה כ\"ז<sup data-n=\"2450\">41</sup> ממש אור חכ' דאצי' שהוא מוחי' למדות דאצי', ואברהם ע\"ה שהי' בחי' מרכבה ממש למדת החסד<sup data-n=\"2451\">42</sup> דאצי' מפני מס\"נ הגדול שהי' לו קיבל הארת חכ' דאצי' ממש בנפשו ולא הי' צריך להניח תפילין<sup data-n=\"2452\">43</sup> גשמיים כי קיבל מוחי' דאצי' למדת אהבתו שהי' מרכבה לאהבה דאצי' וכמ\"ש במ\"א, אבל דוד ע\"ה שהי' מבחי' נפש ומ' דאצי'<sup data-n=\"2453\">44</sup> ולא מן המדות עצמן דאצי'<sup data-n=\"2454\">45</sup> הי' צריך להניח תפילין בקלף גשמי כדי שיולבש בקלף אור מוחי' דאצי' ממש, מפני שנפש דוד שהי' בגדר הבריאה<sup data-n=\"2455\">46</sup> לא הי' ביכולתה לקבל אור חכ' דאצי' <span data-k=\"pg\">פב</span> ּ בבחי' אור וכלי כי אינה מערכו כלל, ובבחי' לבוש לא מתגלה אלא בדבר היותר נמוך והוא בקלף גשמי דוקא כמו התגלות הלחם מן המדות עליונות דאצי' בזרע גד<sup data-n=\"2456\">47</sup> הגשמי ודוכהו במדוכה כנ\"ל. ונמצא כמו שטעם המאכל יחיה נפש האדם מצד שרשו מבחי' טעם בינה דאצי' כמו\"כ חוטי הציצית עצמן וקלף התפילין עצמן יחי' ממש נפש אלקי' מצד אורות העצמיי' דאצי' המלובש בהם, כמו שנפש אאע\"ה הי' אור חכמה דאצי' מחיה אותה ממש בבחי' גילוי והי' יחוד ממכ\"ע עם סוכ\"ע, כמו\"כ המצוה עצמה הקב\"ה עצמו הוא מקורה בבחי' לבוש ונפש המקיימת המצוה תחי' ממנה (והוא הארת תחלתן בסופן וד\"ל). והוא יחוד סוכ\"ע עם ממכ\"ע, היינו מקור הנפש מאמר נעשה אדם כו' מתעלה באורות דאצי' ל\"ב נתי' חכמה דז\"א וכו' שהוא מקור מצות ציצית וד\"ל.\n<b>והנה</b> במוצא פי ה' שבמאכל שיתרונו על נפש האדם הוא בהעלם ומה שהוא דומם והנפש הוא חי יתרון הנפש עליו הוא בגילוי כנ\"ל, אופן הפרש זה שביניהם הוא עד רום המעלות גם בשרש שרשם דהיינו שרשם הוא מאמר נעשה אדם ומאמר תדשא, הרי מאמר נעשה אדם גבוה בבחי' גילוי אבל מצד העלם טעם בינה דאצי' המלובש באותיות תדשא הארץ כו' הרי מאמר תדשא גבוה הרבה ממאמר נעשה אדם כו'. וכן בשרש שרשם בז\"א דאצי' מאמר נעשה אדם נמשך מבחי' אדם דאצי' ומאמר תדשא נמשך מבחי' דומם שבו כו', עכ\"ז מצד העלם חיצוני' בינה שבבחי' דומם שבו כו' הוא [גבוה] מבחי' מדות עצמן דאצי' הנק' אדם שאין בהם אלא צמצום גדול מאור בינה דאצי' כידוע וד\"ל. וכן עד רום המעלות באו\"א וא\"א כו' עד הארת הקו ממהותו ועצמותו ית' הנק' אור א\"ס ומ' דא\"ס כלולה",[["2447","38","<b>תוצא הארץ נפש חי'</b>: בראשית א, כד."],["2448","39","<b>וידבר ה'. . אל משה</b>: בא יג, א."],["2449","40","<b>קדש לי כל</b>: שם יג, ב."],["2450","41","<b>כ\"ז</b>: בג: ליתא."],["2451","42","<b>ואברהם. . מרכבה. . החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["2452","43","<b>ואברהם. . תפילין</b>: נסמן לקמן סג, ג הערה 171."],["2453","44","<b>דוד. . ומ' דאצי'</b>: ראה פרדס (שער עה\"כ) שכ\"ג מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["2454","45","<b>עצמן דאצי'</b>: ג: דאצי' עצמן."],["2455","46","<b>שנפש דוד שהי' בגדר הבריאה</b>: ראה מאמרי אדה\"א נ\"ך ע' קפט."],["2456","47","<b>בזרע גד</b>: בשלח טז, לא."]]],[2300540268,"מי\"ס כידוע והם י' מאמרות מעצמותו ית', הרי מאמר נעשה אדם שהוא א\"ק גבוה ממאמר תדשא בחי' הדומם שבמאציל והיינו היתרון שבבחי' גילוי אור א\"ס ב\"ה, אבל מצד העלם בחי' העצמיי' הגנוזה בעצמותו ית' קודם שנק' מאציל שנתלבשה במאמר תדשא שבמ' דא\"ס הנק' מאציל כו' הרי הוא גבוה ממאמר נעשה אדם כו' וד\"ל. וכמו\"כ ממש יובן במצוה הגשמית כמו הקלף למטה בזה העולם גבוה בבחי' העלם מנפש האדם ותחסרהו<sup data-n=\"2457\">48</sup> כנ\"ל. כמו\"כ עד רום המעלות בשרש דשרש המצוה ושרש דשרש הנפש יהי' אופן ההפרש ביניהם ג\"כ עד\"ז, דהיינו כידוע ומבואר במ\"א בתפילין שמניח הקב\"ה<sup data-n=\"2458\">49</sup> שהוא ז\"א<sup data-n=\"2459\">50</sup> דאצי' שהם בחי' קלף גשמי בעולם אצי' וכתוב בהן ומי כעמך ישראל<sup data-n=\"2460\">51</sup> כו', הרי התפילין שלו הם צירופי אותיות בבחי' אצי' והם בחי' דומם לגבי מדות דאצי' הנק' אדם דאצי' והוא הקב\"ה כידוע, וכשמניחן מצד שיש בהם הארה מלובשת מאור חכ' דאצי' ניתוסף בו מוחין פנימי', והוספת מוחי' הגלויי' במדות אינם ערוך לגבי עצמיות אבא שרש כל עולם האצי'<sup data-n=\"2461\">52</sup> כידוע. ונמצא שהמצות תפילין שהם בבליטה גשמיי' הם מחי' אותו כו' אע\"פ שהם בבחי' דומם בגילוי אור האצי' ויתרון אדם דאצי' עליהן הרבה כו', עכ\"ז יקבל על ידן מוחי' הארת אבא כו' מה שאין ביכולת מוחי' שלו לקבלם בבחי' אור וכלי וד\"ל, והיינו ג\"כ יחוד סובב וממלא וד\"ל. וכן עד\"ז עד רום המעלות באו\"א וא\"א וכו' עד <span data-k=\"pg\">166</span> ּ אור א\"ס כו' המניח תפילין מבחי' קלף כתובי' פ' קדש כו' שבבחי' מאציל מאמר תוצא הארץ נפש חי' כו' הוא בבחי' הדומם שבמאציל עצמו הנק' מל' דא\"ס, ומניחן על מוחין שבמאציל וניתוסף לו מוחין ע\"י הנחת התפילין שהוא אבר וכלי דמלכא עילאה מהותו ועצמותו ית' שמלובש בדומם שבמאציל אור חכ' הגנוזה במהו\"ע ית' ממש וד\"ל. נמצא מובן למשכיל שהמצוה מצד עצמה<sup data-n=\"2462\">53</sup> מהותה ועצמותה הוא בחי' אבר דמלכא בכל עולם לפי ערכו, ופי' אבר וכלי הוא בחי' לבוש שמתלבש בו האור הגנוז בדבר נמוך הנק' אבר כו', והנה באבא הוא באופן אחר וכמו<sup data-n=\"2463\">54</sup> שהוא בז\"א שהרי הוא ההעלם של מצות התפילין דז\"א דהיינו שתהי' הכתיבה פ' קדש באופן זה דוקא אז יומשך לו מוחי' כו', וכן תפילין דא\"א הוא העלם דאבא דהיינו הטעמי' למה ירצה כלל באופן המשכת מוחין אלו כו', וכן עד רום המעלות עד רצונו הפשוט בתכלית הפשיטות הוא מצות תפילין במאציל עצמו כו', נמצא שבקלף הגשמי שורה רצונו הפשוט והוא למעלה מאור א\"ס ב\"ה הנק' מ[ל]' שבכתר כו' וד\"ל. וזהו רצה [הקב\"ה] לזכות את ישראל<sup data-n=\"2464\">55</sup> הרבה להם תורה ומצות, פי' שהמצות מצד עצמיות שלהם כל שיעשינה ויקיימנה האדם הלא המה מלובשי' מאורות עצמותו ית' שהוא רצונו הפשוט כו', ומה",[["2457","48","<b>ותחסרהו</b>: בג: ותחייהו."],["2458","49","<b>בתפילין שמניח הקב\"ה</b>: ברכות ו, א. ראה גם סידור שער התפילין ז, ג ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370163\" data-slug=\"torah-or\" data-id=\"3901370163\">תו\"א מקץ לה, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670236\" data-slug=\"torat-chaim\" data-id=\"2300670236\">תו\"ח לך פג, ב</a>. לעיל נד, ג. לקמן סג, ב."],["2459","50","<b>הקב\"ה שהוא ז\"א</b>: נסמן לעיל נד, ג."],["2460","51","<b>ומי כעמך ישראל</b>: דהי\"א יז, כא. ראה לקמן סג, ב. רס, א. ש\"א נ, א. הערה במאמרי אדה\"א ויקרא ח\"ב ע' תסז."],["2461","52","<b>אבא שרש כל עולם האצי'</b>: ראה ע\"ח (שער סדר אבי\"ע) שמ\"ז, פ\"ב."],["2462","53","<b>עצמה</b>: בג: ליתא."],["2463","54","<b>וכמו</b>: בג: מכמו."],["2464","55","<b>רצה [הקב\"ה] לזכות את ישראל</b>: מכות כג, ב (במשנה)."]]],[2300540297,"שציוה ה' שיקיימנה האדם רצון זה הוא ענין אחר שהוא לזכות הנפש הישראלי שיקיימנה. וזהו אשר קדשנו במצותיו שהם אברי' דמלכא וציוונו<sup data-n=\"2465\">56</sup> ג\"כ לעשותם כדי להעלות הנפש ולייחדה במהותו ועצמותו ית' והוא יחוד קובה\"ו הנעשה ע\"י קיום המצות במעשה הנפש של האדם הנמשכת מבחי' ממכ\"ע וד\"ל, אבל המצות מצד עצמותן המה הגבה למעלה מבחי' ממכ\"ע שהקב\"ה בעצמותו הוא מקורן וד\"ל. וזהו כי<sup data-n=\"2466\">57</sup> שכר מצוה מצוה<sup data-n=\"2467\">58</sup> פי' שכר קיום המצוה היא המצוה עצמה שהוא רצונו הפשוט שלמעלה מזיו השכינה, וזהו יפה שעה א'<sup data-n=\"2468\">59</sup> וד\"ל.",[["2465","56","<b>אשר קדשנו במצותיו. . וציוונו</b>: נוסח ברכת המצות. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לא וע' קפו. דרך מצותיך ע' קסח."],["2466","57","<b>כי</b>: ב: ליתא."],["2467","58","<b>שכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב."],["2468","59","<b>יפה שעה א'</b>: אבות פ\"ד, מי\"ז. ראה גם לעיל נב, א."]]],[2300540055,"voeiro5558_3\n<b>כי</b> ה' יתן חכמה<sup data-n=\"2469\">1</sup> מפיו דעת ותבונה<sup data-n=\"2470\">2</sup>, להבין שרש ענין ממכ\"ע וסוכ\"ע<sup data-n=\"2471\">3</sup>, הנה מבואר למעיין בע\"ח שיש הפרש גדול בין כלים דאצי' היורדים להיות ראש לשועלים<sup data-n=\"2472\">4</sup> בבי\"ע וכמ\"ש לכי ומעטי א\"ע<sup data-n=\"2473\">5</sup> כו' שהאורות עצמם ומהותם המלובשים בכלים משתנים להיות ראש לשועלים כו', והיינו ע\"י בקיעת המסך<sup data-n=\"2474\">*6</sup> שבין אצי' לבריאה שבוקעין ממש ויורדין כו', אבל אורות דאצי' העצמיי' שמסתלקי' למעלה מהכלים אינם בוקעי' המסך כלל ואינם מאירים אלא דרך המסך לבד כו'. וביאור זה דהנה ענין אור מקיף ידוע שהוא מה שאינו נכנס בגילוי האור בבחי' חיות ממש לפי אופן קבלת הכלי, וא\"כ אין אור המקיף מחי' כלל את הכלי, ובאמת אינו כן שהמקיף מחי' ממש את הכלי<sup data-n=\"2475\">6</sup>, ואע\"פ שאינו מערכו שיקבל השפעת המקיף מעצמו' שלו אבל [י]קבל החיות מבחי' חיצוני' דחיצוני' של המקיף. ויובן זה ע\"פ משל הזורק אבן בכחו שכח התנועה שביד נפרדת מן היד ומתלבשת באבן ומוליכתו באויר למרחוק, שכח תנועת היד המוליך האבן היא רוחני' והאבן הוא דומם ואין לו תנועה מצד עצמו, ומה שהכח מוליכו באויר הוא בבחי' מקיף על האבן מה שיוכל להתנענע מחמתו (שאינו דומה לבחי' אור וחיות הנפש <span data-k=\"pg\">פג</span> ּ באצבע הדומם להניעו, שבשר האצבע הרי גלוי בו החיות בבחי' או\"פ, והוא מערכו כו'), אבל האבן אינו מערך הכח הרוחני ועכ\"ז מוליכו ומניעו באויר הרי הכח מלבישו ומקיפו מרחוק בבחי' הסתר ולא בגילוי בתוך מהות האבן, והנה אין אנו רואים בחירה כלל בכח זה הנפרד ומלובש באבן שיטה האבן הנה והנה באופן אחר מכמו שנמשך כח תנועה זו מן היד, אם נמשך מן היד לזרוק למעלה ילך הכח למעלה ולא ילך למטה, וגם אין בחירה כלל ביד האדם לשנות הזריקה שיוזרק האבן למטה, מאחר שכבר נפרד הכח ונבדל להיות בפ\"ע באויר השמים, ואף שלא",[["2469","1","<b>כי ה' יתן חכמה</b>: מאמר זה הוא הנחת כ\"ק אדמו\"ר האמצעי ממאמר אביו כ\"ק אדה\"ז. נדפס בשינויים במאמרי אדה\"ז אתהלך לאזניא ע' עז [וראה הנרשם לעיל (נא, ג) רד\"ה ענין יחוד קוב\"ה ושכינתי']. ראה עוד ע\"ד המאמר וזמן אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["2470","2","<b>כי ה' יתן. . ותבונה</b>: משלי ב, ו."],["2471","3","<b>ממכ\"ע וסוכ\"ע</b>: זהר (רע\"מ) פינחס רכה, א."],["2472","4","<b>ראש לשועלים</b>: נסמן לעיל נד, ב."],["2473","5","<b>לכי ומעטי א\"ע</b>: חולין ס, ב. ראה גם שעה\"י קמב, א ובהערה 24."],["2474","*6","<b>בקיעת המסך</b>: ראה גם לקוטי הש\"ס להאריז\"ל חולין ס, ב. אגה\"ק ס\"כ. לקו\"ת שמ\"ע צא, ד. ביאוה\"ז בשלח מה, ד."],["2475","6","<b>שהמקיף מחי'. . הכלי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח</a>."]]],[2300540093,"ילך הכח כ\"א כפי אשר נמשך מהיד, עכ\"ז אין בחירה ביד לשנות התנועה מאחר שנפרדת ומרוחקת היא ממנה כו'. משא\"כ תנועת האצבע מכח היד שיש בחירה ביד לשנות תנועת האצבע בכתיבה מאופן לאופן. והענין הוא מפני שתנועת האצבע הנמשכת מכח היד יש להם ערך זה לזה שהאצבע חי הוא מן הכח, ואף שהוא התפשטות חיות הכח שביד לבד ולא עצמיותו, אבל הוא התפשטו' העצם ונק' בחי' מל' שבו ולכן ישתנה ההתפשטו' לפי שינוי העצם שהוא הכח שביד באופני הכתיבה וד\"ל. אבל הכח המלובש באבן מאחר שכבר נפרד ונתרחק מהכח שביד ואינו בחי' התפשטו' ראשונה של כח היד להקרא התפשטו' העצם לכן לא ישונה מפני שינוי העצם כו', ואף אם ירצה כח היד באופן אחר הכח יוליך את האבן כמו שנמשך. וא\"א לומר שההולכה והתנועה שמוליכו באויר אינו מאיר בו כח היד כלל, מפני שמובדל הוא ממנו כו', שהרי הולכת הכח למעלה ולא למטה הוא מכח היד שהמשיך כך כו', הרי הולכה זו שבאויר היא המשכת כח היד. אבל הענין הוא שהתפשטו' כח הולכה מן כח היד הוא בחי' מל' שבו בראשית יציאתו כו', ולכן יוזרק למ[על]ה ולא למטה רק כפי כח היד שהמשיכו כו', אבל כשמתרחק הלא אז הכח מוליך מעצמו וכבר נפסק הארת כח היד, אלא מרחוק בדרך הסתר ומקיף מאיר בו התפשטו' ראשונה של כח היד להוליכו למעלה דוקא כו'. ונמצא שתנועת האבן הוא בחי' התפשטו' דהתפשטות כח היד וכבר רחוק הוא מאד מכח היד ולכן לא ישונה כו', אבל כח היד בתנועת האצבע כל שעה שהאצבע מתנענע מאיר בו כח היד העצמי וה\"ז בחי' התפשטותו לבד וד\"ל. וכן הבל הדבור כל שעה מתפשט מכח הדבור העצמי לכן ישונה הדבור כפי רצון כח הדבור וד\"ל.\n[ב] <b>וע\"פ</b> משל זה יובן ההפרש של חיות או\"פ לחיות או\"מ<sup data-n=\"2476\">*7</sup>, דהנה בכח הולכת האבן באויר שנמשך מהתפשטו' ראשונה של כח היד, שהתפשטו' ראשונה מאיר בו בבחי' מקיף מרחוק כנ\"ל, וכן תנועת האבן הדומם שהאבן מניעו בבחי' מקיף כנ\"ל בשניהם אין גילוי הפעולה ניכרת בכח הפועל כלל כו', דהיינו מה שהאבן הולך באופן כזה לא ניכר אופן הולכה זו בכח המוליכו מאחר שהוא מקיפו מבחוץ אין בו גילוי, אלא שהוא כח מניע לבד, אבל שילך בהולכה כזו לא נגלה ונראה בו כלל. משא\"כ חיות האצבע הנגלית באצבע הרי החיות עצמו מתגלה באופן הכתיבה, וכאלו החיות עצמו הוא מאחר שהוא חי ממנו, ונעשה לאחדי' ממש והרי כח הפועל ניכר בפעולה וד\"ל. וכן בכח המוליך האבן שנמשך מרחוק מהתפשטות ראשונה והוא ג\"כ",[["2476","*7","<b>או\"פ. . או\"מ</b>: ראה ע\"ח (שער השתלשלות) ש\"ב, ענף א. ג. (שער העקודים) ש\"ו, פ\"ב. (שער המקיפין) שמ\"ה, פ\"ג."]]],[2300540131,"בבחי' מקיף כנ\"ל, לא הי' ניכר בהתפשטו' ראשונה כל עיקר אופן כח ההולכה כו'. <span data-k=\"pg\">168</span> ּ משא\"כ הבל הדבור שבכח הפועל בדבור שופע מקרוב בפעולת הדבור הרי כח הדבור מאיר בכל פרטי הפעולה כו' דהיינו כל אות יש לו כח בפ\"ע, והכח של האות עם האות הם לאחדי' ממש כמו באצבע כנ\"ל, והוא משל לחיות או\"פ שאור החיות מתחלק לכל פרטי הכלים המקבלי' החיות וכח הפועל בנפעל ממש כו'. אבל אור חיות המקיף הוא מחי' מרחוק ואין שום התחלקות פרטי נראה ונגלה בו, אלא בהשוואה לכל צד מצדדי' המקבל הוא שופע השפעתו דהיינו בדרך כלל שיהי' נמצא במציאות כללות אותו גילוי האור בלי שום התחלקות מעלה ומטה שבו כו'. והנה כמו\"כ לחיות הנפש בכלי הגוף שהוא גילוי החיות בבחי' מעלה ומטה חיות המוח גדול מערך חיות העינים והידים ומתחלקי' ה' חושי'<sup data-n=\"2477\">7</sup> ראיה ושמיעה כו', עד שהקטן מכולם הוא חוש המישוש שחיותו מצומצם מאד בגילוי כו'. והנה התפשטות חיות זה הגלוי במוח ואברי' כל שעה הוא מקבל מעצמיות הנפש שלמעלה ממהות חיות זה שהאברים חיים ממנו, שזה נק' חיה שהוא להחיות לזולתו, ועצמיות הנפש נק' חי בעצם<sup data-n=\"2478\">*8</sup> שמהות חיות נמשך ממנו כמו שם חכם ע\"ש פעולת השכל שנמשך מכח חכמתו<sup data-n=\"2479\">8</sup> כמ\"ש במ\"א. והנה לפ\"ז ודאי שלגבי עצם הנפש שוה ערך חיות חוש המישוש עם חיות המוח מאחר ששניהם הם בבחי' התפשטות גילוי החיות ועצם הנפש אינו בגדר ומהות חיות כלל, רק שהתפשטות החיות כללית נמשך מעצם הנפש והתפשטו' זה הוא שמתפשט לחיות המוח וחיות המישוש כו'. נמצא שגם לאחר שנתפשטה החיות הגלוי באיברי' שונים וכל שעה הוא מקבל מעצם הנפש הנק' מקיף, קבלתו הוא מחיצוני' דחיצוני' דמקיף דהיינו ממש כמשל זריקת האבן שהוא התפשטו' ראשונה ונפרדה אח\"כ שלא ניכר בהתפשטו' ראשונה כל פרטי פעולה הגלויי' כנ\"ל, ואעפ\"כ כח ההליכה<sup data-n=\"2480\">*9</sup> הוא כפי שנמשך ונזרק מתוך כח היד כו', רק שהארתו מרחוק כנ\"ל, כמו\"כ חיות עצם הנפש לכל האברים מרחוק הוא ובדרך כלל בהשוואה לכולם לקטן וגדול כו'. וענין הריחוק הוא [שכללות התפשטות ראשונה מובדלת ומופרדת להיות ראש לחיות המוח וראש לחיות המישוש וד\"ל. ונמצא שהבדלת או\"פ מן או\"מ הוא] בבחי' מסך מבדיל ממש ביניהם שהרי עצם הנפש אינו ראש ומקור כלל לחיות המוח ולא ראש לחיות המישוש כו', רק כללי' התפשטו' הראשונה היא המקור הכללי שלהם הוא הנק' או\"פ ומובדל הוא מערך עצם הנפש הנק' חי כנ\"ל, וכמו שמובדל כח התנועה שבאבן מכח היד כנ\"ל וד\"ל. אבל התפשטות החיות הכללי הראש ומקור למוח וראש לחוש המישוש הרי מהות חיות",[["2477","7","<b>ה' חושי'</b>: ראה מו\"נ ח\"א פמ\"ז. חובת הלבבות שער עבודת אלקים פ\"ט. בחיי ואתחנן ד, כח. כד הקמח אות ז. אלימה רבתי עין הבדולח תמר ג פי\"ג (סח, ג). עין שמש תמר ה פכ\"ד (קמג, ד). ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"י. עמק המלך שער עולם התהו פמ\"ח (כז, ג). וראה זהר (רע\"מ) פינחס רכט, ב."],["2478","*8","<b>ועצמיות הנפש נק' חי בעצם</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' סט. ע' ק. תקס\"ד ע' קכא."],["2479","8","<b>שם חכם. . מכח חכמתו</b>: ראה מאמרי אדה\"ז אתהלך לאזניא ע' סט."],["2480","*9","<b>ההליכה</b>: א: ההולכה — וכ\"ה גם במאמרי אדה\"ז אתהלך לאזניא כאן."]]],[2300540168,"זה הוא שנעשה שכל ונעשה חוש המישוש כמו שמהות חיות הרוחני שבאצבע הוא הפועל כל רגע באצבע בכתיבתו כנ\"ל, שכל פרטי הפועל ניכר בפעולה דהיינו מהות הפועל הוא בנפעל שנשתנה מהותו להיות לאחת<sup data-n=\"2481\">9</sup> ממש עם הנפעל כנ\"ל וא\"כ אין בחי' מסך מבדיל בין פועל לנפעל כלל וד\"ל. וע\"פ משל הנ\"ל יובן למשכיל למעלה שאורות דאצי' העצמיי' הם הנק' סוכ\"ע באמת אינם בגדר וסוג שיחיו ויהיו נשמות ומלאכי' דעולם הבריאה מאין ליש כמו כח הפועל בנפעל דוגמת כתיבת האצבע בלי בחי' מסך מבדיל כו', שהרי נק' מקיפים וכל מקיף מחיה מבחי' עשיי' שבו לבד והוא כמשל חיות עצם הנפש שכל חיות הגוף יחי' ממנו כנ\"ל, וכמשל זריקת האבן הנ\"ל וד\"ל. אבל ל' אורות<sup data-n=\"2482\">10</sup> מכלים דאצי' היורדי' <span data-k=\"pg\">פד</span> ּ להיות ראש לשועלים בבחי' כח הפועל בנפעל לה[ו]ות הנשמות מאין ליש הרי מהות האורות הוא שנשתנה למהות נשמות והוא ענין בקיעת המסך, פי' שמאירי' בנפעל שהוא נשמה המובדלת בלי מסך מבדיל ביניהם אלא כדוגמת כתיבת האצבע שחיות הרוחני המחיי' בשר האצבע הרי עצמיותו מתגלה בבשר האצבע כו' וד\"ל. וזהו לכי ומעטי את עצמך דוקא, שעצמך ומהותך הוא שמתמעט להיות מקור לבעלי גבול וראש לשועלים לכל א' בפ\"ע, וכמשל הבל הדבור שכל אות יש לו כח ומקור בפ\"ע הפועלו בגילוי כנ\"ל וד\"ל.\n[ג] <b>וזהו</b> כי ה' יתן חכמה מפיו דעת ותבונה, פי' מפיו הוא מדת מלכותו<sup data-n=\"2483\">11</sup> ית' היורדת להיות ראש לשועלים וכמ\"ש וברוח פיו כל צבאם<sup data-n=\"2484\">12</sup>, וידוע משל הבל הדבור מכח הדבור שיבא הכח לידי בחי' התחלקות מעלה ומטה כנ\"ל, וידוע שנמשלי' כל העולמות כמו ציור אדם<sup data-n=\"2485\">13</sup> ראש ואיברים פנימי' וחיצוני' ויש כללות חיות המחי' ומקור כללי להם והוא נשמת האדם דבריא' כו'. וכמו שבאדם התחתון המדות שבלב המה עיקר הנהגת כל הגוף לאהוב ולשנוא כו', כמו\"כ עיקר הנהגת כל הנפעלי' דבי\"ע כו', המה מדות שבמל' הנק' גדולה וגבורה כידוע, אך המדות לא היו מתחלקי' כלל להיות חסד מתחלק לכמה רבבות מדרגות כמו לאהוב כך וכך, ובכמה אופנים שונים כו', אינו אלא ע\"י הדעת המתפשט במדות שיכריח הדעת את המדה להיות באופן פרטי כזה, מפני שהדעת כולל תחלה חו\"ג<sup data-n=\"2486\">14</sup> יחד שכפי שיטה דעתו כן יהי' האהבה כו'. נמצא שסיבת ריבוי חילוקי אופני המדה אינו אלא ע\"י הדעת, וזהו ובדעת חדרים ימלאון<sup data-n=\"2487\">15</sup> שיש אדרי' ואכסדרי'<sup data-n=\"2488\">16</sup> שהדעת מתמלא בהם, פי' החדר הוא במדה המקבלת הדעת בתוכה ממש, ולכן ירבו מאד האדרי'<sup data-n=\"2489\">17</sup> שמפני שהדעת המתפשט ומתמלא במדות רבים רב מאד שינויי אופניהם, ולולי",[["2481","9","<b>לאחת</b>: א: לאחדים — וכ\"ה גם במאמרי אדה\"ז כאן."],["2482","10","<b>ל' אורות</b>: נסמן לעיל כד, ב הערה 37."],["2483","11","<b>מפיו. . מלכותו</b>: ראה ת\"ז תס\"ט (קה, א). שם בהקדמה (יז, א)."],["2484","12","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["2485","13","<b>העולמות כמו ציור אדם</b>: ראה גם לקמן פ' בשלח קסה, ג. וש\"נ. מאמרי אדה\"ז תקס\"ג ח\"א ע' רמח (נוסח א'). תקס\"ה ח\"ב ע' תשכט. דרך מצותיך ע' 350."],["2486","14","<b>שהדעת כולל. . חו\"ג</b>: ראה ע\"ח (שער תיקון הנוקבא) של\"ד, פ\"ג. מאמרי אדה\"א בראשית ע' ד. וש\"נ. שעה\"י קלא, ב הערה 32. לקמן פה, ד. פ' משפטים רפג, ד. תצוה שכב, ד. שנג, ב."],["2487","15","<b>ובדעת חדרים ימלאון</b>: נסמן לעיל פ' שמות מב, א."],["2488","16","<b>אדרי' ואכסדרי'</b>: כ\"ה גם במאמרי אדה\"ז כאן. אב: חדרים ואכסדרות."],["2489","17","<b>האדרי'</b>: אב: החדרים."]]],[2300540205,"הדעת לא הי' רק שני קוין לבד, חסד לבדו, ולא הי' נמצא גבורה שבחסד וכו'. ואחר שנתחלקו המדות ישלחו מקורם וכח פעולתם באברים המקבלי' מהם והוא אברי' הפנימיי' שיש בהם חו\"ג ג\"כ אבל הוא בגשמי', כמו כח הדוחה המאכל שנמשך מגבורו' כו', וכן כח המעכל כו', וכח המחזיק הוא בהיפך כו', ובזה המה טבעי' אברי' הפנימי' מתחלקי' מאד, זה טבעו לבשל כמו הקיבה וטבע הריאה להניף רוח כו', והדקי' טבעם לשנות מהות המאכל כו' עד שהכרכשתא טבעו להוציא הפסולת הגמור כו', והרי כחו' הרוחניי' שבכל א' מהם הוא נמשך מכללות חיות הנפש שמחי' אותם ולפי טבע מזגם כן יעשו במאכל כו'. כמו\"כ יובן במלאכים עליונים הנק' אברי' פנימי' דשכינתא<sup data-n=\"2490\">18</sup> והמה המקבלי' השפעות חיות אם לדחות או להחזיק כו', וכל פרטי האופנים הכל מצד קבלתם ממקורם שהם פרטי חילוקי המדות שבלב שנתחלקו מן הדעת שנתפשט בהם כו', עד ששמרי האופני' הם הוצאת פסולת חיים העליונים והוא השפעת גשמיות דצח\"מ של המזלות וד\"ל. וזהו ותתן טרף לביתה<sup data-n=\"2491\">19</sup> והוא המאכל של אכלו ריעי'<sup data-n=\"2492\">20</sup> ומתברר בקרביי' כו'. וזהו מפיו הוא כח הפועל אלקי הכללית המוצא הדעת להתפשט ולהתמלאות בחדרי' עד שיתהוו חדרי' המוגבלי' והם היכלות היכל לבנת<sup data-n=\"2493\">21</sup> כו' והוא תבונ' טעמי המדו' בפרטי חילוקם וד\"ל. אבל ה' יתן חכמה כח מ\"ה<sup data-n=\"2494\">22</sup> הוא אל ברוך<sup data-n=\"2495\">23</sup> כתר מל' שהוא בחי' מקיף ונעשה <span data-k=\"pg\">170</span> ּ גדול דיעה והכין ופעל זהרי חמה כו', והוי' יתן הוא השפעת סוכ\"ע שהוא מבחי' עשיי' שבו וזהו יתן חכמה כמ\"ש נטל צרור וזרק<sup data-n=\"2496\">24</sup> כו' וד\"ל. ובזה יובן ענין זו המדה שנעשה במדת מל' להיות מתחלקי' המדות ע\"י הדעת ומתחלה הוא קו לבד והם חסד או גבורה ואח\"כ הדעת הוא חוט המשקולת<sup data-n=\"2497\">25</sup> לשקול ולחלקם לחלקים רבים ולמדוד מדה וגבול לכל מדה וד\"ל, והוא ענין מפיו דעת ותבונה וד\"ל.",[["2490","18","<b>במלאכים. . אברי'. . דשכינתא</b>: ראה פרדס (שער היכלות) שכ\"ד, פי\"א."],["2491","19","<b>ותתן טרף לביתה</b>: משלי לא, טו."],["2492","20","<b>אכלו ריעי'</b>: שה\"ש ה, א."],["2493","21","<b>היכל לבנת</b>: זהר בראשית מא, ב. מה, א. פקודי רנח, א."],["2494","22","<b>חכמה כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["2495","23","<b>אל ברוך</b>: ברכת יוצר [ושם: הכין]."],["2496","24","<b>נטל צרור וזרק</b>: ראה שמו\"ר רפי\"ג. מאמרי אדה\"א נ\"ך ע' קפג. וש\"נ. שעה\"י קיט, ב בהערה 16."],["2497","25","<b>הדעת. . חוט המשקולת</b>: ראה גם הנסמן במאמרי אדה\"א קונטרסים ע' תיא. לעיל פ' שמות מב, א."]]],[2300540056,"<b>בעזר\"ה שבת פ' מצורע</b>\n<b>להבין</b> שרש ענין מצות דרבנן<sup data-n=\"2498\">1</sup> וגם ענין ברכת כל המצות שהם ג\"כ מדרבנן<sup data-n=\"2499\">2</sup>, הנה כנ\"י אמרה כי טובים דודיך מיין חביבים עלי ד\"ס<sup data-n=\"2500\">3</sup> יותר מיינה ש\"ת, וענין יינה של תורה מבואר במ\"א שהם מצות דאורייתא<sup data-n=\"2501\">4</sup> שהם רמ\"ח אברים דמלכא<sup data-n=\"2502\">5</sup>",[["2498","1","<b>להבין שרש ענין מצות דרבנן</b>: מאמר זה הוא כנראה הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז. ראה להלן ברשימת הכת\"י אודות זמן אמירת המאמר."],["2499","2","<b>ברכת כל המצות. . מדרבנן</b>: נסמן לעיל פ' שמות מח, ד."],["2500","3","<b>כי טובים. . חביבים עלי ד\"ס</b>: שה\"ש א, ב. ראה ע\"ז לה, א וברש\"י שם."],["2501","4","<b>יינה של תורה. . מצות דאורייתא</b>: ראה לעיל נה, א. מח, ד."],["2502","5","<b>רמ\"ח אברים דמלכא</b>: נסמן לעיל מו, ב."]]],[2300540094,"ממש<sup data-n=\"2503\">6</sup> דהיינו שהמצוה עצמה היא חלק מעצמותו ית' ולא מזיוו והתפשטותו לבד, כמו נהנין מזיו השכינה<sup data-n=\"2504\">7</sup> שבג\"ע העליון ועולם הבריאה, שקבלת התהוותם מאין ליש מתצמצם תחלה אור א\"ס ב\"ה בג' מיני צמצומי' קדוש<sup data-n=\"2505\">8</sup> קדוש קדוש הוי' צבאות<sup data-n=\"2506\">9</sup>, ה' צבאות הוא זיו השכינה מקור החיים כח הפועל אלקי המהווה את הנברא מאין ליש. אבל כדי שיהי' כח התפשטות זיו מאלקים להחיות רוח שפלים<sup data-n=\"2507\">10</sup> כו' צ\"ל תחלה צמצום עצמותו הנק' קדוש שהוא מובדל<sup data-n=\"2508\">11</sup> אף מכח ההתפשטו', ואם לא הי' צמצום העצמו' לא הי' כח ההתפשטו' מתפשטת כלל להחיות נפרדים כו', כמשל צמצום עצמות השכל של הרב כשצריך להשפיע שכל מצומצם של התינוק כו', שהשגת הרב העצמו' צ\"ל מובדלת ומרוחקת בתכלית מן צמצום השפעת השכל שמסביר לתינוק, ואלו היתה קרובה השגתו העצמי' במוחו בשעה שהוא משפיע השכל המצומצם הי' בטל השכל במקור ההשגה העצמי' ולא הי' ביכולתה להתפשט ולהתצמצם במוח התינוק כו' וד\"ל. כמו\"כ ענין קדוש שהוא סוכ\"ע שלמעלה מזיו השכינה שמתפשטת להיות ראש לשועלים<sup data-n=\"2509\">12</sup> כנודע, אך נק' קדוש בוי\"ו להורות שהוא המשכה<sup data-n=\"2510\">13</sup> מן העצמות ואין לו ערוך לגבי העצמיות ממש ולכן נק' זעיר פי' שצמצום זה בעצמותו הוא בשביל המשכת כח ההתפשטו' כנ\"ל, א\"כ צמצום זה הוא המשכות העצמיות אך אינה בגילוי כמו כח המתפשט כו'. ומ\"מ אף שהוא המשכה אין לו ערוך לגבי העצמיות ממש שהרי מה שצריך להיות מובדל כו' הוא רק המשכה מעצמותו כו', אבל עצמותו ממש אינו בערך שיושפל כ\"כ להיות נבדל כו', כמו כשהרב משיג השגתו בפ\"ע ואין בדעתו כלל להשפיע שאז אינו בערך שפלות זו להשפיל השגתו ולהתצמצם בה כדי שישפיע כו'. ולכן נק' חכ' עילאה דאצי' קודם שמתצמצם ונמשך למדות להיות מובדל בשם קדש<sup data-n=\"2511\">14</sup> עילאה וכשכבר נמשך למדות נק' קדוש ונק' ז\"א וד\"ל. וג' פעמים קדוש מפני שכל התהוות כלול מחב\"ד חג\"ת נה\"י, וכמו\"כ בהמשפיע צ\"ל ההבדלה והצמצום בעצמותו קודם שישפיע בג' דברים אלו תחלה מחב\"ד כו'.\n<b>והנה</b> המצוה היא אבר דמלכא הוא בחי' קדוש שהוא בחי' עצמיות אוא\"ס ב\"ה שלמעלה מחיי העוה\"ב ולכן כתיב ועשיתם את מצותי<sup data-n=\"2512\">15</sup> והייתם קדושים וכמ\"ש במ\"א בארוכה, וכתיב להיות לכם לאלקים<sup data-n=\"2513\">16</sup> שע\"י מעשה המצות אז ה' לאלקים",[["2503","6","<b>אברים דמלכא ממש</b>: נסמן לעיל נד, ג."],["2504","7","<b>נהנין מזיו השכינה</b>: ראה ברכות יז, א. לעיל נ, ב. נב, א."],["2505","8","<b>בג' מיני צמצומי' קדוש</b>: ראה גם לקמן עח, ד. הנסמן במאמרי אדה\"א בראשית ע' תקא."],["2506","9","<b>קדוש. . הוי' צבאות</b>: ישעי' ו, ג."],["2507","10","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["2508","11","<b>קדוש שהוא מובדל</b>: ראה גם לעיל נא, ד. וש\"נ."],["2509","12","<b>השכינה. . ראש לשועלים</b>: נסמן לעיל נד, ב."],["2510","13","<b>קדוש בוי\"ו. . המשכה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380920\" data-slug=\"likkutei-torah\" data-id=\"4001380920\">לקו\"ת נצבים נ, ב</a>. מאמרי אדה\"א הנחות תקע\"ז ע' רסג וש\"נ. לקמן פ' משפטים רפג, ב. תשא שפב, ב. וש\"נ."],["2511","14","<b>חכ'. . קדש</b>: ראה זהר (רע\"מ) בא מג, ריש ע\"ב. אמור צד, ב. לעיל נד, ג. לקמן פ' תצוה שסב, ב. ויקהל תלו, סע\"ד ואילך."],["2512","15","<b>ועשיתם את מצותי</b>: שלח טו, מ [בדילוג]. ראה לעיל נד, ב. וראה גם מאמרי אדה\"א דברים ח\"ג ע' תתקד."],["2513","16","<b>להיות לכם לאלקים</b>: שלח שם, מא."]]],[2300540132,"בכל נפש מישראל. וענין לאלקי' ידוע שהוא כח הפועל בנפעל ממש והיינו בבחי' או\"כ כמו שהכלי מעין ודוגמת האור והיו לאחדים ממש כידוע. <span data-k=\"pg\">פה</span> ּ כמו\"כ הארת אור א\"ס ב\"ה העצמיו' הנק' קדוש מאיר בנפש המוגבלת בבחי' אור וכלי והיו לאחדי' כמו כח הפועל בתוך הנפעל, והיינו להיות הוי' שהוא הקב\"ה לאלקי' בתוך הנפש ממש, ואיך יהי' בחי' קדוש ומובדל בתוך הנפש המוגבלת כו', אין זה אלא ע\"י המצוה שהוא אבר דמלכא ממש. וכמו שע\"י האבר יכולין להמשיך כל עצמיות האדם<sup data-n=\"2514\">*17</sup> כו', והיינו<sup data-n=\"2515\">17</sup> כשקורא בתורה, ואז הקב\"ה יושב ושונה ג\"כ כנגדו<sup data-n=\"2516\">18</sup> ממש, וכל התורה שמותיו<sup data-n=\"2517\">19</sup> כו' שעיקרה בבחי' אצי'<sup data-n=\"2518\">*20</sup>, כמו אדם כי יהי' בעור בשרו<sup data-n=\"2519\">20</sup> כו' נגע שהוא אדם דאצי' כי יהי' צמצום בעור ובשר כלים דאצי' כו', וכיוצא בזה כל התורה הוא בבחי' אלקות ממש כו'. וזהו שיושב ושונה במוחין דאצי' שזה כשר וכו' וא\"כ בשעה שלומד האדם דבר ההלכה אז שורה במוחו ממש מוחי' דאצי' כמו שההלכה היא בבחי' אצי' וד\"ל. וההשראה הוא בבחי' כח הפועל בנפעל ולא בבחי' מקיף וד\"ל. וכן כשמניח תפילין באתעדל\"ת גם הקב\"ה מניח תפילין אז מאיר בנפשו האלקי' בחי' תפילין דמארי עלמא<sup data-n=\"2520\">21</sup> ממש וד\"ל. וכן בהתעטפו בטלית הגשמי כמו\"כ מתעטף הקב\"ה בטלית<sup data-n=\"2521\">22</sup> כמ\"ש עוטה אור כשלמה<sup data-n=\"2522\">23</sup> כו', נמצא מצות הוי' שהם טליתו ותפיליו ותורתו שהם מבחי' עצמיות אוא\"ס ב\"ה בחי' סוכ\"ע, מאיר בנפש האדם בבחי' או\"כ בשעה שהוא עושה המצוה וזהו להיות הוי' לכם לאלקי' וד\"ל.\n<b>והנה</b> ההפרש שבין מצות דאורייתא למצות דרבנן, שמצות דאורייתא הם מבחי' או\"פ ומצות דרבנן הם מבחי' או\"מ, וזהו עריבים עלי ד\"ס, וצריך להבין תחלה ענין או\"פ ואו\"מ<sup data-n=\"2523\">*24</sup>, דהנה אור פנימי הוא מה שנכנס בתוך אופן מהות הנפש לחיות ממש כמו המאכל שמחי' נפש האדם, שטעם המאכל מחזיק מהות הנפש ותאיר אורה ביותר תוקף ועוז, וקיום הנפש מטעם המאכל כו' אינה מובדלת בערך אלא קרובי' הם והיו לאחדי' כו'. אבל הלבוש שאדם מתלבש בו א\"צ כלל לקיום נפשו לחזקה, ואין בלבוש שהוא דומם מצמר ופשתים כח וחיות להחיות הנפש, אך מתלבש בו האדם בשביל שמירה מהיזק גופו שלא יוזק בקרירו' ואין בו אלא השמירה לגוף שלא יכנס בו הקרירות אבל אין הלבוש מחי' כלל את הגוף. ומ\"מ מבואר במ\"א שיש בהלבוש",[["2514","*17","<b>שע\"י האבר יכולין להמשיך. . האדם</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' שמ. לקמן פ' ויקהל תלג, ג. ש\"א ל, ב ובהנסמן במ\"מ לשם."],["2515","17","<b>כו' והיינו</b>: כנראה שחסרו כאן איזה תיבות."],["2516","18","<b>הקב\"ה. . כנגדו</b>: ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. קונטרסים ע' תקמז. וש\"נ. לקמן פ' יתרו רסג, ב. תרומה שטו, ב. תצוה שנז, ב. שע, ב. פקודי תמג, סע\"א ואילך."],["2517","19","<b>וכל התורה שמותיו</b>: ראה זהר יתרו פז, א. פתיחת הרמב\"ן עה\"ת. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' נב."],["2518","*20","<b>התורה. . אצי'</b>: נסמן לקמן פ' בא קיד, ב."],["2519","20","<b>אדם. . בעור בשרו</b>: תזריע יג, ב."],["2520","21","<b>תפילין דמארי עלמא</b>: ברכות ו, א."],["2521","22","<b>מתעטף הקב\"ה בטלית</b>: נסמן לעיל פ' שמות ז, ד."],["2522","23","<b>עוטה אור כשלמה</b>: תהלים קד, ב."],["2523","*24","<b>או\"פ ואו\"מ</b>: נסמן לעיל נז, ב."]]],[2300540169,"יתרון גדול<sup data-n=\"2524\">24</sup> אפי' על או\"פ של הנפש המחי' הגוף, להיות כי השמירה שהוא שומר הגוף יורה שיש בו השראת אור המקיף של הנפש, שהרי ביכולתו להיות שומר חיות הנפש שלא תוזק וכל שומר גדול בודאי מן המשתמר<sup data-n=\"2525\">25</sup> כו'. אך בשמירה זו מהקרירות אין השראת אור המקיף בבחי' גילוי בכח הפועל בנפעל כו', שהרי אינו אלא סובל הקרירות בו ומחמת זה לא יכנס בגוף וכמ\"ש במ\"א<sup data-n=\"2526\">26</sup>, וזהו דבר גשמי ואין לו ערוך לאור המקיף של הנפש כו'. אבל ישרה בו אור המקיף בבחי' השראה ודירה לבד כאדם הדר בבית שהבית עכ\"פ מכסהו אע\"פ שאין ערוך לבית הגשמי עם האדם כו', וזהו מוכרח מצד שאנו רואים ענין השמירה שמשמר לחיות הנפש שלא תוזק כו'. ויובן זה יותר ממשל השפעת שכל לתינוק בבחי' אור וכלי שמה שהרב שומר לשון ההשפעה שלא יכשול בה התינוק זה אינו משיג התינוק ולא יוכל להשיג זה רק הרב מצד עצמיות השגתו הרחבה, ועכ\"ז אין בשימור הלשון הארת השגתו העצמית בגילוי רק בבחי' לבוש לבד כו'. וכן משל השגחת הגדול על הקטן מרחוק שלא יפול בבור שהשגחתו מרחוק <span data-k=\"pg\">172</span> ּ אינה נכנסת בהשגת הקטן ההולך כו' וגם אינה נגלית בו בבחי'<sup data-n=\"2527\">*27</sup> לבוש לבד וד\"ל. כמו\"כ הארת אור המקיף של הנפש בלבושי' של האדם אינו בבחי' או\"כ אלא השראה לבד וזהו שנמשך בהם השמירה כו', ולכן קשה לשכחה כשלובש ב' מלבושים כאחד<sup data-n=\"2528\">27</sup> שהזכרון הוא מצד המקיף ובמלבושי' שורה על המקיף<sup data-n=\"2529\">*28</sup> וכשלובשם יחד מתמעט השראת המקיפים כו' וד\"ל. ונמצא מובן שהלבוש מצד עצמותו הוא פחות בערך מאד והוא דומם גשמי, ועכ\"ז ישרה בו אור המקיף כנ\"ל. ובזה יובן מה שנמצא בכתבי האריז\"ל וכן בזהר בראשית שיש תערובות טו\"ר<sup data-n=\"2530\">28</sup> בהיכלות<sup data-n=\"2531\">*29</sup>, ובהיכל א' יכול להיות מלאכי' טובי' וקדושי' ומלאכי' רעי' כו', ואין ההיכלות אלו מהארת י\"ס שנמשכים בבחי' או\"פ להוות מאין ליש והרי כח הפועל אלקי בהם בבחי' גילוי והיו לאחדי' כו', שא\"כ לא היו מעורבי' טו\"ר ח\"ו שאין בספי' שהם אלקות ממש שום תערובות רע ח\"ו כי אין רע יורד<sup data-n=\"2532\">29</sup> כו'. אבל היכלות אלו הם בחי' לבושי' של הי\"ס ובלבוש אין הארת החיות בבחי' או\"כ כנ\"ל רק הארת אורות מקיפים בהם בבחי' השראה כנ\"ל, והלבוש מצד עצמו הוא בחי' דומם רחוק מאור פני אלקים חיים מאד, ולכן יוכל להיות בהיכלות אלו תערובות טו\"ר כו' וד\"ל.",[["2524","24","<b>בהלבוש יתרון גדול</b>: ראה גם מאמרי אדה\"ז הקצרים ע' שמו. אתהלך לאזניא ע' יא. ענינים ע' תלא. וראה גם תו\"א ח\"ש טז, א."],["2525","25","<b>וכל שומר. . המשתמר</b>: ראה מאמרי אדה\"ז שם (מע\"ח). תקס\"ז ע' שצט. תקע\"א ס\"ע רפג. מאמרי אדה\"א נ\"ך ע' שמח. וש\"נ. לקמן פ' בשלח רלו, א. תצוה שעח, ד."],["2526","26","<b>סובל הקרירות. . במ\"א</b>: ראה גם מאמרי אדה\"ז שם."],["2527","*27","<b>בבחי'</b>: כנצ\"ל: רק בבחי'."],["2528","27","<b>קשה לשכחה כשלובש ב' מלבושים כאחד</b>: ראה שו\"ע האריז\"ל הלכות תיקון חצות ס\"ו. שו\"ע אדה\"ז חאו\"ח ס\"ב, ס\"ג במהדו\"ק ובמהדו\"ת. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקלז [נוסח א']. תקס\"ד ר\"ע עז [מכתבי האריז\"ל ומבואר במ\"א באריכות] ובנסמן במ\"מ לשם. תקס\"ז ע' שצח [ושם: אסור]. מאמרי אדה\"א דברים ח\"א ע' קיד. וש\"נ. לקוטי לוי\"צ פסחים ע' קכו."],["2529","*28","<b>ובמלבושי' שורה על המקיף</b>: במאמרי אדה\"ז תקס\"ז שם: אור המקיף שורה על המלבושים."],["2530","28","<b>תערובות טו\"ר</b>: ראה גם סה\"מ תרנ\"ח ס\"ע לא ואילך."],["2531","*29","<b>תערובות טו\"ר בהיכלות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670208\" data-slug=\"torat-chaim\" data-id=\"2300670208\">תו\"ח וירא צט, ד</a> ובהערה 41 [ושם: מלאכים דעשי']."],["2532","29","<b>אין רע יורד</b>: ראה ב\"ר פנ\"א, ג. גנת אגוז לר\"י גיקטיליא ח\"א שער ההוי' ירושלים תשמ\"ט ע' מו. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסו ובהנסמן במ\"מ לשם. שע\"ת יז, ד הערה 13. לקמן פ' תצוה שמב, ד."]]],[2300540206,"<b>ועתה</b> יובן ההפרש שבין מצות דאורייתא למצות דרבנן שרמ\"ח פקודין הם רמ\"ח אברי' דמלכא שהוא ענין י\"ס מבחי' או\"פ, פי' כמו מצות תפילין שהם תפילין דמארי עלמא שהוא מוחין דאצי' המקור למדות דאצי' וכתיב בכל מצוה<sup data-n=\"2533\">30</sup> וידבר הוי' אל משה לאמר<sup data-n=\"2534\">31</sup>, שכל מצוה כמו שהיא בבחי' אצי' נמשכה ונשתלשלה ע\"י משה ובא לידי דבור בהתגלות והוא ענין נבואה בורא ניב שפתים<sup data-n=\"2535\">32</sup> כו'. פי' שתפילין דאצי' נתגלו ע\"י משה איש האלקים<sup data-n=\"2536\">33</sup> במ' דאצי' שהוא התגלות דבר ה' המחי' כל העולמות כידוע, והרי מוחי' דאצי' כשמתגלי' בדבור הם בבחי' או\"כ והיו לאחדים ככח הפועל בנפעל וא\"כ לא הי' התגלות המוחין כ\"א מה שהי' יכול לבוא לידי השפעה והיינו בחי' או\"פ כו', אבל מקיפי המוחין לא הי' משה יכול לאומרן בדבור כו'. ונמצא כל מצות שהם אברים דמלכא הם מו\"ס שמשתלשלי' בבחי' אורות וכלים כו' בכדי להיות הוי' לאלקים בתוך כל נפש מישראל כנ\"ל וד\"ל. אבל מצות דרבנן הוא בחי' חכמה דעדיפא מנבואה<sup data-n=\"2537\">34</sup>, ויש בה יתרון גדול על הנבואה מצד שרשה בבחי' מקיף.\n<b>וביאור</b> הענין דהנה חכמי ישראל עשו סייג וגדר בכל דור למצות התורה כמו שאסרו גבינות הגוים<sup data-n=\"2538\">35</sup> שאין בהם איסור מן התורה כלל והסופרי' המה חכמי ישראל ראו שיש לגזור גזירה זו על הצבור, ולא גילו טעם הגזירה כמו ששאלו ר' ישמעאל<sup data-n=\"2539\">36</sup> לר' יהושע וא\"ל האיך אתה קורא כי טובים דודיך כו', כלומר למה לך טעם הנגלה בגזירה זו, הלא הסופרים הם המשיגים בחכמה שבהם שצריך שמירה וסייג לאיזה מצוה מן המצות, והוא כי טובים דודיך מיין מיינה של תורה מהמצוה עצמה שהסייג וגדר הוא השמירה שלא יתקלקל גוף הדבר וכל שומר גדול מהמשתמר כו' כי יש בשומר הארת מקיף של גוף הדבר כנ\"ל. וכמו\"כ עיקר מצות דרבנן המה רק גדרים וסייגים למצות, כמו מצות נט\"י שהוא מד\"ס<sup data-n=\"2540\">37</sup> לבד ומן התורה לא נאמרה למשה שיקחו רביעי' מים<sup data-n=\"2541\">38</sup> כו', א\"כ אין במצוה זו שום השראה בנפש אלקי' כמו במצות הוי' שהיא אבר דמלכא מאחר שלא <span data-k=\"pg\">פו</span> ּ ציוה ה' אל משה לאמר כו'. אך עכ\"ז אף שלא נתגלית מעשה זו של רביעי' מים ליטול על הידים בדבר ה' מהארת י\"ס דאצי' מאורות פנימיי' כו', מ\"מ בבחי' אורו' מקיפי' דד\"ס שהוא מקיף חכמה דאצי' משם השיגו הסופרי' מעשה זו כו', והוא ענין חכם עדיף מנביא<sup data-n=\"2542\">39</sup>, שהחכם חכמתו בחי' מרכבה ובטילה למהות חכמה דאצי' מא\"מ<sup data-n=\"2543\">40</sup> דהיינו ממה שלא יוכל לבא לידי השפעה",[["2533","30","<b>וכתיב בכל מצוה</b>: ועד\"ז [בכל פ' פרשה] בשע\"ת לט, א ובהערה 8. וראה מאמר ד\"ה זה שמי ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370236\" data-slug=\"torah-or\" data-id=\"3901370236\">תו\"א שמות נב, ד</a>־ מאמרי אדה\"ז תקס\"ה ח\"א ע' ריב. ד\"ה אי' ספר תקס\"ה [הנחת כ\"ק אדה\"א נמצאת בבוך 2076 עא, ב]. מאמרי אדה\"א נ\"ך ס\"ע סה ואילך. לקמן פ' בא קיד, א. יתרו רנו, ג. תצוה שנז, א. שסב, ד. שסט, ד. ויקהל שצב, ד."],["2534","31","<b>וידבר הוי' אל משה לאמר</b>: בא יג, א. יב, א. מג."],["2535","32","<b>נבואה בורא ניב שפתים</b>: ישעי' נז, יט. רש\"י וארא ז, א. ראה גם שע\"ת קז, ג. לקמן פ' בא צז, ד. קיד, ג."],["2536","33","<b>משה איש האלקים</b>: ברכה לג, א. תהלים צ, א."],["2537","34","<b>חכמה דעדיפא מנבואה</b>: נסמן לקמן הערה 39."],["2538","35","<b>שאסרו גבינות הגוים</b>: ע\"ז כט, ב [במשנה]."],["2539","36","<b>ששאלו ר' ישמעאל</b>: ע\"ז שם."],["2540","37","<b>נט\"י שהוא מד\"ס</b>: נסמן בסמוך הערה 42."],["2541","38","<b>נט\"י. . רביעי' מים</b>: ראה ידים פ\"א, מ\"א. שו\"ע אדה\"ז חאו\"ח סק\"ס, סט\"ז."],["2542","39","<b>חכם עדיף מנביא</b>: ב\"ב יב, א. ראה לקוטי הש\"ס מהאריז\"ל סוף מס' יבמות. וראה ג\"כ מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670156\" data-slug=\"torat-chaim\" data-id=\"2300670156\">תו\"ח נח מח, א</a> ובהערה 6. לקמן נט, ג."],["2543","40","<b>מא\"מ</b>: מאור מקיף."]]],[2300540238,"במדות בבחי' או\"כ, ולכן אין במעשה זו שום הארה בבחי' כח הפועל בנפעל שהוא הנפש כו', אלא יהי' בה הארת המקיפי' בבחי' השראה בדרך לבוש שהרי מעשה זו של נט\"י היא סייג וגדר לשמור מצות תרומה וקדשים<sup data-n=\"2544\">41</sup>, וה\"ז כמו הלבוש שהוא שומר לגוף שיש בלבוש הלבשת המקיף כנ\"ל, והוא כמשל המשגיח מרחוק על צמצום ההשפעה שלא תתקלקל כו' שאין ההשגחה נגלי' בבחי' או\"כ אלא מתלבשת בדבר שמן הצד כו' וד\"ל. ולכן בשעה שתיקן שלמה<sup data-n=\"2545\">42</sup> עירובי' ונט\"י אמרה חכם בני<sup data-n=\"2546\">43</sup> כו' שהשיג בחכמתו הסייג וגדר למלאכת הוצאה שהיא מ' ל\"ת<sup data-n=\"2547\">44</sup> הנמשכת בדבר ה' אל משה לאמר, וכאשר יוודע טעם איסור מלאכת הוצאה בצמצום השפעת השכל לבד לא יוכל למצוא סייג וגדר איך שלא לבא לידי הוצאה כו'. אבל כאשר ידע וישיג עומק הטעם שהוא בחי' המקיף אז יוכל למצוא השכלה בדבר שמן הצד איך שתושמר השפעה המצומצמת כו'. כמו השפעת הרב לתלמיד יסבב עצמו בדבר מן הצד בכדי שלא ילך התלמיד בדרך עקלתון, הנה הסביבה באה מן עמקות השגת הרב, ואם הי' הרב מצמצם שכלו כפי אופן השפעתו לתינוק לבד לא הי' ביכולתו להמציא הסביבה והשימור בדברים שמן הצד לענין ההשכלה כו', וכל ששכל הרב יותר בעמקות יודע יותר לסבב ולמצוא שמירה מן הצד כו', ועכ\"ז בזה שנעשי' השמירה והסיבוב הוא בבחי' אחוריי' של השפעת ההשכלה ולא בפנימית ההשכלה כו', להיות כי אין השראת המקיף אלא בדבר החיצוני יותר כמו שהוא שורה בלבושי' כנ\"ל וד\"ל. כמו\"כ הסופרי' נק' חכמים שמשיגי' הגדרים והסייגים למצות ה', ואע\"פ שמעשה המצוה דרבנן עצמה היא כמו בחי' לבוש לגבי מצות הוי' עכ\"ז יהי' בה השראת מקיף שלם<sup data-n=\"2548\">*45</sup> המצוה וד\"ל.\n<b>וזהו</b> כי טובים דודיך מקיפי' דאו\"א דאצי' מיין מיינה של תורה יין המשמח<sup data-n=\"2549\">45</sup> להיות מוחי' דז\"א כו', כי אורייתא<sup data-n=\"2550\">46</sup> שהוא ז\"א<sup data-n=\"2551\">47</sup> דאצי' מחכמה עילאה נפקא בבחי' אור וכלי אבל מצות דרבנן יש בהם הארת מקיפים. וזהו ערבים עלי ד\"ס שמספרי' ועושי' סייגי' וגדרי' למצות הוי' יותר מיינה של תורה. והנה החכמים העושי' הסייגי' למצות הוי' ע\"פ ההשגחה בחכ' עילאה דאצי' שהוא אם צריך מצוה פלוני' סייג וגדר או לא, הנה הסייגי' עצמם שהוא מעשה המצוה דרבנן המה בחי' לבושי' לבד כנ\"ל, וכמו שנאמר בלבושי' שהם מתחלפי' ואינם עומדי' בקביעות כמ\"ש כלבוש תחליפם<sup data-n=\"2552\">48</sup> כו', ולבושא דלביש בצפרא<sup data-n=\"2553\">49</sup> לא לביש ברמשא כו', כי אין האדם צ\"ל תמיד בלבושי' אלא",[["2544","41","<b>נט\"י. . תרומה וקדשים</b>: נסמן בהערה הבאה."],["2545","42","<b>בשעה שתיקן שלמה</b>: ראה שבת יד, ב ואילך."],["2546","43","<b>חכם בני</b>: משלי כז, יא."],["2547","44","<b>מ' ל\"ת</b>: מצות לא תעשה."],["2548","*45","<b>שלם</b>: כנצ\"ל: של."],["2549","45","<b>יין המשמח</b>: ס' שופטים ט, יג. תהלים קד, טו."],["2550","46","<b>אורייתא. . מחכמה עילאה נפקא</b>: נסמן לעיל פ' שמות יא, א."],["2551","47","<b>אורייתא שהוא ז\"א</b>: ע\"ח (שער המוחין) ש\"כ, פ\"ג. (שער דרושי הצלם) שכ\"ה, דרוש ח."],["2552","48","<b>כלבוש תחליפם</b>: תהלים קב, כז."],["2553","49","<b>ולבושא דלביש בצפרא</b>: ראה ת\"ז תכ\"ב סה, א."]]],[2300540269,"ילבשם בשעה שהוא צריך בזמן הקור או לצאת בדרך למרחוק כו', וכן כמו אותיות המחשבה שהם לבושי' הם מתחלפי' שמשוטטי'<sup data-n=\"2554\">50</sup> כו' בכל רגע מתהוה מחשבה אחרת כו'. כמו\"כ כל מצות דרבנן מתחלפי' לפי העת והזמן כו', כמו שבא שלמה ותיקן עירובין, ונט\"י וקודם <span data-k=\"pg\">174</span> ּ שבא שלמה אכלו כל ישראל בלא נט\"י ולא הי' פגם כלל לנפשם האלקי', כמו שיש עתה פגם גדול לאוכל בלי נט\"י ונעקר מן העולם<sup data-n=\"2555\">51</sup> כו', כי לא היו מצות תרומה וקדשים צריכין לבוש עדיין קודם שבא שלמה. אבל כשהשגיח שלמה בחכמתו שעתה הוא העת שצריכי' לבוש עשה הרחקה וגדר והוא נט\"י מפני סרך קדשים, ובהרחקה זו מאיר או\"מ של מצות תרומה וקדשים והמזלזל בה נעקר מן העולם וכמ\"ש בכתבי האריז\"ל<sup data-n=\"2556\">52</sup> בעוצם הפגם כו', וכן תיקן עירובין לשמור מלאכת הוצאה ולא היתה צריכה שימור קודם לכן וד\"ל. וכן כל גזירות י\"ח דבר<sup data-n=\"2557\">53</sup>, וכל גזירות של חכמי ישראל בכל דור הוא שראו והשיגו שהשעה צריכה לכך לגדור גדר למצוה פלוני' ולא גילו טעם הגזירה בסברת טעם עד יב\"ח<sup data-n=\"2558\">54</sup> כו'. ומה שראו הוא בחי' השגת חכם עצמיות הדבר דעדיף מנביא וכמ\"ש במ\"א בענין חכם<sup data-n=\"2559\">55</sup> עדיף מנביא, שהנביא הוא שמאיר בו הארת הדבר כפי אופן קבלת נשמתו לבד, והוא כח הפועל בתוך הנפעל ממש לפי ערכו לבד ולכן הי' מופשט מגשמיותו לגמרי כו'. אבל החכם המשיג בהשגתו יכול להשיג אף מה שאין ערוך להיות מקור לנפשו כמו למעלה מעולם האצי' כו', כמו\"כ בהשגת החכמי' הי' אפשר להם להשיג מקיפי' של כל המצות מה שא\"א למשה לאמור וד\"ל.\n<b>ועתה</b> יובן ג\"כ ענין ברכות כל המצות שהם מדרבנן שהם ג\"כ בחי' או\"מ על הנפש בענין אחר, להיות כי העשיי' עצמה בעשותו המצוה בהנחת תפילין באתערותא דילי' מתעורר לעילא ענין הנחת תפילין דמארי עלמא כנ\"ל. אך איך יתעורר לעילא במעשה אדם התחתון שהוא בתכלית השפלות מתועב ברוח הגסה דקלנ\"ו<sup data-n=\"2560\">56</sup> כו', לזה תקנו הברכה אשר קדשנו בבחי' מקיף דהיינו להגביה את הנפש לבחי' סוכ\"ע דקמי' כחשיכה כאורה, ואז חשך הנפש מתהפך לאור כמ\"ש במ\"א שנעוץ התחלה בסוף<sup data-n=\"2561\">57</sup>",[["2554","50","<b>אותיות המחשבה. . שמשוטטי'</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע רסב ואילך. ובהוספות ע' 7. שע\"ת צא, ג הערה 40. ש\"א ז, א ובהנסמן במ\"מ לשם."],["2555","51","<b>ונעקר מן העולם</b>: סוטה ד, ב."],["2556","52","<b>בכתבי האריז\"ל</b>: ראה שער מאמרי רז\"ל סוטה שם. לקוטי הש\"ס מס' שבת [בני ברק ו, ב]. נגיד ומצוה דברים השייכים בסעודה [ירושלים תשכ\"ה ע' פז]. וראה גם מאמרי אדה\"א נ\"ך ע' ל ובהערה שזלזל."],["2557","53","<b>גזירות י\"ח דבר</b>: ראה שבת יג, ב."],["2558","54","<b>ולא גילו. . יב\"ח</b>: ע\"ז לה, א."],["2559","55","<b>במ\"א בענין חכם</b>: ראה גם בהנסמן לעיל הערה 39."],["2560","56","<b>דקלנ\"ו</b>: דקליפת נוגה."],["2561","57","<b>שנעוץ התחלה בסוף</b>: ראה לעיל נה, ד."]]],[2300540298,"כדי להגביה הסוף כו', וכמשל עיגול המסבב מלמעלה ומלמטה בשוה כמש\"ש, ואז תהי' ביכולת הנפש במעשי' לעורר מצות הוי' לעילא בבחי' אצי' כו'. ומפני שחכמי ישראל יודעין תוכן כוונת הציווי מבחי' או\"מ לכן ידעו נוסח ההמשכת או\"מ על הנפש לייחדה בקדש העליון כו', וזהו ערבים עלי ד\"ס שהם הברכות של המצות שעל ידם יהי' מצות ה' נעשית לעילא לעילא כו', וכמו וצונו שהוא יחוד קבה\"ו<sup data-n=\"2562\">58</sup> כמ\"ש לעיל שרצה לזכות נשמות ישראל לייחדם במהותו ית' ע\"י העשי' עצמה, כן בנוסח הברכה הוא ג\"כ יחוד קוב\"ה ושכינתי' על עליית חושך הנפש שתוכל לעשות המצוה ולהתקשר ולהשתאב בגופא דמלכא<sup data-n=\"2563\">59</sup> ע\"י העשי' כו' וד\"ל. אך לא תהי' רצון הנפש בנוסח הברכה להשתאב, כי זהו ע\"מ לקבל פרס<sup data-n=\"2564\">60</sup> שמשמשין את הרב בעבודת המצוה כדי להתקשר בו, והרי ברצון התקשרות זו יש בה תערובות עצמו שיהי' הוא מקושר, והחצי אחר הוא לה' שההתקשרות שהוא רוצה הוא במהותו כו', ולכן נק' פרס<sup data-n=\"2565\">61</sup> וד\"ל. אלא שע\"י אמרו הברכה ממילא נעשה היחוד והארת או\"מ עד שבהעשי' תהי' ההשתאבות ממילא ולא שהוא יתן לבו בזה כו', כמו העבד הנאמן שיעשה ציווי אדונו רק מצד שציוה ולא מצד איזה תועלת אפי' לאדון וד\"ל. וזהו שהבין הינוקא בריחא דלבושייהו<sup data-n=\"2566\">62</sup> שחסר בנפשם או\"מ ממצות ק\"ש אף שבעסקם במצוה פטורים היו<sup data-n=\"2567\">63</sup>, אבל או\"מ דק\"ש מ\"מ חסר בנפשם, שנפשם לא עשו ולא נעשה היחוד של וצונו שבמעשה המצוה לזכות ישראל וד\"ל, ובלבושיהן הבין דוקא בריחא<sup data-n=\"2568\">64</sup> מבואר במ\"א.",[["2562","58","<b>וצונו שהוא יחוד קבה\"ו</b>: ראה לעיל נז, א."],["2563","59","<b>ולהשתאב בגופא דמלכא</b>: נסמן לעיל פ' שמות ה, ב."],["2564","60","<b>ע\"מ לקבל פרס</b>: ראה אבות פ\"א, מ\"ג."],["2565","61","<b>והחצי. . נק' פרס</b>: ראה בכורות נח, א. ערוך בערכו. ברטנורה פאה פ\"ח, מ\"ה."],["2566","62","<b>שהבין הינוקא בריחא דלבושייהו</b>: זהר (ינוקא) בלק קפו, א."],["2567","63","<b>שבעסקם במצוה פטורים היו</b>: סוכה כה, א. ראה גם הנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261237\" data-slug=\"likkutei-sichot\" data-id=\"1300261237\">לקו\"ש תשא כרך כו ע' 237</a> הערה 64."],["2568","64","<b>ובלבושיהן. . בריחא</b>: ראה מאמרי אדה\"ז הקצרים ס\"ע שצט. תקס\"ב ח\"א ע' סא."]]],[2300540057,"<b>בעז\"ה פ' וארא, דרוש מאדמו\"ר נבג\"מ זי\"ע שנת תקפ\"א</b>\n<span data-k=\"pg\">פז</span> ּ<b>וידבר</b><sup data-n=\"2569\">1</sup> אלקים אל משה ויאמר אליו אני הוי', וארא אל אברהם<sup data-n=\"2570\">2</sup> אל יצחק כו' עד ושמי הוי' לא נודעתי להם, והנה יש להבין בתחלה כללות מאמר זה דוידבר אלקים אל משה כו' דמשמע דקאי אדסמיך לי' בסוף סדרה שקדמה, שא' משה למה הרעות<sup data-n=\"2571\">3</sup> לעם הזה כו' והשיבו ה' עתה תראה<sup data-n=\"2572\">4</sup> כו', והוא מ\"ש",[["2569","1","<b>וידבר. . וארא</b>: המאמר כאן מיוסד על שני מאמרי אדה\"ז, כדלהלן: א) חלק הראשון [מתחלת המאמר עד להלן סו, א] מיוסד על מאמר ד\"ה זה וידבר. . וארא משנת תקס\"ה שנדפס במאמרי אדה\"ז על פרשיות התורה ח\"א ע' רכו [שם הוא הנחת כ\"ק אדה\"א משנת תקס\"ה. וריש ע' רלב שם נמצא ג\"כ ביאור על המאמר]. ונוסח אחר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370251\" data-slug=\"torah-or\" data-id=\"3901370251\">תו\"א וארא נו, א</a>. והגהות (על התו\"א נדפס) ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300142\" data-slug=\"or-hatorah-hb\" data-id=\"8316300142\">אוה\"ת שמות כרך א ע' קמב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460169\" data-slug=\"or-hatorah-hb\" data-id=\"8316460169\">וע' קסט</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300139\" data-slug=\"or-hatorah-hb\" data-id=\"8316300139\">כרך ח ע' ב'תתפב</a> ואילך. ב) חלק השני [מלהלן סו, א ד\"ה והנה יש לפרש] מיוסד על ד\"ה וארא תקס\"ב שנדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קלד [שם הנחת כ\"ק אדה\"א. ובע' קלז נמצא ביאור על המאמר ובח\"ב ע' תקעט נמצאו ראשי פרקים מהמאמר. ובהוספות שם ע' רצא קיצורים מכ\"ק אדמו\"ר הצ\"צ]. ונוסח אחר בתו\"א נה, א והערות וקיצורים על התו\"א באוה\"ת וארא כרך א' ע' קלט. כרך ז ע' ב'תקפד וע' ב'תקפט. כרך ח ע' ב'תתסה. וראה עוד ע\"ד המאמר וזמן אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["2570","2","<b>וידבר אלקים אל משה. . וארא אל אברהם</b>: וארא ו, ב. ג."],["2571","3","<b>למה הרעות</b>: שמות ה, כב [ושם: הרעתה — ראה תו\"א כאן. מאמרי אדה\"א שמות ח\"א ע' כט]."],["2572","4","<b>עתה תראה</b>: שמות ו, א."]]],[2300540095,"וידבר אלקי' כו' וארא אל אברהם כו', ולכאורה אין זו תשובה כלל על שאלת משה למה הרעות כו'. ועוד יש להבין מ\"ש בתחלה וידבר אלקים בשם אלקי' ואח\"כ א' אני הוי' כו', וגם מ\"ש וארא כו' ושמי הוי' לא נודעתי להם מה זה שייכות לענין התשובה על שאלת משה למה הרעות כו'. ועוד יש להבין בעיקר טעם ענין הגלות הקשה הזה שנגזר עליהם במצרים כמ\"ש ועבדום וענו אותם<sup data-n=\"2573\">5</sup> כו' וכן וימררו את חייהם<sup data-n=\"2574\">6</sup> כו' בחומר ובלבנים, מה הי' החטא שלהם כ\"כ שגזר עליהם גלות קשה כ\"כ משך זמן רב כזה (מאחר שלא קיבלו התו\"מ עדיין וז' מצות ב\"נ<sup data-n=\"2575\">7</sup> שמרו<sup data-n=\"2576\">8</sup> וגם מצות מילה<sup data-n=\"2577\">9</sup> ושבת<sup data-n=\"2578\">10</sup> וכה\"ג<sup data-n=\"2579\">11</sup> שקיבלו מאבות כו'). אך הנה יש להבין תחלה במ\"ש וידבר אלקי' מהו שם אלקים זה שהוא ענין שררה<sup data-n=\"2580\">12</sup> ואדנות כמו עד האלקי' יבא<sup data-n=\"2581\">13</sup> כו', שיתכן שם זה גם ברבים<sup data-n=\"2582\">14</sup> כמו כי יש אלקי' שופטי'<sup data-n=\"2583\">15</sup> כו' וכן כי אלקים קדושים הוא<sup data-n=\"2584\">16</sup> כו', ואיך יתכן ל' רבים באלקים חיים שהוא יחיד ומיוחד אין אלקי' מבלעדו כו'. ומה גם הרי ידוע שמתאחד אלקי' בהוי' שהוא אחד פשוט כמ\"ש כי הוי' הוא האלקי'<sup data-n=\"2585\">17</sup>, כולא חד<sup data-n=\"2586\">18</sup> ממש וכמו במע\"ב דכתי' ביום עשות<sup data-n=\"2587\">19</sup> ה' אלקי' ארץ ושמים כו', ואם הי' בחי' אלקים זה בבחי' רבים כשאר שם אלקי' איך נתחברו יחד ב' שמות דה' ואלקי' לבריא' מע\"ב מאחר שזה יחיד וזה רבים כו'. אלא צ\"ל דשם אלקי' זה הוא בתכלית היחוד דאח\"פ כמו שם הוי' ממש, וא\"כ מה זה שא' וידבר אלקי' כו' ויאמר אליו אני הוי' ולא א' וידבר הוי' אל משה דמשמע דאלקים זה הוא שמתייחד להיות בבחי' שם הוי' ע\"כ א' אני הוי' דכולא חד כו'.\n<b>והנה</b> יש להקדים תחלה ענין מ\"ש גדול ה'<sup data-n=\"2588\">20</sup> ומהולל מאד בעיר אלקינו הר קדשו וארז\"ל אימתי גדול<sup data-n=\"2589\">21</sup> כשהוא בעיר אלקינו דוקא, ולכאורה יש סתירה לזה ממ\"ש גדול ה' כו' ולגדולתו אין חקר<sup data-n=\"2590\">22</sup> כלל גם לא בעיר אלקינו כו'. אך הנה ידוע דמ\"ש לגדולתו אין חקר כלל היינו בבחי' התפשטו' דגילוי אוא\"ס למטה מטה עד אין תכלית, משום שבחי' התפשטות אור זה הוא בבחי' א\"ס ממש משום דאיהו וחיוהי<sup data-n=\"2591\">23</sup> חד בהון כו' הכל הוא בבחי' הא\"ס. אך זהו הטעם עצמו שמכריח לומר שא\"א",[["2573","5","<b>ועבדום וענו אותם</b>: לך טו, יג."],["2574","6","<b>וימררו את חייהם</b>: שמות א, יד."],["2575","7","<b>וז' מצות ב\"נ</b>: ראה סנהדרין נו, סע\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670591\" data-slug=\"torat-chaim\" data-id=\"2300670591\">תו\"ח נח עז, א</a> הערה 14."],["2576","8","<b>וז' מצות ב\"נ שמרו</b>: ראה מפרשי ההגדה שבולי הלקט. זבח פסח. (עה\"פ תבוא כו, ה ויהי שם לגוי) שלא שנו. . ודתם. תדא\"ר שבהערה הבאה."],["2577","9","<b>וגם מצות מילה</b>: ראה תדא\"ר פכ\"ג. מאמרי אדה\"א במדבר ח\"ב ע' תשסה."],["2578","10","<b>ושבת</b>: ראה גם שמו\"ר פ\"א, כח. פ\"ה, יח. וש\"נ."],["2579","11","<b>וכה\"ג</b>: ראה רמב\"ם הל' מלכים פ\"ט, סה\"א."],["2580","12","<b>אלקים. . שררה</b>: ראה רש\"י בראשית ו, ב. וישלח לה, ז. שמות ד, טז. וארא עה\"פ כאן. לקמן עה, ב. פ' בא קיב, ד. תצוה שכז, ד. ויקהל שצו, ג. מאמרי אדה\"א בראשית ע' קצו. וש\"נ. נ\"ך ע' קנג. שה\"א ל, א. ש\"א לו, א."],["2581","13","<b>עד האלקי' יבא</b>: משפטים כב, ח."],["2582","14","<b>האלקי'. . שם זה גם ברבים</b>: רש\"י וירא כ, יג. וישלח לה, ז."],["2583","15","<b>כי יש אלקי' שופטי'</b>: תהלים נח, יב [ושם: אך יש]."],["2584","16","<b>כי אלקים קדושים הוא</b>: יהושע כד, יט."],["2585","17","<b>כי הוי' הוא האלקי'</b>: ואתחנן ד, לה. לט."],["2586","18","<b>כולא חד</b>: ראה זהר בהקדמה יב, א. תרומה קסא, ב. מאמרי אדה\"א דברים ח\"א ע' קעה [ובהנסמן בריש המאמר שם]. שה\"א יב, ב ובהערה 25. לקמן עג, ב. פ' בשלח קנא, א. יתרו רנח, ג. תרומה דש, ד. תצוה שכט, ג. שנא, ג. ויקהל תה, א."],["2587","19","<b>ביום עשות</b>: בראשית ב, ד."],["2588","20","<b>גדול ה'</b>: תהלים מח, ב [וכן צ\"ל במאמרי אדה\"ז על פרשיות התורה כאן]. ראה גם לקמן פ' בשלח רלג, ד."],["2589","21","<b>אימתי גדול</b>: ראה זהר פקודי רלה, א. ויקרא ה, א. ז\"ח תשא מד, א. חוקת נא, רע\"ד. מאמרי אדה\"א נ\"ך ע' פ. וש\"נ."],["2590","22","<b>גדול. . אין חקר</b>: תהלים קמה, ג."],["2591","23","<b>דאיהו וחיוהי</b>: ת\"ז בהקדמה ג, ב."]]],[2300540133,"שיומשך למטה באבי\"ע גם מבחי' גילוי אור התפשטו' דא\"ס, רק בחי' הארה דהארה מעצמו' דאור א\"ס כמ\"ש באורך נראה אור<sup data-n=\"2592\">24</sup> כו', וזהו שנק' זיו השכינה<sup data-n=\"2593\">25</sup>, דהשכינה עצמה היא בבחי' ומדרג' דאוא\"ס ג\"כ מאחר שהוא בחי' המל'<sup data-n=\"2594\">26</sup> שהיא אחת ממדותיו ית' דאיהו וחיוהי חד ממש הכל בבחי' א\"ס כנ\"ל דע\"ז נא' לגדולתו אין חקר כלל כנ\"ל וד\"ל. ובחי' זיו השכינה זה הוא בחי' שם אלקים שנק' מגן ונרתק לשם הוי' כמ\"ש כי שמש ומגן<sup data-n=\"2595\">27</sup> הוי' אלקים כידוע שזהו שם אלקי' המצמצם ומסתיר לשם הוי', כי כדי שיוכל לבא האור האלקי להיות ממנו התהוות ברואי' בע\"ג מאין ליש ממש, הוצרך לשם אלקים להיותו בא בבחי' הארה דהארה בבקיעת האור ע\"י מסך כידוע בע\"ח שהמל' בוקע המסך<sup data-n=\"2596\">28</sup> שמפסיק בין אצי' לבריאה ונעשה מקור וכתר <span data-k=\"pg\">176</span> ּ לבריאה כו' וד\"ל. והנה על בחי' הארה דהארה זו שנמשך למטה שנק' זיו והוד בעלמא כמו הודו על ארץ<sup data-n=\"2597\">29</sup> כו', הוא שאמר מה רבו מעשיך ה'<sup data-n=\"2598\">30</sup> כו', שבא בבחי' ריבוי והתחלקות מאד, דהיינו מפני שבחי' אור וזיו זה הוא שנתחלק לרבבות מדרגות שונות להיות מקור לכל ריבוי רבבות המלאכים שהן במדרגות חלוקות ושונות זמ\"ז כמו אלף אלפי' ישמשוני'<sup data-n=\"2599\">31</sup> כו'. וכאו\"א יש לו כח מיוחד מאור וזיו האלקי הנ\"ל, עד שגם<sup data-n=\"2600\">32</sup> למטה מטה יותר בא בחי' הריבוי וההתחלקות לאין שיעור כמו בכל פרטי חלקי דצח\"מ וארמ\"ע<sup data-n=\"2601\">33</sup> בגשמיות שע\"ז א' מה רבו מעשיך כו', מעשיך ממש בא בריבוי גדול ביותר. ומבחי' ריבוי ההתחלקות כ\"כ במיני דצח\"מ וארמ\"ע ממילא יובן ההתחלקות וריבוי הגדול בשרש הדצח\"מ וארמ\"ע ברוחניות, מאחר שהשפע הולך מבחי' הרוחני' אל הגשמיות כמא' אין לך עשב למטה<sup data-n=\"2602\">34</sup> שאין לו מזל רוחני המכה ואו' לו גדל כו'. ואנו רואים שגם במין זה דעשב יש רבבות מינים<sup data-n=\"2603\">35</sup> שונים בצמח השדה, כמו\"כ ודאי בהכרח יש ברוחניות של העשבים במזל העליון ג\"כ אותן הרבבות מדרגות שמהן באו בגשמיות, וכן בכל פרטי הצומח, וגם בכל פרטי חלקי החי והמדבר שכולן מקבלי' מן המזלות, וכן פרטי יסודות גשמיי' דארמ\"ע מקבלים מבחי' הרוחניות שלהם במזלות כידוע במ\"ש אני אענה את השמים<sup data-n=\"2604\">36</sup> והם יענו את הארץ, עד שמזל מחכים ומזל מעשיר<sup data-n=\"2605\">37</sup>",[["2592","24","<b>באורך נראה אור</b>: תהלים לו, י. ראה מאמרי אדה\"א דברים ח\"א ע' קעח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680065\" data-slug=\"torat-chaim\" data-id=\"2300680065\">תו\"ח וישב רה, א</a> הערה 16. לקמן פ' תרומה דש, ד. ויקהל שפח, סע\"ד ואילך. תה, א."],["2593","25","<b>זיו השכינה</b>: ברכות יז, א."],["2594","26","<b>דהשכינה. . בחי' מל'</b>: נסמן לעיל א, ד."],["2595","27","<b>כי שמש ומגן</b>: נסמן לקמן סג, ג."],["2596","28","<b>שהמל' בוקע המסך</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ד. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["2597","29","<b>הודו על ארץ</b>: תהלים קמח, יג."],["2598","30","<b>מה רבו מעשיך ה'</b>: תהלים קד, כד."],["2599","31","<b>אלף אלפי' ישמשוני'</b>: דניאל ז, י."],["2600","32","<b>עד שגם</b>: ב: וכל שבא."],["2601","33","<b>וארמ\"ע</b>: נסמן לעיל פ' שמות ה, ד."],["2602","34","<b>אין לך עשב למטה</b>: באוה\"ת וארא כאן ע' ב'תתפג מציין: הובא בר\"ח פ\"ה משער האהבה והוא במ\"ר בראשי' פ\"י[, ו]. ראה מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. וע' תתעו ואילך. שה\"א נג, א."],["2603","35","<b>במין זה דעשב יש רבבות מינים</b>: ראה גם לקמן פ' יתרו ערה, ג. שע\"ת ע, א ובהערה 13."],["2604","36","<b>אני אענה את השמים</b>: הושע ב, כג [בהוספת תיבת ”אני\" — ראה לקמן פ' תרומה שח, סע\"ג ואילך. מאמרי אדה\"א ויקרא ח\"א ע' קנה. שמות ח\"א ע' קצו. הנחות תקע\"ז ע' רכב ובהנסמן בהנ\"ל]."],["2605","37","<b>שמזל מחכים ומזל מעשיר</b>: שבת קנו, א. וראה לקמן פ' בא קלב, ד."]]],[2300540170,"ומשפיל כו' שאם הורד מזלו למעלה יושפל למטה לפי שגם המזלות ברקיע מקבלים מחיצוני' דאופנים (כמ\"ש בע\"ח בסופו<sup data-n=\"2606\">38</sup> ). וזהו שאומרי' ומסדר את הכוכבי'<sup data-n=\"2607\">39</sup> במשמרותיהם ברקיע כרצונו כו', ומשפיל ומרים למזלות כרצונו (וכמ\"ש וכמצביי' עביד בחיל שמיא<sup data-n=\"2608\">40</sup> כו') כמ\"ש כל אשר חפץ ה'<sup data-n=\"2609\">41</sup> עשה בשמים כו', וכידוע דכל מה שנמשך מאופני' במזלות אינו רק בחי' החיצוני' ופסולת ונק' שמרי האופנים כו' שנברר מפנימי' השפע האלקי שנמשך לאופנים וחיות כו' (ע\"י המלאכים שנק' קרביי' ואצטומכא כמ\"ש וכל קרבי<sup data-n=\"2610\">42</sup> כו', שמבררי' השפע העליונה האלקי' שנמשך מבחי' מל' דאצי' בבי\"ע ומבדילי' הפנימי' מן החיצוני' והוא אשר נמשך למזלות כמ\"ש במ\"א).\n<b>וזהו</b> שארז\"ל במדרש<sup data-n=\"2611\">43</sup> ע\"פ אף ידי יסדה ארץ<sup data-n=\"2612\">44</sup> וימיני טפחה שמים נטה הקב\"ה יד ימינו וברא השמים ונטה יד שמאלו וברא הארץ כו', שמרמז בזה לבחי' עולמות העליוני' הרוחניי' שנק' שמים בכלל כמו מלאכי' ונשמות דבריא' ויצי' כו' שע\"ז אמר אני אענה את השמים שנמשך מבחי' ימין דחסד עליון להשפיע לשמים עליונים, וגם שם מתחלק האור ושפע לכל מלאך ונשמה בפ\"ע וכמו ריבוי ההיכלות שיש בג\"ע דבריאה ויצי', וכמו לע\"ל שא' שעתיד ה' להנחיל לכל צדיק ש\"י עולמות<sup data-n=\"2613\">45</sup> כו', וז\"ש ימיני טפחה שמים. ומ\"ש ידי יסדה ארץ זהו שנטה שמאלו דוקא וברא את הארץ שהוא להמשיך מרוחניות לגשמיות להיות ריבוי התחלקות השפע במזלות, להיות השפע בא בהגשמה דד\"י ארמ\"ע ודצח\"מ שזהו מבחי' שמאל דוחה<sup data-n=\"2614\">46</sup> לדחות השפע למטה שתבא בגשמיות יותר כו', וזהו והם יענו את הארץ עד שאין לך עשב כו', וזהו שנטה שמאלו דוקא וברא את הארץ וכל אשר בה (ולמעלה היינו בחי' עלמא דאתכסיי' ועלמא דאתגלייא<sup data-n=\"2615\">47</sup> בכללות, ונחלקו לפרטי' רבים בין בהעלם בין בגילוי כמו ריבוי התחלקות צירופי האותיות דמח' שבאי' ג\"כ בדיבור בהתחלקות צרופי' רבים לאין שיעור וכמ\"ש בס\"י ה' אבנים<sup data-n=\"2616\">48</sup> בונות ק\"ך בתים מכאן ואילך כו') (ומ\"ש בראשית ברא אלקי' <span data-k=\"pg\">פח</span> ּ בחוכמתא<sup data-n=\"2617\">49</sup> את השמים ואת הארץ לרוחניות וגשמיות בשוה וכמ\"ש אתה עשית את השמים<sup data-n=\"2618\">50</sup> כו', משום דהפרש זה בין עולמות הרוחניי' לעולמות הגשמיי' היינו ביריד' השפע אלקי בנבראי' מאין ליש כמ\"ש מה רבו מעשיך ה' כולם בחכ' עשית בח\"ת שבדיבור, אבל בח\"ע שבראש שנק' בראשית שם ברא",[["2606","38","<b>המזלות. . בע\"ח בסופו</b>: ראה גם פרדס (שער אבי\"ע) שט\"ז פ\"ח. מאמרי אדה\"א דברים ח\"ב ע' תפד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670093\" data-slug=\"torat-chaim\" data-id=\"2300670093\">תו\"ח נח נט, ד</a> הערה 57. לקמן פ' בשלח קסה, ב הערה 70."],["2607","39","<b>ומסדר את הכוכבי'</b>: ברכות ק\"ש (ערבית)."],["2608","40","<b>וכמצביי' עביד בחיל שמיא</b>: דניאל ד, לב."],["2609","41","<b>כל אשר חפץ ה'</b>: תהלים קלה, ו."],["2610","42","<b>המלאכים. . וכל קרבי</b>: תהלים קג, א. ראה זהר לך פז, סע\"א. (רע\"מ) פינחס רלד, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תרסח. בראשית ע' קיג. הנחות תקע\"ז ע' שלו ובהנסמן בהנ\"ל."],["2611","43","<b>במדרש</b>: ראה פדר\"א פי\"ח. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א כאן נו, ב</a>."],["2612","44","<b>אף ידי יסדה ארץ</b>: ישעי' מח, יג."],["2613","45","<b>שעתיד. . ש\"י עולמות</b>: עוקצי' בסופה. וראה ג\"כ אוה\"ת כאן ע' ב'תתפג."],["2614","46","<b>שמאל דוחה</b>: סוטה מז, א."],["2615","47","<b>עלמא דאתכסיי' ועלמא דאתגלייא</b>: נסמן לעיל פ' שמות לג, א."],["2616","48","<b>בס\"י ה' אבנים</b>: פ\"ד מי\"ב [הלשון שמובא בפנים הוא במהדורת מנטובא שכ\"ב — צילום ירושלים תשכ\"ב — פ\"ד, מ\"ד בדילוג]."],["2617","49","<b>בראשית. . בחוכמתא</b>: בראשית א, א. וראה תרגום ירושלמי שם."],["2618","50","<b>אתה עשית את השמים</b>: נחמי' ט, ו."]]],[2300540207,"אלקים שמים וארץ כא' וכמ\"ד שמים וארץ<sup data-n=\"2619\">51</sup> כא' [נבראו] מטעם זה שכולם שוין שם<sup data-n=\"2620\">52</sup> משפיע ומקבל) (אבל מ\"ד שמים נבראו תחלה היינו כנ\"ל דרוחניות העולמות קדמו תחלה לארץ הגשמי' ומ\"ד ארץ<sup data-n=\"2621\">53</sup> נברא תחלה דסוף מעשה<sup data-n=\"2622\">54</sup> כו' כמ\"ש ביום עשות ה' אלקים ארץ ושמים זהו כמ\"ש ה' בחכ' יסד ארץ<sup data-n=\"2623\">55</sup> כונן שמים בתבונה הרי החכ' שנק' ראשית יסד ארץ ושמים כונן בתבונה שלמטה מן החכ', וז\"ש מה רבו מעשיך בארץ כולם בחכמה עשית שזה יותר עליון משמים בשרשו היפך כל הנ\"ל וכמ\"ש במ\"א).\n<b>והנה</b> לפעמים א' מה רבו מעשיך כו' ולפעמים א' מה גדלו מעשיך<sup data-n=\"2624\">56</sup> ה' מאד עמקו מחשבותיך כו', והענין הוא דזהו ההפרש בין עולמות העליונים הרוחניי' הנ\"ל שע\"ז א' מה גדלו מעשיך כו', שהן גדולים במעלה להיותם בבחי' ביטול היש לאין האלקי בתמידות ועולים בעליות רבות כמו ילכו מחיל<sup data-n=\"2625\">57</sup> כו' כמו בכל חדש ושבת כו' שע\"ז א' מזמור שיר ליום השבת כו' עד כי שמחתני<sup data-n=\"2626\">58</sup> ה' בפעליך כו' מה גדלו כו', וזהו מאד עמקו מחשבותיך שהן עולי' בבחי' עומק דמח' סתימאה שהוא ח\"ע שבראש כו'. אבל מ\"ש מה רבו מעשיך היינו בהתחלקות דצ\"ח גשמיי', דאע\"פ שכולם בחכמה עשית<sup data-n=\"2627\">59</sup>, מ\"מ הן עשי' גשמיות ונמשכו מבחי' ח\"ת שבצרופי אותיות הדבור שנתגלגלו למטה מטה ביותר וכמ\"ש לכו חזו מפעלות אלקי'<sup data-n=\"2628\">60</sup> לשון רבים שנתרבו הצרופי' דאלקי' לפעול ריבוי פעולת המשכות העולמות התחתוני' הגשמיי', וז\"ש אשר שם שמות בארץ<sup data-n=\"2629\">61</sup> דוקא א\"ת שמות אלא שמות כו', כי באמת אין ערוך כלל וכלל לעולמות התחתוני' הגשמיי' כשפע המזלות מרוחני' לגשמי' לגבי העולמות הרוחניי' ממש כמלאכים ונשמות דבריאה ויצי' בגעה\"ע וגעה\"ת וכה\"ג וד\"ל.\n<b>ויובן</b> זה ההפרש גם בבחי' התענוג האלקי שיש בכל עולם ועולם בבחי' הרוחניות שיש בזה ריבוי התחלקות מדרגות מאד, כמו שאנו רואים למטה בתענוגי עוה\"ז הגשמיי' שנפלו בשבה\"כ מבחי' פסולת התענוג הרוחני שבג\"ע הארץ דעשי' בד' נהרות<sup data-n=\"2630\">62</sup> שיוצאי' חוץ לג\"ע כידוע. דהנה אנו רואים במציאות תענוגי הגשמיי' שיש בהם כמה מיני מדרגות שונות גם בכל מין ומין, כמו בחלק הדומם יש תענוגי' בכסף וזהב ומיני",[["2619","51","<b>וכמ\"ד שמים וארץ</b>: חגיגה יב, א."],["2620","52","<b>שכולם שוין שם</b>: ב: ששוין. ה: ששוין שם."],["2621","53","<b>מ\"ד שמים. . ומ\"ד ארץ</b>: חגיגה שם."],["2622","54","<b>דסוף מעשה</b>: פיוט לכה דודי."],["2623","55","<b>ה' בחכ' יסד ארץ</b>: משלי ג, יט."],["2624","56","<b>מה גדלו מעשיך</b>: תהלים צב, ו."],["2625","57","<b>ילכו מחיל</b>: תהלים פד, ח."],["2626","58","<b>מזמור שיר. . כי שמחתני</b>: תהלים צב, א. ה."],["2627","59","<b>שכולם בחכמה עשית</b>: המשך הכתוב מה רבו (תהלים קד, כד)."],["2628","60","<b>לכו חזו מפעלות אלקי'</b>: תהלים מו, ט. וראה במנחת שי שם. זהר בראשית נח, ב ובמפרשים שם. לקמן עג, ב. עה, ג. עט, א. פ' בא קיג, א. בשלח רלג, ד. יתרו רנג, א. תצוה שכז, א. פקודי תמג, ב. תנג, ג. מאמרי אדה\"א נ\"ך ע' תעב. שה\"א מז, ב ובהערה 21."],["2629","61","<b>אשר שם שמות בארץ</b>: המשך הכתוב לכו חזו. ברכות ז, ב. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשצב. וש\"נ. נ\"ך ע' תעב."],["2630","62","<b>בתענוגי עוה\"ז. . בד' נהרות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670222\" data-slug=\"torat-chaim\" data-id=\"2300670222\">תו\"ח לך צו, ב</a> ובהנסמן במ\"מ לשם."]]],[2300540239,"מתכות ואבנים טובות ומרגליות וכה\"ג, שיש בזה מינים רבים מחולקים באופן התענוג גם בעפר הארץ עצמה בטוב מזיג' היסודות שבה בכל מקום לפי מה שהוא כו', וכן בחלק הצומח יש כמה מיני פירות מחולקי' בטעמיהן באופן התענוג שבהם זה טעמו כך וזה טעמו כך כי ריבוי המינים בפירות הארץ וכל אשר בה בתבואה וכל צמח פרי הארץ יש רבוא רבבות מדריגות מינים שונים זמ\"ז כו', וכן יש רבבות מדרגו' בטעמים של המאכלים דחי כבקר וצאן ועופות וכן בדגים וחלב ודבש, וכה\"ג בתענוגי בנ\"א בבחי' מדבר בכמה מיני תענוגי' שונים כתאות המאכל ותאות המשגל ותאות הכבוד וגדולה ולהשיג הון כו' וניצוח והתפארו' או טיול ומנוחה או למלחמה ורציחה או להיפוך לחסד ורחמים כו', בכולם יש תענוג מיוחד בפ\"ע והכל המה תענוגי' גשמיי' מאד שנפל בשבה\"כ (גם <span data-k=\"pg\">178</span> ּ התענוג שבשכל ותענוג הכבוד שהוא רוחני בערך תענוגי' הגשמיי', גם הוא גשמי' יחשב בתענוג העליון שבג\"ע דעשי'), שהן בחי' פסולת דפסולת שנופל מחיצוני' התענוג שבג\"ע דעשי' ששרשו בעונג העליון דמל' דאצי' בגעה\"ע שנק' זיו השכינה עד שרש ומקור כל התענוגי' שבאצי' בבחי' פנימי' דע\"י כו'. ואמנם הנה עכ\"ז הגם שתענוגי' הגשמי' הן בשפלות המדרגה ביותר כמו בטעמי' דצומח הפירות וטעמי המאכלים דבשר ודגים וכה\"ג בתענוגי בנ\"א הנ\"ל, מ\"מ מאחר שאנו רואים שבתענוגי' הגשמי' יש בחי' התחלקות רב כ\"כ לרבבות אלפי' מדרגות באופני' שונים, מוכרח לומר שגם בשרש שרשם למעלה עד מקור הראשון דתענוג העליון האלקי בנשמות ומלאכי' דגעה\"ע וגעה\"ת יש רבבות מדרגות בהתחלקות וריבוי כאלה, בכמה מיני מדריגות חלוקות ושונים זמ\"ז, עד שיש כמה רבבות מדרגות בבחי' העונג העליון לנשמות בעוה\"ב כמו שיהי' ש\"י עולמות לכל צדיק דהיינו ש\"י מדרגות דעונג העליון כו' וד\"ל. והנה בחי' ריבוי ההתחלקות מדרגות בעונג העליון שבבריאה ויצי' הוא שנמשך מריבוי הצירופי' דאותיות מבחי' אלקי' דוקא כנ\"ל, שע\"י שם אלקים הוא המתצמצם ומתחלק לריבוי חלקים מאד, דק\"ך צירופי' דאלקי'<sup data-n=\"2631\">63</sup> מתחלקי' לאין שיעור כמ\"ש בס\"י ה' אבנים כו'. וזהו שאלקים ל' רבים כו' כמו כי אלקים קדושים הוא כו', לפי שמתחלק לרבבות מדרגות בבחי' המשכת עונג העליון לנשמות ומלאכים בכל א' לפי מה שהוא, וזהו ריבוי מדרגות בשירה שהמלאכים או' בכל יום<sup data-n=\"2632\">*64</sup> כו', ועליהם א' מה גדלו מעשיך ה' כנ\"ל, ו[ב]יריד' החיצוני' דחיצוניו' מהם למטה עד המזלו' שמשפיעים מרוחניות לגשמיות ממש כתענוגי דצח\"מ גשמיי' הנ\"ל ע\"ז א' מה רבו מעשיך כנ\"ל ואין לתחתונים ערך כלל לעליוני' כי לא נמשך לתחתונים רק מן בחי' הפסולת כנ\"ל וד\"ל.",[["2631","63","<b>דק\"ך צירופי' דאלקי'</b>: נסמן לעיל כ, א."],["2632","*64","<b>בשירה שהמלאכים. . יום</b>: ראה גם לקמן עד, א. וש\"נ. פ' בא צג, ד. וש\"נ. סידור שער החנוכה רעח, ג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370169\" data-slug=\"torah-or\" data-id=\"3901370169\">תו\"א מקץ לז, א</a>."]]],[2300540270,"<b>ובכ\"ז</b> יובן ענין הנ\"ל במא' אימתי גדול כשהוא בעיר אלקינו דוקא והלא לגדולתו אין חקר כלל גם לא בעיר אלקינו כו', הענין יובן ע\"פ כל הנ\"ל דבאמת מ\"ש לגדולתו אין חקר היינו דוקא בבחי' התפשטו' דאוא\"ס עצמו שנק' גדולתו העצמי' שאין לה חקר כלל, ואע\"פ שגדול ה' ומהולל מאד בלי גבול זהו רק בבחי' הארה דהארה שמאיר מאוא\"ס בעולמות העליוני' ועולמות התחתונים כנ\"ל שהן ריבוי צירופי האותיות שנמשך מבחי' מל' דאצי' בבי\"ע לנשמות ומלאכי' עד סוף עולם העשי'. וזהו גדול הוי' ומהולל מאד בלי גבול כמו שאו' משובח ומפואר בלשון חסידיו ועבדיו שהן נשמות ומלאכים<sup data-n=\"2633\">64</sup> דבי\"ע, וע\"ז מסיים משובח ומפואר עדי עד כו' היינו עד שמו הגדול מל' דא\"ס<sup data-n=\"2634\">*65</sup> בבחי' גדולתו העצמי' הנ\"ל שהוא בבחי' א\"ס ממש. וזהו הוי' אחד ושמו הגדול אחד<sup data-n=\"2635\">65</sup> ממש באח\"פ האמיתי שאינו מתחלק כלל לרבבות צרופי' דאותיות בהמשכות רבות כו', ונק' נורא תהלות<sup data-n=\"2636\">66</sup> ושם א' לו דומי' תהלה<sup data-n=\"2637\">67</sup> כו', להיותו למעלה עדיין מבחי' הקו\"ח מקור כל ההשתל' דאבי\"ע כידוע, וז\"ש כי עמך מקור חיים שהוא הקו\"ח, עמך טפל ובטל כו' ונק' חיי החיים<sup data-n=\"2638\">68</sup> כו' וד\"ל. אך הנה עכ\"ז א' תחלה גדול ה' ומהולל מאד <span data-k=\"pg\">פט</span> ּ ואח\"כ א' לגדולתו אין חקר שזהו כמו דבר והיפוכו לכאורה שגדול ה' כו' זהו בבחי' התפשטו' הארה דהארה בבחי' זיו השכינה דמל' בבי\"ע כנ\"ל שאין לזה ערך לגדולתו העצמי' שהיא ברוממות העצמו' ממש כו', ומוכרח לומר שגם בחי' התפשטו' הארה דהארה זו הרי נק' מהולל מאד בלי גבול<sup data-n=\"2639\">69</sup> כלל וכמו שא' משובח ומפואר עדי עד שמו הגדול שזהו גדולתו העצמי' מבחי' מל' דא\"ס עצמו כנ\"ל, וא\"כ הרי מגיע השירות והתשבחו' דמלאכים ונשמות דבריאה ויצי' לבחי' שמו הגדול ממש והיינו משום דנעוץ תחב\"ס<sup data-n=\"2640\">70</sup> וסב\"ת כו', ולכך א' גדול ה' ולגדולתו אין חקר דהיינו הך כמ\"ש אני ראשון מל' דא\"ס ואני אחרון<sup data-n=\"2641\">71</sup> מל' דאצי' בבי\"ע כו', וזהו יש\"ר מברך לעלם<sup data-n=\"2642\">72</sup> כו' וד\"ל. אך הנה זהו דוקא בבחי' המשכה פנימי' מפנימי' ההארה דמל' דא\"ס בבחי' המשכות העונג העליון הפשוט שבעצמו' א\"ס שנק' שעשועי המלך בעצמו<sup data-n=\"2643\">73</sup> כו', שנמשך בקו\"ח העובר לכל האצי' עד מל' דאצי' בג\"ע העליון לנשמות דבריא' שנהנין מזיו השכינה שהוא בחי' העונג העליון דפנימי' ע\"י שנמשך בו מפנימי' דמל' דא\"ס בכלל. וזהו שא' גדול ה' ומהולל מאד בעיר אלקינו דוקא והוא בירושלים של מעלה שבעולם הבריאה כמו נשבע ה' כו' ולא אבא בעיר<sup data-n=\"2644\">74</sup> כו' כמ\"ש בזהר, והוא שנק' עיר אלקינו דוקא שבא מבחי' צרופי אותיות הפנימיות דעולם התענוג העצמי שלמעלה להיות בבחי' בנין היכלות ובתים כמו ה' אבנים בונות ק\"ך בתים כו', וכמו היכלות הפנימי' דג\"ע וכה\"ג במ\"ש שעתיד להנחיל",[["2633","64","<b>משובח ומפואר. . נשמות ומלאכים</b>: ברכת ברוך שאמר. ראה פע\"ח (שער הזמירות) ש\"ז, פ\"ד. לקמן פ' יתרו רנב, ד. פקודי תנז, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670027\" data-slug=\"torat-chaim\" data-id=\"2300670027\">תו\"ח בראשית לג, ד</a> ובהערה 13. ש\"א ח, ב. לו, ב."],["2634","*65","<b>שמו הגדול מל' דא\"ס</b>: נסמן לעיל פ' שמות ה, ג."],["2635","65","<b>הוי' אחד ושמו. . אחד</b>: זכרי' יד, ט."],["2636","66","<b>נורא תהלות</b>: בשלח טו, יא."],["2637","67","<b>לו דומי' תהלה</b>: תהלים סה, ב [ושם: לך — ראה לקמן פ' בשלח קסז, ג. פקודי תנז, א]."],["2638","68","<b>חיי החיים</b>: יומא עא, א."],["2639","69","<b>מאד </b>[ב: ניתוסף: מאד]<b> בלי גבול</b>: ראה אגה\"ק סי\"ז (קכו, א). תו\"ח ח\"ש קלא, ג ובהערה 30. שע\"ת קלה, ד ובהערה 30. ש\"א לג, א. לקמן סה, ד. עט, ג. פ' בשלח קסח, ב. רח, א. רכ, ב. רמא, ד. יתרו רסו, ג."],["2640","70","<b>דנעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["2641","71","<b>אני ראשון. . ואני אחרון</b>: ישעי' מד, ז. ראה גם לקמן פ' ויקהל תיג, ג. שעה\"י קמב, ב ובהערה 31."],["2642","72","<b>יש\"ר מברך לעלם</b>: נוסח הקדיש."],["2643","73","<b>שעשועי המלך בעצמו</b>: נסמן לקמן צב, ד."],["2644","74","<b>נשבע. . ולא אבא בעיר</b>: הושע יא, ט. ראה זהר ואתחנן רסב, ב. ויקרא טו, ב. תענית ה, א."]]],[2300540299,"לכל צדיק ש\"י עולמות כו', וכמו ת' עלמין דכסופין<sup data-n=\"2645\">75</sup> דנהרי לצדיקייא כו'. וע\"ז א' מה גדלו מעשיך ה' שהן עולמות העליוני' דבריא' ויצי' שהן עולי' למעלה בבחי' אור התענוג העליון עד שמגיע לבחי' גדולתו העצמי' בשעשועי המלך בעצמו ממש, וכמו העוה\"ב שנק' עדן כו'. ואע\"פ שאין זה רק בחי' התפשטו' מגדולתו העצמי' ע\"ז א' גדול ה' ומהולל מאד בתענוג של הנשמות דוקא בג\"ע דקוב\"ה אתא לאשתעשע<sup data-n=\"2646\">76</sup> עם הנשמו' הצדיקי' בג\"ע כו', ואימתי גדול כשהוא בעיר אלקינו בירושלים ש\"מ שנק' הר קדשו שם ניכר גדולתו העצמי' שבעצמו' א\"ס ממש מטעם הנ\"ל דנתחב\"ס וסוב\"ת. ואמנם זהו בבחי' הפנימי' דוקא ומשם נמשך בחי' החיצוני' לג\"ע הארץ ומשם נמשך הפסולת לע\"ש דנוגה דעשי' שהן ריבוי המשכות תענוגי עוה\"ז הנ\"ל שע\"ז א' מה רבו מעשיך כו' כנ\"ל (וע\"כ כשראה ר\"ע<sup data-n=\"2647\">77</sup> כרך גדול של רומי מלא תענוגי עוה\"ז שחק וא' אם לעוברי רצונו כך כו' כמ\"ש במ\"א וד\"ל).\n<b>ובכ\"ז</b> יובן מ\"ש כאן וידבר אלקים אל משה אני הוי' כו', דהנה כאשר יתבונן האדם היטב בבחי' ריבוי ההתחלקו' בצירופי' דאותיות ע\"י שם אלקי' שהוא ל' רבים מטעם זה כנ\"ל, בין בהשפעה הפנימי' מעולם התענוג הפשוט דאור א\"ס בעולמות העליוני' לנשמות ומלאכים בג\"ע ועוה\"ב ברבוא רבבות מדריגות לאין שיעור כלל כמ\"ש גדול ה' כו' בעיר אלקינו כו', ובין בהשפעה החיצוני' לעולמות התחתוני' עם השפע' רבוי חלקי ד\"י ארמ\"ע ודצח\"מ דעשי' כנ\"ל, הרי יתפעל האדם מזה בבחי' היראה הגדולה ועצומה בביטול הישות וגסות לגמרי מכל וכל באימה ופחד כו'. לפי שמבחי' אלקי' נמשך היראה כמ\"ש סוף דבר<sup data-n=\"2648\">78</sup> כו' האלקי' ירא כו', ונק' ירא אלקי' כמו האלקי' אני ירא<sup data-n=\"2649\">79</sup> וכידוע, להיות כי ע\"י התבוננו' זאת באה בלב האדם בחי' ביטול במציאו' דיר\"ע מפני התפשטו' גדולתו ית' בעולמו' וד\"ל. <span data-k=\"pg\">180</span> ּ ואמנם הנה גם מסתעף מזה בחי' התפעלות האהבה והדביקות לימשך אחרי ה' בכל לב ונפש וכמ\"ש ואהבת את ה' אלקיך<sup data-n=\"2650\">80</sup> כו', להיות שמתבונן בגדולתו העצמי' ממש שלפני הקו\"ח כנ\"ל שהוא ית' מקורא דכולא<sup data-n=\"2651\">81</sup> והוא עיקרא ושרשא דכולהו עלמין<sup data-n=\"2652\">82</sup> גם לעוה\"ב (כמו שאו' אין זולתך לחיי העוה\"ב כו') וכולא קמי' כלא ממש חשיב<sup data-n=\"2653\">83</sup>, שהן בחי' אותיות לבד דאפי' העוה\"ב עצמו ביו\"ד נברא<sup data-n=\"2654\">84</sup> כו'. וזהו ואהבת את ה' אלקיך, פי' האהבה והדביקו' יהי' לשם הוי' אלקיך דוקא שהוא בחי' גדולתו העצמ[י]ת שאין לה",[["2645","75","<b>ת' עלמין דכסופין</b>: נסמן לעיל פ' שמות כה, ד."],["2646","76","<b>דקוב\"ה אתא לאשתעשע</b>: ראה זהר לך עז, א."],["2647","77","<b>כשראה ר\"ע</b>: מכות כד, ב. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שטז ואילך."],["2648","78","<b>סוף דבר</b>: קהלת יב, יג."],["2649","79","<b>האלקי' אני ירא</b>: מקץ מב, יח."],["2650","80","<b>ואהבת את ה' אלקיך</b>: ואתחנן ו, ה."],["2651","81","<b>מקורא דכולא</b>: זהר בראשית לג, א."],["2652","82","<b>עיקרא ושרשא דכולהו עלמין</b>: זהר בהקדמה יא, ב."],["2653","83","<b>וכולא קמי' כלא. . חשיב</b>: נסמן לעיל פ' שמות לח, א."],["2654","84","<b>העוה\"ב. . ביו\"ד נברא</b>: מנחות כט, ב."]]],[2300540325,"חקר כלל שנק' חיי החיים ולמעלה ממקור חיים דקו\"ח כנ\"ל, והיינו שבחי' ריבוי התפשטו' והתחלקות השפע דאוא\"ס שנמשך למטה ע\"י הקו\"ח בכל האבי\"ע כנ\"ל יהי' בבחי' ביטול בהוי' אחד בחי' אח\"פ הנ\"ל. ובזה מתחברי' ב' שמות דהוי' ואלקי' דהיינו ששם אלקי' הבא בהתחלקות וריבוי בכל העולמות יהי' מתייחד ומתחבר בשם הוי' דאוא\"ס עצמו כמו שהי' קודם הצמצום הראשון שהי' הוא ושמו בלבד<sup data-n=\"2655\">85</sup> כו', וזהו פי' הפשוט דשמע ישראל<sup data-n=\"2656\">86</sup> ה' אלקינו הוי' אחד ממש באח\"פ הנ\"ל וד\"ל.\n<b>וזהו</b> וידבר אלקים אל משה אני הוי', פי' וידבר אלקים זהו שם אלקים בצמצום הראשון שבא בבחי' התחלקות והתפשטו' גדולתו ית' בכל ההשתלשלו' דאבי\"ע, והוא שלגבי מדרג' משה שנק' איש האלקי'<sup data-n=\"2657\">87</sup> [ש]למעלה מבחי' אלקי', והיינו בשם הוי' שהוא עצמו' אא\"ס ממש ע\"כ א' לו אלקי' זה אני הוי' שמתייחד ומתחבר בשם הוי' בבחי' היחוד שם הוי' ואלקי', וע\"כ א' אני הוי' ממש דכולא חד ממש (דכמו שא' כי ה' הוא האלקי' שלמעלה משם הוי'<sup data-n=\"2658\">88</sup> כך בחי' אלקי' א' אני הוי' כו', דאין הפרש בין הוי' לאלקי' כלל משום דגם לאחר הריבוי והתחלקות הנ\"ל בבחי' אלקי' הכל מיוחד בעצמו' אוא\"ס שלפני הקו\"ח כו') (לפי שאין הצמצום הראשון מסתיר לפניו כלל וכמו שהי' קודם הצמצום הזה כך הוא גם אח\"כ בלי שינוי כלל וכמ\"ש אני הוי' לא שניתי<sup data-n=\"2659\">89</sup> כו' שהרי א' אנת ה[וא ד]מייחד לון<sup data-n=\"2660\">90</sup> כו' דאיהו וחיוהי חד<sup data-n=\"2661\">91</sup> ממש כו' כידוע). וזהו הוי' אחד ושמו האלקי' אחד באח\"פ כשם הוי' וממילא מובן שנתייחד שם הוי' בשם אלקי' מלמעלה למטה בלי הסתר והעלם כלל (כמו לע\"ל שיוציא חמה שם הוי' מנרתקה<sup data-n=\"2662\">92</sup> שם אלקים ונגלה כבוד הוי'<sup data-n=\"2663\">93</sup>, וכן יש מעין זה בכל שבת<sup data-n=\"2664\">94</sup> כידוע). והנה אחר שנתייחדו ב' שמות דהוי' ואלקי' אל משה (מצד התו\"מ שיותן ע\"י משה שזהו יחוד הפנימי יותר כמשי\"ת במ\"ש ושמי הוי' [דתו\"מ] לא נודעתי להם כו'), אז אמר וארא אל אברהם אל יצחק כו', פי' וארא קאי אדסמיך לי' שא' אני הוי' שהוא יחוד דהוי' ואלקים ואז נתגלה שם הוי' בשם אלקי' לאבות ג\"כ, להיות גילוי שם הוי' לאברהם וכמ\"ש בו וירא אליו הוי'<sup data-n=\"2665\">95</sup> כו' וכן ביצחק ויעקב, וכידוע שהאבות הן הן המרכבה<sup data-n=\"2666\">96</sup> דבחי' חג\"ת<sup data-n=\"2667\">97</sup> דאצי' הכלולי' בג' שמות דאל אלקי' הוי'<sup data-n=\"2668\">98</sup>, אל חסד דאברהם ואלקי' גבו' דיצחק והוי' ת\"ת דיעקב בריח התיכון כו' והן ג' מדות דאוי\"ר ורחמים, אברהם הי' מרכבה בבחי' האהבה ודביקו' שזהו בחי' החסד<sup data-n=\"2669\">99</sup> ויצחק ביראה ופחד<sup data-n=\"2670\">100</sup> ויעקב ברחמים<sup data-n=\"2671\">101</sup> כו'. ואמנם",[["2655","85","<b>שהי' הוא ושמו בלבד</b>: נסמן לעיל נג, ב."],["2656","86","<b>דשמע ישראל</b>: ואתחנן ו, ד."],["2657","87","<b>משה. . איש האלקי'</b>: ברכה לג, א. תהלים צ, א."],["2658","88","<b>האלקי' שלמעלה משם הוי'</b>: ראה גם מאמרי אדה\"א בראשית ע' קעג. הנחות תקע\"ז ע' שלט ובהנסמן בהנ\"ל."],["2659","89","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["2660","90","<b>אנת ה</b> [וא ד]<b>מייחד לון</b>: ת\"ז בהקדמה (יז, א)."],["2661","91","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["2662","92","<b>שיוציא חמה. . מנרתקה</b>: נסמן לעיל פ' שמות לט, ב."],["2663","93","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["2664","94","<b>מעין זה בכל שבת</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' קעט. וש\"נ. לקמן פ' בשלח קמד, א הערה 21."],["2665","95","<b>וירא אליו הוי'</b>: וירא יח, א."],["2666","96","<b>שהאבות. . המרכבה</b>: נסמן לעיל ה, ג."],["2667","97","<b>שהאבות. . חג\"ת</b>: ראה מאו\"א מערכת אבות סכ\"ז. פרדס (שער הכינויים) שכ\"ב, פ\"ד. ע\"ח (שער אנ\"ך) שי\"ט, פ\"ג. סידור שער חגה\"ס רנז, ג. לקמן פ' משפטים רפ, ב. הנסמן בסמוך."],["2668","98","<b>דאל אלקי' הוי'</b>: תהלים נ, א. זהר אחרי סה, א. פרדס (שער השמות) ש\"כ, פ\"א."],["2669","99","<b>אברהם. . החסד</b>: נסמן לעיל נו, ג."],["2670","100","<b>ויצחק ביראה ופחד</b>: ראה פרדס (שער הכינויים) שכ\"ב, פ\"ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם."],["2671","101","<b>ויעקב ברחמים</b>: ראה זהר לך פז, ב. הנסמן במאמרי אדה\"א בראשית ע' קנו."]]],[2300540348,"כדי שיוכלו האבות להיות בחי' מרכבה לעצמו' אא\"ס שלמעלה מכל ההשתל' זהו שא' וארא אל אברהם <span data-k=\"pg\">צ</span> ּ שנתגלה שם הוי' גם לאברהם כו', אך דוקא אחר בחי' היחוד דשם הוי' בשם אלקי' כמ\"ש לו אני הוי', אני אלקי' הוא הוי' דהכל א' כנ\"ל, אז הוא שהי' יכול להתגלות באוי\"ר ורחמים דאבות שיהיו בבחי' מרכבה לגביו, אבל קודם היחוד דשם הוי' באלקי' לא הי' אור שם הוי' נגלה לאבות להיות לו בחי' מרכבה ממש רק בשם אלקי' לבד וד\"ל.\n<b>ומעתה</b> יש להבין מ\"ש וארא אל אברהם באל שדי דוקא (ולכאו' [הרי] אנו מוצאי' שרוב התגלו' אלקות לאבות הי' בשם אלקי' ובשם הוי', רק פ\"א בהיותו בן צ\"ט שנה א\"ל אני אל שדי<sup data-n=\"2672\">102</sup> התהלך כו'). אך הנה הענין הוא דבחי' שם זה דאל שדי הי' בחי' ממוצע לחבר ולקשר לגילוי אוא\"ס שבשם הוי' באלקי' בכל עת התגלות שם הוי' ואלקי' באבות, וז\"ש וארא אל אברהם כו' מה שארא ואתגלה בשם הוי' לאברהם כו' זה הי' ע\"י שם אל שדי דוקא שהוא בחי' הממוצע המחבר ומביא להיות בחי' התגלות שם הוי' באבות אברהם ויצחק כו' וד\"ל. וטעם הדבר למה הוצרך לבחי' ממוצע זה דשם אל שדי כו', הענין הוא לפי שבאמת הגם שהאבות הן המרכבה ממש בבחי' ביטול במציאו' ממש במס\"נ האמיתי עד שעלו ונכללו בהוי' אחד ממש והיו מרכבה לבחי' חג\"ת דאצי' כנ\"ל. עכ\"ז הרי היו נשמות שלהם בבחי' הבריאה מאין ליש בבחי' גבול<sup data-n=\"2673\">103</sup>, וידוע שאין ערך כלל לנברא עם הבורא ית' שהוא בלתי בעל גבול כלל (וגם שם אלקים המצמצם למטה ומפסיק בין אצי' לבריאה אינו מסתיר לפניו כלל כנ\"ל באלקי' דצמצום הראשון), וא\"כ האיך הי' אתעדל\"ת בהעלאת מ\"נ דעובדו' דאברהם איש החסד למטה בבחי' גבול מעורר אתעדל\"ע<sup data-n=\"2674\">104</sup> בבחי' שם הוי' שבחסד דעצמו' המאציל שהוא בבחי' א\"ס ממש. כי חסד ואהבה דאברהם אע\"פ שנק' אוהבי<sup data-n=\"2675\">105</sup> רחימא דמלכא<sup data-n=\"2676\">106</sup> כמ\"ש בזהר הרי מ\"מ היא גבול בנשמתו שהיא בחסד דמל' דבריאה<sup data-n=\"2677\">107</sup>, ואיך יהי' מזה החסד או האהבה המוגבלת אתעדל\"ע בחסד ואהבה בעצמו' המאציל שהוא בבחי' א\"ס ואיך נק' בשם מרכבה, וכן בפחד דיצחק ורחמים דיעקב כו'. אלא צ\"ל בהכרח שיש מי שמחבר ומקשר לאתעדל\"ע שבאצי' להיות מתעורר מאתעדל\"ת שבבחי' גבול כו', ולזה א' וארא אל אברהם בבחי' ממוצע לחבר ולהמשיך שם הוי' בחסד דאברהם וכן בפחד יצחק כו' להיות בבחי' מרכבה ממש, והוא בחי' אל שדי דהיינו בשם זה דא\"ל אל\"ף למ\"ד שהוא בבחי' החסד דוקא כמ\"ש חסד אל כל היום<sup data-n=\"2678\">108</sup>, ואל זה מלובש בשם שדי",[["2672","102","<b>אני אל שדי</b>: לך יז, א."],["2673","103","<b>נשמות שלהם. . גבול</b>: ראה גם בסמוך הערה 107. ולהעיר ממאמרי אדה\"ז על מארז\"ל ע' רצא."],["2674","104","<b>אתעדל\"ת. . אתעדל\"ע</b>: נסמן לעיל מא, א."],["2675","105","<b>דאברהם. . אוהבי</b>: ישעי' מא, ח."],["2676","106","<b>דאברהם. . רחימא דמלכא</b>: ראה זהר ואתחנן רסב, ב. מאמרי אדה\"א שמות ח\"ב ע' שמג. וש\"נ."],["2677","107","<b>בנשמתו שהיא בחסד דמל' דבריאה</b>: ראה לקמן פ' יתרו רנח, ד. אגה\"ק סט\"ו. מאמרי אדה\"ז תקס\"ה ח\"א ע' רעו (נוסחא שני'). פרשיות התורה ח\"ב ע' תשכט. שעה\"י קמה, ב. ש\"א עט, א ובהערה 4. מאמרי אדה\"א דברים ח\"ב ע' תרפג."],["2678","108","<b>חסד אל כל היום</b>: תהלים נב, ג."]]],[2300540371,"שהוא בבחי' הדין וצמצום<sup data-n=\"2679\">109</sup> דוקא כו', והוא כענין מארז\"ל בפי' שדי שא' לעולמו די<sup data-n=\"2680\">110</sup> כו' וד\"ל.\n<b>וביאור</b> הדברים הנה כתי' כי אמרתי עולם חסד יבנה<sup data-n=\"2681\">111</sup> הרי העולם נברא במדת החסד דוקא (כמו שא' חסד א' יברא<sup data-n=\"2682\">112</sup> כו'), אך א\"כ הול\"ל כי אמרתי חסד יבנה עולם ולא עולם חסד יבנה דמשמע שגוף הבנין הוא מבחי' החסד, וז\"ש חסד יבנה שיומשך החסד בבחי' בנין והיכל כו', וא\"כ מה זה שא' [כי אמרתי] עולם חסד יבנה כו'. אלא הענין הוא דבחי' עולם זה הוא אור האלקי העליון שמאיר מזיו ואור התענוג דעולם הא\"ס כנ\"ל לכל נשמה ונשמה להקיף אותה מכל צד כענין שיהי' לכל צדיק ש\"י עולמות, שיש עד\"ז כמה מיני רבבות עלמין וכמו ת' [אלף<sup data-n=\"2683\">113</sup> ] עלמין דכסופין כו'. וזה העולם יבנה בבחי' בנין והיכל כהיכל ובית גשמי המקיף לאדם למעלה ולמטה וכל צד כמו שבתי בבית ה'<sup data-n=\"2684\">114</sup> <span data-k=\"pg\">182</span> ּ לחזות בנועם ה' ולבקר בהיכלו כו' שמוקף מלמעלה ולמטה וד' רוחות בד' דפנות כו'. וזה ההיכל נבנה מבחי' אור החסד העליון דוקא, שזהו בחי' המקיף דרב חסד העליון שנק' אה\"ר שהוא בחי' אהבה העליונה דבחי' חסד דאצי' הנמשכת ובא' על נשמת האדם מלמעלה ומקפת אותה מראשה עד רגלה כו', וכמו וימינו תחבקני<sup data-n=\"2685\">115</sup> ימין מקרבת<sup data-n=\"2686\">116</sup> דאה\"ר העליונה תחבקני מכל צד כו', כמו\"כ אור חסד העליון נעשה ונמשך לנשמה האלקי' בבחי' בנין בית והיכל להסתירו בסתר עליון כו'. וזהו כמו שע\"י אהבה וחסד דאברהם שהי' מרכבה לבחי' חסד דאצי' שכלול בחסד דעצמו' המאציל, הרי נעשה אתעדל\"ע עי\"ז ונמשך התעוררו' אור האה\"ר העליונה שבעצמו' דא\"ס ממש כמו זכור רחמיך וחסדיך כי מעולם המה מעולם דא\"ס<sup data-n=\"2687\">117</sup>, וכן אשר נשבעת לאבותינו<sup data-n=\"2688\">118</sup> מימי קדם כמ\"ש במ\"א, והי' אור רב חסד זה מקיף לנשמת אברהם וכמ\"ש לו אנכי מגן לך<sup data-n=\"2689\">119</sup> ונק' מגן אברהם<sup data-n=\"2690\">120</sup> כידוע (וכמו\"כ זוכר חסדי אבות<sup data-n=\"2691\">121</sup> ומביא גואל דבחי' מקיף דרב חסד הנ\"ל לב\"ב למען שמו באה\"ר העליונה כמו שהי' עוזר ומושיע ומגן לאברהם ממש דזכות אבות לא תמו<sup data-n=\"2692\">122</sup> מטעם זה שהיו בבחי' מרכבה ממש למדות דחג\"ת שבא\"ס ממש שנק' ימי קדם כידוע). וזהו כי אמרתי ברצוני להיות עולם שהוא בחי' בית והיכל לנשמות, אז ע\"י חסד דוקא יבנה כל בית והיכל [ועולם], והוא בהתחלקו' החסד הזה לריבוי אותיות דוקא שנק' אבנים לבנות ריבוי בתים והיכלות כמו בנין בית בריבוי אבנים כמו ה' אבנים בונות כו' שזהו בחי' חסד אלקים לשון רבים כנ\"ל (כמשי\"ת).",[["2679","109","<b>שדי. . הדין וצמצום</b>: ראה ערכי הכינוים (לבעל סדה\"ד) מערכת שדי. אוה\"ת וארא ע' קנז ואילך."],["2680","110","<b>שדי שא' לעולמו די</b>: ראה חגיגה יב, א."],["2681","111","<b>כי. . חסד יבנה</b>: תהלים פט, ג."],["2682","112","<b>חסד א' יברא</b>: ב\"ר פ\"ח, ה."],["2683","113","<b>אלף</b>: ראה בהנסמן לעיל כה, ד."],["2684","114","<b>שבתי בבית ה'</b>: תהלים כז, ד [בדילוג]."],["2685","115","<b>וימינו תחבקני</b>: שה\"ש ב, ו. ח, ג."],["2686","116","<b>ימין מקרבת</b>: סוטה מז, א."],["2687","117","<b>זכור רחמיך. . מעולם דא\"ס</b>: תהלים כה, ו [בדילוג השם]. ראה גם לקמן פ' בשלח קעא, ב. יתרו רסה, ג. משפטים רצט, ג. מאמרי אדה\"א הנחות תקע\"ז ע' רפז. וש\"נ."],["2688","118","<b>אשר נשבעת לאבותינו</b>: מיכה ז, כ. ראה גם לעיל פ' שמות ד, ד."],["2689","119","<b>אנכי מגן לך</b>: לך טו, א."],["2690","120","<b>מגן אברהם</b>: נוסח תפלת העמידה. ב\"ר פל\"ט, יא. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך יב, א</a>."],["2691","121","<b>זוכר </b>[א: וזוכר]<b> חסדי אבות</b>: תפלת העמידה."],["2692","122","<b>דזכות אבות לא תמו</b>: שבת נה, א. ראה גם לקמן פ' בא קכז, ג. בשלח קצט, ד."]]],[2300540392,"<b>וזהו</b> וארא אל אברהם כו' באל שדי דוקא כנ\"ל, דהנה ע\"ד הנ\"ל בפי' כי אמרתי עולם כו', כך הי' באבות שהן המרכבה ממש כסוס לגבי רוכבו וכפני ארי' ופני שור<sup data-n=\"2693\">123</sup> למעלה במרכבה העליונה כו', וכמ\"ש ויעל אלקי' מעל אברהם<sup data-n=\"2694\">124</sup> דהיינו שהי' אור גילוי השכינה ממש על נשמת אברהם בדברו אתו וכשכלה לדבר אתו נעלה ונסתלק אלקי' מנשמת אברהם. ובודאי הי' גילוי זה באופן מדרג' דנשמת אברהם שהוא באופן דביקותו למעלה באלקים חיים [ב]אהבה ותשוק' בהתקשרות אמיתי' בתמידו' בלי הפסק וביטול כלל, וכמ\"ש ויסע אברם הלוך ונסוע הנגבה<sup data-n=\"2695\">125</sup> בסט' דדרום שהוא בחי' האהבה<sup data-n=\"2696\">126</sup> כפני ארי' להימין דארי' שאג באה\"ר<sup data-n=\"2697\">127</sup> כו', ופי' הלוך ונסוע מדרגא לדרגא<sup data-n=\"2698\">128</sup> בעילוי אחר עילוי בעוצם הדביקו' והפשט' כל העצמו' מכל וכל כו'. ולפ\"ע עליי' נשמת אברהם בחסד ואהבה האלקי' בדרום העליון, כך נמשך עלי' מלמעלה למטה על נשמתו ממש בבחי' גילוי אור מקיף דאה\"ר העליונה שבאה מעצמו' א\"ס שבמדת החסד ואהבה שבאצי' דאיהו וחיוהי חד ממש שהוא בבחי' א\"ס ממש כמו אהבתי אתכם אמר ה'<sup data-n=\"2699\">129</sup>, דאהבה זו בבחי' א\"ס ממש ולא אהבה גבולי' כאהבת אדם כי לא אדם הוא<sup data-n=\"2700\">130</sup> כו', ולכך אמר אה\"ע אהבתיך<sup data-n=\"2701\">131</sup> בנצחיות דא\"ס וכן אה\"ר כו'. ומטעם זה ודאי שאור אה\"ר העליונה דא\"ס ממש נעשה בבחי' מקיף לנשמת אברהם בדברו אתו מכל צד מלמעלה ומלמטה כמו היכל ובית כנ\"ל בפי' עולם חסד יבנה וד\"ל (וכמו וכבוד ה' יאספך<sup data-n=\"2702\">132</sup> שיש מלבוש לנשמה בג\"ע<sup data-n=\"2703\">133</sup> מזיו השכינה בבחי' מקיף להקיפה מכל צד כו' וגם לנשמה בגוף או' ואתה משמרה בקרבי<sup data-n=\"2704\">134</sup> כמ\"ש במ\"א) (וגם נמשך <span data-k=\"pg\">צא</span> ּ לבא למטה בלבוש גשמי להלביש ולהקיף על האדם לשמרו מכל רע ומכל קטרוג כמו ויסך אלוה בעדו<sup data-n=\"2705\">135</sup>, אלוה זה שם של חסד העליון, וכן הלא אתה שכת בעדו<sup data-n=\"2706\">136</sup> כו' וכה\"ג). אך הנה מאחר שבחי' אור אהבה או חסד עליון זה בא מעצמו' א\"ס שבאצי' להקיף לנשמה האלקי' בפרט בנשמת אברהם ולנש\"י בכלל כמ\"ש יסובבנהו<sup data-n=\"2707\">137</sup> יבוננהו יצרנהו כו', [א\"כ] לכאורה יפלא איך יוגבל האור הזה בשיעור ומדה להיות בהגבלה באופן בנין בית או היכל וסוכה לסכך ולהקיף רק לנשמה זאת, ולבא בהתחלקות פרטיות לכל נשמה ונשמה, שכל זה אין לו ערך לגבי עצמות אור האה\"ר העליונה כמו שהיא למעלה בעצמו', כי איך יוגבל מאור א\"ס המשכת אור הבא במדה אף שבא בבחי' מקיף לנשמה כו', וגם מה שבא בצמצומי' רבים בכמה רבבות אופנים שונים במקיפים",[["2693","123","<b>וכפני ארי' ופני שור</b>: יחזקאל א, י."],["2694","124","<b>ויעל אלקי' מעל אברהם</b>: לך יז, כב. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680072\" data-slug=\"torat-chaim\" data-id=\"2300680072\">תו\"ח ויחי רמג, ב</a>."],["2695","125","<b>ויסע אברם. . הנגבה</b>: לך יב, ט."],["2696","126","<b>דדרום. . האהבה</b>: זהר ויצא קנג, רע\"א."],["2697","127","<b>דארי' שאג באה\"ר</b>: ראה גם מאמרי אדה\"א דברים ח\"א ס\"ע שא ואילך. וש\"נ."],["2698","128","<b>הלוך ונסוע מדרגא לדרגא</b>: ראה זהר לך פ, א. פד, א."],["2699","129","<b>אהבתי אתכם אמר ה'</b>: מלאכי א, ב."],["2700","130","<b>כי לא אדם הוא</b>: שמואל-א טו, כט."],["2701","131","<b>אה\"ע אהבתיך</b>: ירמי' לא, ב [ושם: ואהבת — ראה לקמן עו, ד. פ' יתרו רסט, ב [ושם נדפס מגוכתי\"ק]. תצוה שלה, ד [ושם נדפס מגוכתי\"ק]. שנז, ג [כנ\"ל]. שסד, ב. שעב, א. פקודי תמה, ב [ושם נדפס מגוכתי\"ק]. תמח, ג [כנ\"ל]. תנח, ד. מאמרי אדה\"א ויקרא ח\"א ע' ח. וש\"נ. ש\"א ב, א. תו\"ח ויצא קעז, ד ובהערה 30]."],["2702","132","<b>וכבוד ה' יאספך</b>: ישעי' נח, ח [ושם: כבוד — ראה לקמן פ' משפטים שב, ב הערה 498]."],["2703","133","<b>מלבוש לנשמה בג\"ע</b>: ראה גם זהר נח סו, א. לעיל פ' שמות ז, ג. ח, א. כח, א. לקמן פ' בא צט, ב. בשלח קפא, ב. תשא שפד, ב. שעה\"י קמא, ב. שע\"ת נח, ג הערה 10. מאמרי אדה\"א ויקרא ח\"ב ע' תקנז וע' תשמו. קונטרסים ע' קח ואילך."],["2704","134","<b>ואתה משמרה בקרבי</b>: נסמן לעיל ז, ג."],["2705","135","<b>ויסך אלוה בעדו</b>: איוב ג, כג. ראה גם לקמן פ' בשלח רלו, ב. וש\"נ."],["2706","136","<b>הלא אתה שכת בעדו</b>: איוב א, י."],["2707","137","<b>יסובבנהו</b>: האזינו לב, י."]]],[2300540412,"שונים לכל נשמה (כענין ש\"י עולמות או ת' עלמין דכסופין כנ\"ל). ומוכרח לומר לפי שכל יכול הוא ויכול להמשיך דבר והיפוכו כא', והוא בחי' אור החסד שיבא במדה וגבול בהקפה כפי הצריך ולא יותר, וזהו שנק' אל שדי א\"ל הוא בחי' המקיף דחסד העליון הנ\"ל, ואמנם בא בצמצומי' במדה ושיעור כפי שיעור בנין היכל ועולם, וזהו שם שדי שא' לעולמו די, שמצמצם אור החסד שעולם יבנה כנ\"ל ואו' די שלא יומשך בלי גבול כו' וד\"ל.\n<b>ומה</b> שא' בלשון די, כי הנה בבחי' הצמצום שקדם להתהוות העולם כבר א' בראשית ברא אלקי'<sup data-n=\"2708\">138</sup> בשם אלקים דוקא המצמצם<sup data-n=\"2709\">139</sup> עצמות האור להיות רק בחי' הארה דהארה לבד כידוע במא' כברייתו ש\"ע ברישא חשוכא<sup data-n=\"2710\">140</sup> כו'. אך זה הצמצום שא' לעולמו די היינו לאחר שמתפשט אור החסד דמקיף העליון שצריך לצמצמו שלא יתפשט יותר מדאי עד שצריך לומר לעולמו די, הנה ודאי שגם הצמצום הזה הבא אחר ההתפשטו' מוכרח שעלה ברצון הקדום בעצמו' המאציל ואח\"כ יצא צמצום זה לידי גילוי מן ההעלם בעולם הנברא יש מאין במה שיש לו גבול ומדה ושיעור כו'. וזהו שא' ברצונו הקדום שיהי' לעולמו די בגבול ומדה כו', שהי' זה הצמצום בעצמותו תחלה באמירה דרצון בהעלם ומזה יצא כח הצמצום להגביל העולם ממש (וכמו שאנו רואי' בכל מציא' בריא' מאין ליש בעולמות הרוחניי' וגם הגשמיי' שהן מוגבלים בתמונתם, ואופן בנין חומרם וצורתם, [כ]ציור בריא' דאדם ובהמה בכמה מינים שונים, וכן ציור הצומח ודומם בכל מיניהם, וכך בציור החיות ואופני' ושרפי' כמ\"ש כי הוא ציוה ברצונו הקדום ונבראו<sup data-n=\"2711\">141</sup> ממילא בצמצום ציור ותמונה כמו גם בשמים וארץ וכל אשר בהם לא יוסיף ולא יגרע כו') (ואע\"פ שאו' ברוך שאמר והי' העולם<sup data-n=\"2712\">142</sup> שזהו אמירה דחסד ורב טוב שברצון הקד[ו]ם, עכ\"ז כלול עמו בחי' הדין וצמצום בחסד זה עצמו במה שא' לעולמו די בכלל ובפרט בכל עולם וכל מציאות רוחני וגשמי וד\"ל). וזהו פי' די שהיו\"ד הוא הצמצום שאחר ההתפשטו' דעולם שיהי' די להתפשטותו, והוא יו\"ד שאחר הדלי\"ת, שהד' הוא התפשטו' דאורך ורוחב וצמצום דיו\"ד מצמצמו בגבול ומדה לפי הצריך ולא יותר (וזהו פי' דשם שדי, דשי\"ן הוא ג' קוין דחכ' במל' ודלי\"ת הוא התפשטו' דמל' ויו\"ד שאחריו הוא בחי' חיבור יסוד שבמל' שנק' יו\"ד זעירא שא' לעולמו די שכלול מחו\"ג יחד וד\"ל).",[["2708","138","<b>בראשית ברא אלקי'</b>: בראשית א, א."],["2709","139","<b>אלקים. . המצמצם</b>: נסמן לעיל לד, ד."],["2710","140","<b>כברייתו ש\"ע ברישא חשוכא</b>: שבת עז, ב (כגי' רש\"י)."],["2711","141","<b>כי הוא ציוה. . ונבראו</b>: תהלים קמח, ה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380823\" data-slug=\"likkutei-torah\" data-id=\"4001380823\">לקו\"ת ראה כו, ד</a>. ש\"א סט, רע\"א ובהערה 1. מאמרי אדה\"א במדבר ח\"ב ע' תריט."],["2712","142","<b>ברוך שאמר והי' העולם</b>: נוסח ברוך שאמר."]]],[2300540432,"<span data-k=\"pg\">184</span> ּ<b>וזהו</b> שא' וארא אל אברהם כו' שכאשר הי' צריך להיות בחי' גילוי דשם הוי' בנשמת האבות להיות בחי' מרכבה כנ\"ל, הי' ע\"י בחי' הממוצע דאל שדי דוקא שהוא המצמצם לאור מקיף דחסד עליון ואו' לעולמו די. וכך הי' באבות כשהי' השכינה שורה עליהם בבחי' מקיף כנ\"ל, ועי\"ז הי' ביכולת האבות להיות מרכבה עליונה להעלות מ\"ן ולהמשיך מ\"ד עד שיהי' תמיד אתעדל\"ע באצי' מאתעדל\"ת שלהם כנ\"ל וד\"ל. ובכ\"ז יובן מ\"ש הללוהו בגבורותיו<sup data-n=\"2713\">143</sup> ואח\"כ הללוהו כרוב גודלו ולא כגודל גדלו כו', לפי שע\"י בחי' גבורות וצמצומי' דשם שדי הנ\"ל באור החסד העליון הוא שיכול לבא אח\"כ לבחי' גדולה והתפשטות רבות בריבוי אופנים שונים באופן בנין בית והיכל שהוא בנין דחסד כמ\"ש עולם חסד יבנה כנ\"ל, ואם לא בחי' גבורות וצמצום הזה שא' לעולמו די כנ\"ל, לא הי' יכול לבוא המשכת חסד העליון מאור א\"ס עצמו שבאצי' ביריד' והתחברות כ\"כ למטה להתמשך בציור אופן בנין בית והיכל שנק' מקיפים לנשמות ומלאכים, וכנ\"ל במקיף העליון [ב]נשמת אברהם וכה\"ג וע\"כ א' וארא כו' באל שדי דוקא כנ\"ל. וז\"ש הללוהו בגבורותיו בבחי' הצמצומי' שא' לעולמו די ואח\"כ הללוהו כרוב גודלו שגדולה וחסד העליון בא בריבוי חלקי' בשיעור ומדה כפי הצריך לבנין העולמות וההיכלות ולא יותר כנ\"ל וד\"ל.\n<b>והנה</b> כדוגמא זו שא' וארא אל כו' יש ג\"כ עכשיו בכל נשמה בפרט כמ\"ש ואהבת את ה' כו', דפי' ואהבת הוא פועל יוצא לפעול ולהמשיך למעלה התעוררו' אה\"ר בעצמו' א\"ס שתצא מן ההעלם דעצמו' לידי גילוי להיות בבחי' מקיף על הנשמה כמו וימינו תחבקני (או כמ\"ש ה' צלך<sup data-n=\"2714\">144</sup> על יד ימינך וכה\"ג). והיינו לאהבה את הוי' שיפעול למעלה אה\"ר להביא לגילוי אור דשם הוי' בגילוי אהבה עליונה למטה, אך בפסוד\"ז עד ק\"ש היינו רק התעוררות שלמטה בנשמות שמתפעלי' באהבה מפני השגות גדולת ה' בשיר ושבח שמשבחי' ברוממו' אל בגרונם כו', עד ברכת אה\"ע אהבתנו שהוא אה\"ר העליונה שבאה על הנשמה בבחי' מקיף עד הבוחר בעמ\"י באהבה, ואז יכול לומר בק\"ש ואהבת את ה' כו' שיומשך עליו אה\"ר העליונה מן ההעלם לגילוי ממש, ונק' היכל אהבה<sup data-n=\"2715\">145</sup> עליונה דאצי' [או היכל החסד<sup data-n=\"2716\">146</sup> דאצי' כו' כידוע וד\"ל (ובאמת ויציב שהוא היכל הרצון<sup data-n=\"2717\">147</sup> כידוע שיש כח ועוז באהב' העליונ' דאצי'] כמים הפא\"פ<sup data-n=\"2718\">148</sup> כו' לאמת לאמיתי' דאהבה התחתונה שבאדם שיהי' כמו האמת דאהבה האלקי' העליונה באמרו אמת ויציב כו'",[["2713","143","<b>הללוהו בגבורותיו</b>: תהלים קנ, ב. ראה גם מאמרי אדה\"א נ\"ך ע' מו. וש\"נ."],["2714","144","<b>ה' צלך</b>: נסמן לקמן הערה 283."],["2715","145","<b>היכל אהבה</b>: ראה פע\"ח (שער הק\"ש) ש\"ח, פ\"ד. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ."],["2716","146","<b>היכל החסד</b>: ראה סידור האריז\"ל במקומו."],["2717","147","<b>ובאמת ויציב. . היכל הרצון</b>: ראה פע\"ח (שער הק\"ש) ש\"ח, פכ\"ז. מאמרי אדה\"א דברים ח\"ב ע' תז. וש\"נ."],["2718","148","<b>כמים הפא\"פ</b>: ע\"פ משלי כז, יט."]]],[2300540452,"ומתוקן כמו יציבא מילתא<sup data-n=\"2719\">149</sup> כו', שמאמת לאמת הראשון והוא בחי' בירור שני דנשמות בעלייתם באצי' שנק' קשור' דנשמתי'<sup data-n=\"2720\">150</sup> והן ט\"ו ווי\"ן<sup data-n=\"2721\">151</sup> דאמת ויציב שבווין תתקטר<sup data-n=\"2722\">152</sup> כו' כמ\"ש במ\"א וד\"ל).\n<b>ושמי</b> הוי' לא נודעתי להם, פי' קאי אדסמיך לי' שא' אני הוי' דהיינו שם אלקים הוא שם הוי' ביחוד גמור כנ\"ל, ובזה היחוד דשם הוי' ואלקי' הוא שנתגלה לאבות. וז\"ש וארא אל אברהם כו' ע\"י בחי' הממוצע דאל שדי כנ\"ל, אך עכ\"ז ושמי הוי' לא נודעתי להם דהיינו שמי הוי' הפנימי' והעצמי' שלמעלה מעלה גם מבחי' היחוד דהוי' ואלקים הנ\"ל לא נודעתי להם כלל. והענין הוא לפי שכל שמבואר למעלה בענין יחוד זה דהוי' ואלקי' הכל הוא בבחי' אור ההשפעה והמשכה מאור א\"ס ב\"ה ע\"י שם הוי' באלקי' בהתפשטו' גדולתו כו' עד למטה מטה בעולמות העליוני' שע\"ז א' מה גדלו מעשיך ה' כו' <span data-k=\"pg\">צב</span> ּ ועד עולמות התחתוני' שע\"ז א' מה רבו מעשיך ה' כו' כנ\"ל באריכות, אבל<sup data-n=\"2723\">153</sup> זה אינו רק בחי' התפשטו' דשם הוי' באלקי' כו', וז\"ש אני הוי' שמתגלה למטה בשם אלקי' בשביל להיות מקור חיות כל העולמות כו', אבל שמי הוי' העצמי ממש כמו שהוא ית' לבדו בעצמותו למעלה מעלה מבחי' התפשטות והשתלשלו' בקו\"ח כו' באו\"כ ואותיות וצירופי' כו', לא נודעתי גם לאבות אע\"פ שהן המרכבה ממש כנ\"ל, לפי שהן הן כל התו\"מ שניתן לישראל למטה שהן בשרשם בפנימי' דשם הוי' דוקא שנק' שמי הוי' ממש. וביאור הענין ידוע בשרש המצות שהן בבחי' פנימי' דרצה\"ע ממש כמו שהוא בפנימי' ועצמו' דא\"ס שנק' פנימי' רצונותיו (שלמעלה הרבה גם מרצונו הפשוט להאציל או\"כ ע\"י הקו\"ח כו'), והיינו כמו שהמצות הן בעצמותו ית' שנק' מצות הוי'<sup data-n=\"2724\">154</sup> ממש, וכן אנו או' אשר קדשנו במצותיו<sup data-n=\"2725\">155</sup> כו', שנק' מצותי וחוקתי<sup data-n=\"2726\">156</sup> כו' (למעלה גם מבחי' רמ\"ח אברים דמלכא<sup data-n=\"2727\">157</sup> שהן רק או\"כ דאצי', אלא הן באור א\"ס עצמו רק שנמשך בבחי' הלבשה ומקיף על אדם העליון דאצי' שהוא בחי' ז\"א, כידוע ומבואר במ\"א בענין מה שא' שהקב\"ה שהוא בחי' ז\"א<sup data-n=\"2728\">158</sup> דאצי' מניח תפילין<sup data-n=\"2729\">159</sup> בראשו כו' ותפילין דמארי עלמא<sup data-n=\"2730\">160</sup> מאי כתי' בהו ומי כעמך ישראל<sup data-n=\"2731\">161</sup> גוי אחד בארץ, וכה\"ג מתעטף בטלית<sup data-n=\"2732\">162</sup> ועושה צדקה<sup data-n=\"2733\">163</sup> ועוסק בתורה<sup data-n=\"2734\">164</sup> וגמ\"ח<sup data-n=\"2735\">165</sup> וגם [ב]ביקור חולים שביקר לא\"א<sup data-n=\"2736\">166</sup> כו' וכה\"ג וד\"ל), וזהו שנק' שמי הוי' שבעצמותו ית' ממש. וזהו שא' בזהר עמ\"ש מה יתרון לאדם<sup data-n=\"2737\">167</sup> בכל עמלו שיעמול תחת השמש דוקא אבל שאני עמלא דאוריי' דלעילא מן",[["2719","149","<b>אמת ויציב. . יציבא מילתא</b>: דניאל ו, יג. ראה גם לעיל פ' שמות לח, ב. וש\"נ."],["2720","150","<b>קשור' דנשמתי'</b>: ראה גם לקמן פ' תרומה שו, א. שט, ג. ויקהל תמא, ג. שע\"ת סא, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680344\" data-slug=\"torat-chaim\" data-id=\"2300680344\">תו\"ח וישב רי, ב</a> הערה 16."],["2721","151","<b>ט\"ו ווי\"ן</b>: ראה פע\"ח (שער הק\"ש) ש\"ח, פכ\"ח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680334\" data-slug=\"torat-chaim\" data-id=\"2300680334\">תו\"ח וישב רי, א</a> הערה 14."],["2722","152","<b>שבווין תתקטר</b>: זמירות לליל שבת [אזמר בשבחין]."],["2723","153","<b>אבל</b>: בה: שכל."],["2724","154","<b>מצות הוי'</b>: ויקרא ד, ב. יג. כב. ועוד."],["2725","155","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות. ראה גם לקמן פ' בשלח קעו, א."],["2726","156","<b>מצותי וחוקתי</b>: מלכים-א יא, לד. תולדות כו, ה."],["2727","157","<b>רמ\"ח אברים דמלכא</b>: נסמן לעיל מו, ב הערה 123."],["2728","158","<b>שהקב\"ה. . ז\"א</b>: נסמן לעיל נד, ג."],["2729","159","<b>שהקב\"ה. . מניח תפילין</b>: נסמן לעיל נו, ד."],["2730","160","<b>ותפילין דמארי עלמא</b>: ברכות ו, א."],["2731","161","<b>ומי כעמך ישראל</b>: נסמן לעיל נו, ד."],["2732","162","<b>מתעטף בטלית</b>: נסמן לעיל ז, ד."],["2733","163","<b>ועושה צדקה</b>: ירמי' ט, כג. ראה תדא\"ז פ\"א. לקמן סט, ד."],["2734","164","<b>ועוסק בתורה</b>: ע\"ז ג, ב."],["2735","165","<b>וגמ\"ח</b>: סוטה יד, א."],["2736","166","<b>[ב]ביקור חולים שביקר לא\"א</b>: סוטה יד, א."],["2737","167","<b>מה יתרון לאדם</b>: קהלת א, ג. ראה זהר ויחי רכג, ב."]]],[2300540472,"שמשא הוא כו', וביאור הדברים ידוע בפי' כי שמש ומגן<sup data-n=\"2738\">168</sup> הוי' אלקים דהוי' נק' שמש ואלקי' הוא מגן ונרתק לשם הוי' כידוע, ובחי' העמל שתחת השמש זהו לעשות היחוד בהוי' ואלקים כנ\"ל כמו שהיו האבות עושים יחוד עליון זה תמיד ע\"י שם שדי כו' כנ\"ל, וע\"ז א' מה יתרון לאדם בעמלו ש[יעמול] תחת השמש שאין זה רק לשפע העולמות כנ\"ל, אבל עמלא דאורייתא שהן קיום התו\"מ שלנו לעילא מן שמשא הוא והיינו בחי' שמי הוי' שם עצמותו<sup data-n=\"2739\">169</sup> ית' ממש, כמו מצות הוי' דתפילין שלנו שהן כתפילין דמארי עלמא כו' (ולא כמו עובדא דיעקב במקלות שפצל<sup data-n=\"2740\">170</sup> כו' דאע\"פ שהי' בכוונה א' באותו יחו\"ע דתפילין כמ\"ש בזהר, עכ\"ז אין בו מצות הוי' שבעצמו' ממש רק בתפילין שלנו דוקא. וכה\"ג בכל המצות שקיימו האבות ברוחני' דאצי', כאברהם שקיים כל התו\"מ שברוחניות<sup data-n=\"2741\">171</sup> כידוע, עכ\"ז שמי הוי' [ד]עצמו' לא הי' בזה רק במצות גשמיו' שניתנו לנו במ\"ת דוקא, לפי ששרשם מתרי\"ג ארחין<sup data-n=\"2742\">172</sup> וי\"ג חוורתי<sup data-n=\"2743\">173</sup> דע\"י שהן באוא\"ס עצמו, שע\"כ א' דוד רחבה מצותך מאד<sup data-n=\"2744\">174</sup> בבחי' א\"ס עצמו ממש, שזה לא נודעתי לאבות כ\"א במ\"ת, שא' אנכי שרש רמ\"ח<sup data-n=\"2745\">175</sup> ולא יהי' לך שרש שס\"ה ל\"ת בגשמיות דוקא ואז הי' גילוי פנימי' דשם הוי' העצמי כמ\"ש פב\"פ דיבר ה' עמכם<sup data-n=\"2746\">176</sup>, אבל לאבות שמי הוי' לא נודעתי להם) וד\"ל.\n<b>ואחר</b> כ\"ז יובן ענין התשובה על שאלת משה למה הרעות לעם הזה כו' מה זו תשובה לזה במ\"ש וארא אל אברהם כו', דהנה ידוע בענין והחיות רו\"ש<sup data-n=\"2747\">177</sup> כו' דלפ\"ע בחי' הרצוא מלמטה למעלה כך ערך בחי' השוב מלמעלה למטה דרוח אייתי רוח<sup data-n=\"2748\">178</sup> כו'. דאם בחי' הרצוא מלמטה למעלה הוא בבחי' ההסתלקות והעלי' למעלה מעלה ביותר, ודאי כן לפ\"ע יהי' בחי' הירידה וההמשכה דבחי' שוב מלמעלה מעלה ממקום ומדרג' העליונה <span data-k=\"pg\">186</span> ּ וגבוה ביותר ברוממות העליון ביותר (וכמ\"ש במ\"א בענין והנה אנחנו מאלמים אלומים והנה קמה אלומתי<sup data-n=\"2749\">179</sup> כו' שהעלאת מ\"ן דיוסף צ\"ע הי' למעלה יותר ע\"כ הי' המשכתו מלמעלה מעלה יותר, כענין שמים לרום<sup data-n=\"2750\">180</sup> וארץ לעומק שמעמ\"ת יותר יעלה לעמ\"ר יותר כו' וממקום שעלה לשם משם",[["2738","168","<b>כי שמש ומגן</b>: תהלים פד, יב. ראה שהיחוה\"א פ\"ד. מאמרי אדה\"א דברים ח\"ב ע' ת. נ\"ך ע' שצה ובהנסמן בהנ\"ל. לקמן פ' יתרו רעא, א."],["2739","169","<b>שם עצמותו</b>: ה: שבעצמותו."],["2740","170","<b>עובדא דיעקב במקלות שפצל</b>: ויצא ל, לז-ח. זהר (ס\"ת) ויצא קסב, א. מאמרי אדה\"ז תקס\"ב ח\"א ע' יב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670576\" data-slug=\"torat-chaim\" data-id=\"2300670576\">תו\"ח בראשית מה, ד</a> הערה 45."],["2741","171","<b>המצות. . שברוחניות</b>: ראה יומא כח, ב. לעיל נו, ג. לקמן פ' בשלח קנב, א. קנה, ד. קסט, סע\"ג ואילך. קעה, ג. קעו, א. יתרו רנז, ג. משפטים רפה, ג. שא, ג. ויקהל תכב, ג. מאמרי אדה\"א שמות ח\"א ע' פח. ויקרא ח\"א ע' נח ובהנסמן בהנ\"ל. ש\"א לט, ב. מט, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670306\" data-slug=\"torat-chaim\" data-id=\"2300670306\">תו\"ח לך פד, ג</a> ובהערה 27."],["2742","172","<b>מתרי\"ג ארחין</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, א."],["2743","173","<b>וי\"ג חוורתי</b>: ראה זהר שם קכח, ב."],["2744","174","<b>רחבה מצותך מאד</b>: תהלים קיט, צו. ראה גם מאמרי אדה\"א בראשית ע' מג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670576\" data-slug=\"torat-chaim\" data-id=\"2300670576\">תו\"ח בראשית מה, ד</a> ובהערה 39. לקמן פ' בשלח קנו, ד. משפטים שא, א."],["2745","175","<b>אנכי שרש רמ\"ח </b>[אגד ניתוסף: מ\"ע]: נסמן לעיל יז, ג הערה 722."],["2746","176","<b>פב\"פ דיבר ה' עמכם</b>: ואתחנן ה, ד."],["2747","177","<b>והחיות רצו\"ש</b>: יחזקאל א, יד."],["2748","178","<b>דרוח אייתי רוח</b>: ראה זהר תרומה קסב, ריש ע\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשג. מאמרי אדה\"א בראשית ע' רל. וש\"נ."],["2749","179","<b>והנה אנחנו. . אלומתי</b>: וישב לז, ז [בדילוג]. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קטו (נוסחא שני')."],["2750","180","<b>שמים לרום</b>: משלי כה, ג. ראה גם מאמרי אדה\"א בראשית ע' רסח. וש\"נ."]]],[2300540490,"ימשך. וראי' מגלות זה האחרון שהעלי' למעלה ביותר דקוב\"ה בגלותא אסתלק לעילא לעילא<sup data-n=\"2751\">181</sup> כו' ע\"כ יהי' הירידה והמשכה בגילוי אור בימות המשיח ממקום העליון ביותר<sup data-n=\"2752\">182</sup> כידוע) (ושרש הענין ידוע בשרש בחי' רו\"ש שזהו מן המקבל אל המשפיע, ושרשו מלמעלה למטה מן המשפיע אל המקבל נק' מטי ולא מטי<sup data-n=\"2753\">184</sup><sup data-n=\"2754\">183</sup> כמ\"ש בע\"ח, והוא כמו ורוח אלקי' מרחפת כו' נוגע ואינו נוגע<sup data-n=\"2755\">185</sup> כו', שזהו בבחי' המקיף על הפנימי שנוגע ואינו נוגע כו'. שיש ג\"כ במשפיע אל המקבל התפשטו' והסתלקות, ולפ\"ע הירידה בבחי' מטי תחלה כך ערך העליה והסתלקות דלא מטי, כמו הנשימה בחוטם<sup data-n=\"2756\">186</sup> בב' נקבים שתחלה מתפשט ויורח<sup data-n=\"2757\">187</sup> בנקב א' בחוטם בשינה ומיד חוזר ומסתלק, אבל בדפיקו דליבא<sup data-n=\"2758\">188</sup> נהפך הוא שתחלה מסתלק ברצוא ואח\"כ מתיישב בבחי' שוב, ורוח שבלב מרכבה לגבי נשמה<sup data-n=\"2759\">189</sup> שבמוח ומבחי' רו\"ש העולה מן הלב נמשך הנשמה בחוטם ואף בבחי' מולמ\"ט, ולפ\"ע העלא' דרו\"ש כן הוא ערך הירידה דמולמ\"ט דמקיף דנשמה מלמעלה למטה וד\"ל). ובזה יובן כל עיקר ענין הטעם שהיו ישראל בגלות מצרים בחו\"ל בעב\"ק<sup data-n=\"2760\">190</sup> כ\"כ אע\"פ שלא חטאו כלל כנ\"ל, לפי שכל עלי' גורם ירידה לפ\"ע כנ\"ל, ולפ\"ע המדרג' הגבוה שיהי' בירידה והמשכה מלמעלה מעומ\"ר כו' למטה בבחי' שוב כך לפ\"ע צ\"ל בתחלה בחי' הרצוא מעמ\"ת ביותר כנ\"ל. וע\"כ כאשר ישראל היו צריכי' לבא למעלת קבלת התורה פב\"פ ממדריגה הגבוה מאד נעלה כידוע בבחי' שוב מרוממות הא\"ס עצמו באמרו אנכי כו' שאנכי<sup data-n=\"2761\">191</sup> כו', לזאת היו צריכים להיות תחלה בגלות מצרים בעמ\"ת דנש\"ט<sup data-n=\"2762\">192</sup> בגלות קשה בחו\"ל כו', כדי שיצעקו אל ה' בצר להם בבחי' רצוא והסתלקות בכלות הנפש ממש כמ\"ש ותעל שוועתם<sup data-n=\"2763\">193</sup> אל האלקי' כו'. וזה הי' מוכרח להיות שבלא זה לא היו יכולים להגיע למדרג' קבלת התורה דלפום צערא אגרא<sup data-n=\"2764\">194</sup> וכמ\"ש ג' דברים באי' ע\"י יסורים<sup data-n=\"2765\">195</sup> תורה וא\"י ועוה\"ב, תורה באמצעית גלות מצרים ע\"י יסורים קשים בחו\"ל כו', וא\"י ע\"י היסורים שבמדבר מ' שנה דכתי' ויענך וירעיבך<sup data-n=\"2766\">196</sup> כו', והעוה\"ב ע\"י הגלות הארוך כו' (וכל הגבוה גבוה במעלה יותר צ\"ל תחלה צער ועינוי יותר, בגלות מצרים רק רד\"ו שנה<sup data-n=\"2767\">197</sup> לפני מ\"ת, וא\"י למעלה ממ\"ת שהוא קיום התו\"מ,",[["2751","181","<b>דקוב\"ה בגלותא. . לעילא</b>: נסמן לעיל לט, א."],["2752","182","<b>ממקום העליון ביותר</b>: ראה גם לעיל פ' שמות א, ג ובהערה 46."],["2753","184","<b>מטי ולא מטי</b>: נסמן לעיל מא, א."],["2754","183","<b>רו\"ש. . מטי ולא מטי</b>: ראה ש\"א עח, ב: שהרי זהו הכלל. ביאוה\"ז אחרי עז, א-ב. מאמרי אדה\"א קונטרסים ע' רפו ואילך. וע' תמב. לקמן רלח, ד. שכא, ב."],["2755","185","<b>ורוח. . נוגע ואינו נוגע</b>: בראשית א, ב. ראה ב\"ר פ\"ב, ד. רש\"י האזינו לב, יא."],["2756","186","<b>הנשימה בחוטם</b>: ראה גם סידור שער התפילין ט, ב ואילך. אמ\"ב שם קכד, א."],["2757","187","<b>ויורח</b>: בה: ויורד."],["2758","188","<b>בדפיקו דליבא</b>: ראה גם מאמרי אדה\"א בראשית ע' שלח. שמות ח\"ב ע' תמג ואילך. ובהנסמן בהנ\"ל."],["2759","189","<b>ורוח. . לגבי נשמה</b>: ראה זהר לך פג, ב."],["2760","190","<b>בחו\"ל בעב\"ק</b>: בחומר ולבנים בעבודה קשה."],["2761","191","<b>אנכי כו' </b>[בה: מי]<b> שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. אב\"ע תולדות כז, יט. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["2762","192","<b>מצרים. . דנש\"ט</b>: נסמן לעיל מא, ד."],["2763","193","<b>ותעל שוועתם</b>: שמות ב, כג."],["2764","194","<b>דלפום צערא אגרא</b>: אבות ספ\"ה. ולגי' אדה\"ז בסידורו מכ\"א."],["2765","195","<b>ג' דברים. . יסורים</b>: ראה גם לעיל ו, ג. וש\"נ."],["2766","196","<b>ויענך וירעיבך</b>: עקב ח, ג."],["2767","197","<b>מצרים רק רד\"ו שנה</b>: נסמן לעיל א, ג."]]],[2300540508,"ועוה\"ב למעלה מא\"י ע\"כ הגלות מתארך ביותר כו' כמשי\"ת). ובזה יתורץ לכאורה ענין התשובה על שאלת משה למה הרעות כו', דבשביל שיוכלו לקבל משמי הוי' שבתו\"מ במ\"ת פב\"פ שלא נודעתי לאבות שהוא מדרגה גבוה ביותר מפנימי' ועצמו' דאוא\"ס ממש כנ\"ל, ע\"כ צריכים להיות בבחי' הרצוא תחלה לפ\"ע השוב, והוא בגלות דמצרים שירע להם ביותר דלפום צערא אגרא כו', וז\"ש וארא אל אברהם כו' ושמי הוי' לא נודעתי להם כו' שזהו תשובה על למה הרעות כו' וד\"ל.\n<b>אך</b> עדיין אין זה מתיישב דבשביל זה לא הי' מוכרח שיבאו בגלות מצרים דוקא והי' יכול להביא עליהם צער ויסורים בלא גלות בעבודה קשה כו'. ועוד דלא הי' <span data-k=\"pg\">צג</span> ּ צ\"ל [רק] בחי' רצוא ולא יסורי' בגלות כו'. אך הנה יש להקדים תחלה ענין א' והוא מ\"ש רם על כל גוים ה'<sup data-n=\"2768\">198</sup> כו', ויש להבין למה על גוים דוקא הוא רם כו', אך הענין הוא משום דא\"א שיומשך אור האלקי בגוים בגילוי או\"פ רק מרחוק ה' נראה עליהם<sup data-n=\"2769\">199</sup>, וקרו לי' אלקא דאלקייא<sup data-n=\"2770\">200</sup> כו', להיותו הוא ית' רם ומתנשא מהם בבחי' מקיף ברוממות העליון ע\"כ גם למטה רם ומתנשא אצלם כו', לפי שהן מקבלי' שרש חיותם מבחי' הרוממות דבחי' מקיף העליון כמו שהוא ית' רם ברוממו' העצמות טרם שמצמצם א\"ע ביריד' והשתלשלו' דאו\"פ בכלי, שאין ע\"ש<sup data-n=\"2771\">201</sup> יכולים לקבל משם בגילוי משום שנא' וכבודי לאחר לא אתן<sup data-n=\"2772\">202</sup> כו'. רק מבחי' המקיף העליון ששם יכולים לקבל משום ששם נא' וגם חשך לא יחשיך ממך כחשיכה כאורה<sup data-n=\"2773\">203</sup> ממש שוין<sup data-n=\"2774\">204</sup>, כידוע במה שביקש משה<sup data-n=\"2775\">205</sup> שלא תשרה שכינה באוה\"ע כו', לפי שמצד בחי' רוממו' העצמו' יכול להשרות שכינה גם בחשך כמו באור, וראי' מנבוא' בלעם<sup data-n=\"2776\">206</sup> וממה שדיבר אל הנחש<sup data-n=\"2777\">207</sup> כו' וממה שנק' מלך הגוים<sup data-n=\"2778\">208</sup> בזמן הגלות כו', לפי שנבדל הוא בערך מכל ההשתלשלו' (וע\"כ איוב שהי' מאוה\"ע<sup data-n=\"2779\">209</sup> א'<sup data-n=\"2780\">210</sup> אם צדקת מה תתן לו ואם רבו<sup data-n=\"2781\">211</sup> פשעיך מה תעשה לו כו' וד\"ל). ולפי\"ז לא הי' יכול להיות בחי' השפעה פנימי' ועצמיות מיוחדת לישראל לבדם כמו במ\"ת דכתיב פב\"פ כו', מאחר שבבחי' רוממו' העצמו' הכל שוין שם חשך ואור סט' דקדושה עם כו'. אך זה הי' עיקר ענין גלות ישראל במצרים שיהיו משועבדים תחת שר של מצרים שאז הוא ית' ברוממו'",[["2768","198","<b>רם על כל גוים ה'</b>: תהלים קיג, ד. ראה גם לקמן פ' בשלח קלה, א."],["2769","199","<b>מרחוק ה' נראה עליהם</b>: ע\"פ ירמי' לא, ב."],["2770","200","<b>וקרו לי' אלקא דאלקייא</b>: מנחות בסופה."],["2771","201","<b>ע\"ש</b>: נסמן לעיל לז, ג."],["2772","202","<b>וכבודי לאחר לא אתן</b>: ישעי' מב, ח. מח, יא."],["2773","203","<b>וגם חשך. . כאורה</b>: תהלים קלט, יב [בדילוג. ושם: גם — ראה לקמן עו, ב. פ' בא קכג, א. בשלח קנד, א. קסו, ג. קצא, ד. רכט, ד. מאמרי אדה\"א שמות ח\"ב ע' שלה. דברים ח\"ג ע' תתצב ובהנסמן בהנ\"ל. ש\"א מג, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680119\" data-slug=\"torat-chaim\" data-id=\"2300680119\">תו\"ח ויחי רמא, א</a> הערה 1]."],["2774","204","<b>כחשיכה כאורה ממש שוין</b>: ראה סידור סדר הגדה רצז, רע\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380124\" data-slug=\"likkutei-torah\" data-id=\"4001380124\">לקו\"ת צו יב, א</a>. עט\"ר דרוש לעשי\"ת ע' נא."],["2775","205","<b>שביקש משה</b>: נסמן לעיל לא, א."],["2776","206","<b>מנבואת בלעם</b>: ראה גם לעיל שם."],["2777","207","<b>שדיבר אל הנחש</b>: בראשית ג, יד."],["2778","208","<b>מלך הגוים</b>: ירמי' י, ז."],["2779","209","<b>איוב שהי' מאוה\"ע</b>: ב\"ב טו, א-ב. ירושלמי סוטה ספ\"ה. כד הקמח מערכת גר (ע' קיג). ס' יוחסין מאמר ראשון מערכת משה בסופה (ע' 6). פיסקא הבאה. מאמרי אדה\"ז שבהערה הבאה."],["2780","210","<b>איוב. . א'</b>: כ\"ה גם בפיסקא הבאה. מאמרי אדה\"ז על פרשיות התורה ח\"א כאן ע' רל. ובאיוב [שבהערה הבאה] שזה מדברי אליהו[א]. — ראה אודותיו ב\"ב שם. רש\"י תוס' והגהות יעב\"ץ לשם. רי\"ף לע\"י שם. ירושלמי סוטה שם. ר\"ח ורש\"י לע\"ז ג, א. יל\"ש וילקוט המכירי ישעי' מג, ט [רמז תנד]. עמ\"ה (שער או\"א) שי\"ג פל\"ה (עה, ב)."],["2781","211","<b>אם צדקת. . ואם רבו</b>: איוב לה, ז. ו [ושם: ורבו — ראה בפיסקא הבאה. לקמן פ' ויקהל שצב, ב [ושם הוגה מגוכתי\"ק]. מאמרי אדה\"א שמות ח\"ב ע' תרסח. נ\"ך ע' תרא ובהנסמן בהנ\"ל. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680378\" data-slug=\"torat-chaim\" data-id=\"2300680378\">תו\"ח תולדות קנה, ד</a>]."]]]]});
